// ══ THEMES ══
const THEMES = [
  { id:'claro',     label:'☀️ Claro',       dark:false,
    bg:'#f0f4f8', accent:'#2563eb', preview:['#f0f4f8','#ffffff','#2563eb'] },
  { id:'escuro',    label:'🌙 Escuro',       dark:true,
    bg:'#1a1d23', accent:'#3b82f6', preview:['#1a1d23','#22262e','#3b82f6'] },
  { id:'pro',       label:'🚀 Escuro Pro',   dark:true,
    bg:'#0f1117', accent:'#64ffda', preview:['#0f1117','#161b26','#64ffda'] },
  { id:'midnight',  label:'🌌 Midnight',     dark:true,
    bg:'#0d0d0d', accent:'#a78bfa', preview:['#0d0d0d','#141414','#a78bfa'] },
  { id:'contraste', label:'⚡ Alto Contraste', dark:true,
    bg:'#000000', accent:'#ffff00', preview:['#000000','#0a0a0a','#ffff00'] },
];

let _currentTheme = 'claro';

function applyTheme(id) {
  _currentTheme = id;
  const t = THEMES.find(t => t.id === id) || THEMES[0];
  document.documentElement.setAttribute('data-theme', id === 'claro' ? '' : id);
  // Persist
  try { localStorage.setItem('cruzeiro-theme', id); } catch(e) {}
  // Update swatches active state if visible
  renderThemeSwatches();
  // Force Chart.js redraws if any active charts (they read CSS vars on paint)
  try {
    Object.values(Chart.instances || {}).forEach(c => { try { c.update('none'); } catch(e) {} });
  } catch(e) {}
}

function loadSavedTheme() {
  try {
    const saved = localStorage.getItem('cruzeiro-theme');
    if (saved && THEMES.find(t => t.id === saved)) applyTheme(saved);
  } catch(e) {}
}

function renderThemeSwatches() {
  const el = document.getElementById('theme-swatches');
  if (!el) return;
  el.innerHTML = THEMES.map(t => {
    const active = _currentTheme === t.id;
    const [c1, c2, c3] = t.preview;
    return `<button onclick="applyTheme('${t.id}')" title="${t.label}" style="
      display:flex;flex-direction:column;align-items:center;gap:6px;
      background:none;border:none;cursor:pointer;padding:0">
      <div style="
        width:72px;height:52px;border-radius:12px;overflow:hidden;
        border:2px solid ${active ? c3 : 'transparent'};
        box-shadow:${active ? `0 0 0 2px ${c3}44,0 2px 12px rgba(0,0,0,.18)` : '0 1px 4px rgba(0,0,0,.12)'};
        position:relative;transition:all .15s">
        <!-- Base bg -->
        <div style="position:absolute;inset:0;background:${c1}"></div>
        <!-- Card strip -->
        <div style="position:absolute;top:8px;left:6px;right:6px;height:26px;border-radius:6px;background:${c2}"></div>
        <!-- Accent bar -->
        <div style="position:absolute;bottom:0;left:0;right:0;height:6px;background:${c3};opacity:.85"></div>
        ${active ? `<div style="position:absolute;top:4px;right:4px;font-size:11px">✓</div>` : ''}
      </div>
      <span style="font-size:11px;font-weight:${active?700:500};color:var(--text2);white-space:nowrap">${t.label}</span>
    </button>`;
  }).join('');
}

// Load theme immediately on script parse (before DOM ready) to prevent flash
loadSavedTheme();

// Returns a grid-line color appropriate for the current theme
// (Chart.js configs can't use CSS variables directly)
function themeGridColor() {
  const dark = ['escuro','pro','midnight','contraste'].includes(_currentTheme);
  return dark ? 'rgba(255,255,255,.07)' : 'rgba(0,0,0,.05)';
}
function themeZeroLineColor() {
  const dark = ['escuro','pro','midnight','contraste'].includes(_currentTheme);
  return dark ? 'rgba(239,83,80,.5)' : 'rgba(239,83,80,.4)';
}

// ── Plugin Chart.js — Volume / Profundidade ──────────────────────────────
const _chartVolumePlugin = {
  id: 'cruzeiro_volume',

  // Rosca: pinta o canvas com a cor de fundo real do card pai (percorre
  // o DOM até achar o primeiro elemento com fundo não-transparente), para
  // que o buraco da rosca combine exatamente com o fundo do card — sem
  // retângulo visível — tanto no tema claro quanto nos escuros.
  beforeDraw(chart) {
    if (chart.config.type !== 'doughnut' && chart.config.type !== 'pie') return;
    const ctx = chart.ctx;
    ctx.save();
    let bg = null;
    let el = chart.canvas.parentElement;
    while (el && el !== document.body) {
      const c = getComputedStyle(el).backgroundColor;
      if (c && c !== 'rgba(0, 0, 0, 0)' && c !== 'transparent') { bg = c; break; }
      el = el.parentElement;
    }
    if (!bg) bg = getComputedStyle(document.documentElement).getPropertyValue('--bg2').trim() || '#fff';
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, chart.width, chart.height);
    ctx.restore();
  },

  // Pós-draw: sobrepõe gradiente de brilho nas barras e nas fatias de rosca.
  // NÃO usamos ctx.shadow* aqui — Chart.js faz save()/restore() em torno de
  // cada dataset e descarta nossa sombra antes de pintar as barras.
  afterDatasetsDraw(chart) {
    const type = chart.config.type;
    const ctx  = chart.ctx;

    // ── Barras ──────────────────────────────────────────────────────────
    if (type === 'bar') {
      const horiz = chart.options.indexAxis === 'y';
      // Efeito 3D apenas em barras verticais (horizontal tem artefatos visuais)
      if (horiz) return;

      ctx.save();
      // Clip estritamente à área do gráfico — impede que o gradiente
      // vaze para os eixos, legenda ou fora do canvas
      const ca = chart.chartArea;
      ctx.beginPath();
      ctx.rect(ca.left, ca.top, ca.right - ca.left, ca.bottom - ca.top);
      ctx.clip();

      chart.data.datasets.forEach((_, di) => {
        const meta = chart.getDatasetMeta(di);
        if (meta.hidden) return;
        meta.data.forEach(el => {
          if (!el) return;
          try {
            // Barra VERTICAL: el.x=centro X, el.y=topo, el.base=zero, el.width=largura
            const top  = Math.min(el.y, el.base);
            const barH = Math.abs(el.y - el.base);
            const barW = el.width || 0;
            const left = el.x - barW / 2;
            if (barW < 2 || barH < 2) return;
            // Brilho da esquerda pra direita (efeito cilindro iluminado)
            const grad = ctx.createLinearGradient(left, top, left + barW, top);
            grad.addColorStop(0,    'rgba(255,255,255,0.32)');
            grad.addColorStop(0.45, 'rgba(255,255,255,0.06)');
            grad.addColorStop(1,    'rgba(0,0,0,0.10)');
            ctx.fillStyle = grad;
            const rr = Math.min(4, barW / 2, barH / 2);
            ctx.beginPath();
            if (ctx.roundRect) ctx.roundRect(left, top, barW, barH, rr);
            else ctx.rect(left, top, barW, barH);
            ctx.fill();
          } catch(e) {}
        });
      });
      ctx.restore();
    }

    // ── Rosca / Pie ──────────────────────────────────────────────────────
    if (type === 'doughnut' || type === 'pie') {
      ctx.save();
      chart.data.datasets.forEach((_, di) => {
        const meta = chart.getDatasetMeta(di);
        if (meta.hidden) return;
        meta.data.forEach(arc => {
          if (!arc) return;
          try {
            const sa = arc.startAngle, ea = arc.endAngle;
            const ir = arc.innerRadius ?? 0, or = arc.outerRadius ?? 0;
            const cx = arc.x ?? 0, cy = arc.y ?? 0;
            if (Math.abs(ea - sa) < 0.01 || or < 1) return;
            const mid = sa + (ea - sa) / 2;
            const rm  = (ir + or) / 2;
            // Gradiente radial: borda interna escura → meio transparente → borda externa clara
            const gr = ctx.createRadialGradient(cx, cy, ir, cx, cy, or);
            gr.addColorStop(0,   'rgba(0,0,0,0.08)');
            gr.addColorStop(0.5, 'rgba(255,255,255,0.0)');
            gr.addColorStop(1,   'rgba(255,255,255,0.22)');
            ctx.fillStyle = gr;
            ctx.beginPath();
            ctx.arc(cx, cy, or, sa, ea);
            ctx.arc(cx, cy, Math.max(0, ir), ea, sa, true);
            ctx.closePath();
            ctx.fill();
            // Highlight radial localizado no centro de cada fatia
            const hl = ctx.createRadialGradient(
              cx + Math.cos(mid)*rm*0.3, cy + Math.sin(mid)*rm*0.3, 0,
              cx, cy, or
            );
            hl.addColorStop(0,   'rgba(255,255,255,0.20)');
            hl.addColorStop(0.55,'rgba(255,255,255,0.03)');
            hl.addColorStop(1,   'rgba(255,255,255,0.0)');
            ctx.fillStyle = hl;
            ctx.beginPath();
            ctx.arc(cx, cy, or, sa, ea);
            ctx.arc(cx, cy, Math.max(0, ir), ea, sa, true);
            ctx.closePath();
            ctx.fill();
          } catch(e) {}
        });
      });
      ctx.restore();
    }
  },
};

// ══ CATEGORIES ══
// Generic default categories — user can add, edit or remove in Settings
let CATS_RAW = [
  "Alimentação","Alimentação:Restaurante","Alimentação:Supermercado",
  "Casa","Contas","Diversos","Educação","Lazer","Outras Rendas",
  "Presentes","Renda Financeira","Roupas","Salário","Saúde",
  "Saúde:Farmácia","Saúde:Médicos","Tarifas",
  "Transporte","Viagens"
];

// ══ CATEGORY MANAGEMENT ══
async function loadPersistedCategories() {
  try {
    const saved = await ff.categoriesGet();
    if (saved && Array.isArray(saved)) CATS_RAW.splice(0, CATS_RAW.length, ...saved);
  } catch(e) {}
}

async function saveCategories() {
  try { await ff.categoriesSave({ categories: [...CATS_RAW].sort((a,b) => a.localeCompare(b,'pt-BR')) }); }
  catch(e) { console.error('Failed to save categories', e); }
}

function refreshCategories() {
  const el = G('cat-manage-list');
  if (!el) return;
  const sorted = [...CATS_RAW].sort((a,b) => a.localeCompare(b,'pt-BR'));

  // Group by top-level
  const groups = {};
  sorted.forEach(c => {
    const top = c.split(':')[0];
    if (!groups[top]) groups[top] = [];
    groups[top].push(c);
  });

  let html = '';
  Object.entries(groups).sort(([a],[b]) => a.localeCompare(b,'pt-BR')).forEach(([top, cats]) => {
    html += `<div style="background:var(--bg2);border:1px solid var(--border);border-left:4px solid var(--chart-income);border-radius:12px;margin-bottom:10px;overflow:hidden;box-shadow:0 1px 3px rgba(20,30,50,.04)">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:11px 14px;background:var(--green-bg);border-bottom:1px solid var(--border)">
        <span style="font-weight:700;font-size:13px;color:var(--green)">${esc(top)}</span>
        <div style="display:flex;gap:6px">
          <button class="ev-action-btn" style="padding:4px 10px;font-size:11px" onclick="openAddCategory(true,'${esc2(top)}')">+ Sub</button>
          <button class="btn-icon" onclick="openRenameCategory('${esc2(top)}','${esc2(top)}')">✎</button>
          <button class="btn-icon" style="color:var(--red);font-size:11px" onclick="deleteCategory('${esc2(top)}')">✕</button>
        </div>
      </div>`;
    cats.filter(c => c !== top).forEach(c => {
      const sub = c.split(':').slice(1).join(':');
      html += `<div style="display:flex;align-items:center;justify-content:space-between;padding:8px 14px 8px 28px;border-bottom:1px solid var(--border);font-size:13px">
        <span style="color:var(--text2)">${esc(sub)}</span>
        <div style="display:flex;gap:6px">
          <button class="btn-icon" style="font-size:11px" onclick="openRenameCategory('${esc2(c)}','${esc2(c)}')">✎</button>
          <button class="btn-icon" style="color:var(--red);font-size:11px" onclick="deleteCategory('${esc2(c)}')">✕</button>
        </div>
      </div>`;
    });
    html += '</div>';
  });

  el.innerHTML = html || '<div class="info-box">Nenhuma categoria.</div>';
}

function openAddCategory(isSub, parentName) {
  const title = isSub
    ? (parentName ? `Nova subcategoria em "${parentName}"` : 'Nova subcategoria (ex: Alimentação:Restaurante)')
    : 'Nova categoria';
  showCatInputModal(title, '', val => {
    if (!val?.trim()) return;
    const full = (isSub && parentName) ? `${parentName}:${val.trim()}` : val.trim();
    if (CATS_RAW.includes(full)) { toast('Categoria já existe'); return; }
    if (isSub && parentName && !CATS_RAW.includes(parentName)) CATS_RAW.push(parentName);
    CATS_RAW.push(full);
    saveCategories();
    refreshCategories();
    toast(`✅ "${full}" adicionada`);
  });
}

function openRenameCategory(oldName, currentName) {
  showCatInputModal(`Renomear "${currentName}"`, currentName, val => {
    if (!val?.trim() || val.trim() === currentName) return;
    const newFull = val.trim();
    for (let i = 0; i < CATS_RAW.length; i++) {
      if (CATS_RAW[i] === oldName) CATS_RAW[i] = newFull;
      else if (CATS_RAW[i].startsWith(oldName + ':'))
        CATS_RAW[i] = newFull + CATS_RAW[i].slice(oldName.length);
    }
    saveCategories();
    refreshCategories();
    toast(`✅ Renomeada para "${newFull}"`);
  });
}

// Inline text input modal (replaces prompt() which is blocked in Electron)
function _catModalConfirm() {
  const v = G('cat-modal-input')?.value;
  closeModal('modal-custom-parser');
  window._catModalCb?.(v);
}

function showCatInputModal(title, defaultVal, onConfirm) {
  G('custom-parser-title').textContent = title;
  G('custom-parser-body').innerHTML = `<div class="field"><input class="inp" id="cat-modal-input" type="text" value="${esc(defaultVal)}" style="width:100%" placeholder="Nome da categoria" onkeydown="if(event.key==='Enter')_catModalConfirm()"></div>`;
  G('custom-parser-footer').innerHTML = `<button class="btn" onclick="closeModal('modal-custom-parser')">Cancelar</button><button class="btn primary" id="cat-modal-ok">Confirmar</button>`;
  // Attach via JS to avoid HTML attribute escaping issues
  setTimeout(() => {
    const btn = G('cat-modal-ok');
    if (btn) btn.onclick = _catModalConfirm;
  }, 10);
  window._catModalCb = onConfirm;
  openModal('modal-custom-parser');
  setTimeout(() => G('cat-modal-input')?.focus(), 80);
}

async function deleteCategory(name) {
  // Blur active element first to prevent focus trap after confirm dialog
  if (document.activeElement?.blur) document.activeElement.blur();
  const isParent = CATS_RAW.some(c => c.startsWith(name + ':'));
  const msg = isParent
    ? `Excluir "${name}" e todas as suas subcategorias?`
    : `Excluir a categoria "${name}"?`;
  if (!await showConfirmDialog(msg, '', 'Confirmar', true)) return;
  const before = CATS_RAW.length;
  const removed = [];
  // Remove the category and any sub-categories
  for (let i = CATS_RAW.length - 1; i >= 0; i--) {
    if (CATS_RAW[i] === name || CATS_RAW[i].startsWith(name + ':')) {
      removed.push(CATS_RAW[i]);
      CATS_RAW.splice(i, 1);
    }
  }
  saveCategories();
  // Marca como excluída de propósito — sem isso, se alguma transação
  // antiga ainda tiver esse texto literal no campo category (histórico
  // não é reescrito ao excluir), a categoria "fantasma" reaparecia
  // sozinha no próximo boot (reconciliação automática em main.js).
  ff.categoriesExclude({ names: removed }).catch(() => {});
  refreshCategories();
  toast(`🗑 ${before - CATS_RAW.length} categoria(s) removida(s)`);
}

// ══ STATE ══
let accounts    = [];
let currentAccountId = null;
let currentPage = 'overview';
let sortBy      = 'date';
let sortOrder   = 'desc';
let editingTxId = null;
let editingAccId= null;
// Última data usada ao criar um lançamento manual em cada conta — a
// primeira transação de uma conta ainda assume hoje, mas depois que o
// usuário muda a data uma vez, as próximas transações NOVAS nessa mesma
// conta passam a sugerir essa última data (até o usuário mudar de novo).
let _lastTxDateByAccount = {};
let selBank     = 'itau';
let selectedRows= new Set();
let searchQuery = '';
let fxRates     = {};
let periodDays  = 90; // default period

// Column config: id, label, width, visible
let colConfig = [
  { id:'date',     label:'date',      width:100, visible:true },
  { id:'category', label:'category',  width:170, visible:true },
  { id:'memo',     label:'memo',      width:220, visible:true },
  { id:'expense',  label:'expense',   width:110, visible:true },
  { id:'income',   label:'income',    width:110, visible:true },
  { id:'balance',  label:'balance',   width:120, visible:true },
  { id:'cleared',  label:'C',         width:44,  visible:true },
  { id:'actions',  label:'',          width:64,  visible:true },
];

// ── INIT ──
(async () => {
  try {
  await fetchFxRates();
  await loadAccounts();
  await loadOverviewSettings();
  // Check license status on startup (non-blocking)
  setTimeout(() => checkLicense().catch(()=>{}), 2000);
  renderCatFilterChips();
  try { const ver = await ff.appVersion(); const vEl = G('app-version'); if (vEl) vEl.textContent = `v${ver}`; } catch(e) {}
  try { window._importDefaults = await ff.importDefaultsGet(); } catch(e) { window._importDefaults = {}; }
  await loadCatTypes().catch(()=>{});
  await initPatrimonio().catch(()=>{});
  await loadCatTypes();
  // Listen for update notifications from main process
  try {
    ff.onUpdateStatus(data => {
      const bar = G('update-bar');
      const msg = G('update-msg');
      const btn = G('update-install-btn');
      if (!bar) return;
      bar.style.display = 'flex';
      msg.textContent = data.message;
      btn.style.display = data.type === 'ready' ? '' : 'none';
    });
  } catch(e) {}
  try {
    ff.onDbError(data => {
      toast(`⚠️ ${data.message}`);
      console.error('[DB Error]', data.message);
    });
  } catch(e) {}


  // No aggressive focus recovery — it causes more freezes than it fixes

  // Expose installUpdate globally for the update bar button
  window.installUpdate = async function() {
    const btn = G('update-install-btn');
    if (btn) { btn.textContent = '⏳ Aguarde...'; btn.disabled = true; }
    const msg = G('update-msg');
    if (msg) msg.textContent = 'Fechando app e iniciando instalação...';
    try {
      await ff.installUpdate();
    } catch(e) {
      console.error('[update]', e);
      if (btn) { btn.textContent = '↻ Reiniciar e instalar'; btn.disabled = false; }
      if (msg) msg.textContent = 'Erro ao instalar. Tente fechar e abrir o app.';
    }
  };

  // Ctrl+F → open advanced search (override browser default)
  document.addEventListener('keydown', e => {
    if ((e.ctrlKey || e.metaKey) && e.key === 'f') {
      e.preventDefault();
      goPage('search');
      setTimeout(() => G('adv-query')?.focus(), 80);
    }
  });

  // Delete key on document: delete selected transactions
  document.addEventListener('keydown', async e => {
    if ((e.key === 'Delete') && selectedRows.size > 0 && currentPage === 'account') {
      // Don't fire if focus is inside an input
      if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.target.isContentEditable) return;
      e.preventDefault();
      if (!await showConfirmDialog(`Excluir ${selectedRows.size} lançamento(s)?`, 'Esta ação pode ser desfeita com Ctrl+Z.', 'Excluir', true)) return;
      const ids = [...selectedRows];
      for (const id of ids) await ff.deleteTx(id);
      selectedRows.clear(); _selAnchor = null;
      toast(`${ids.length} lançamento(s) excluído(s)`);
      await loadAccounts();
      if (currentPage === 'account') refreshAccount();
      if (currentPage === 'overview') await refreshOverview();
      if (currentPage === 'evolucao') refreshEvolucao();
      refreshUndoBtn();
    }
  });

  // Esc key on document: cancela a seleção de transações (só quando não
  // há modal aberto por cima — nesse caso o Esc já fecha o modal via seu
  // próprio handler local, e não deve também mexer na seleção por baixo).
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && selectedRows.size > 0 && currentPage === 'account') {
      if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.target.isContentEditable) return;
      if (document.querySelector('.overlay.open')) return;
      clearSelection();
    }
  });
  await loadEvolucaoConfig();
  await loadPersistedCategories();
  goPage('overview');

  // Initialize language
  await initLanguage();

  // Auto-update IPCA and benchmarks in background on startup
  setTimeout(async () => {
    try { await patFetchIPCA(); } catch(e) { console.warn('Auto IPCA pat:', e); }
    try { await fetchIPCA();    } catch(e) { console.warn('Auto IPCA ev:',  e); }
    try { await fetchBenchmarks(true); } catch(e) { console.warn('Auto benchmarks:', e); }
    try { await ff.financingFetchIndexes(); } catch(e) { console.warn('Auto financing indexes:', e); }
  }, 1500);

  // Check first run → show tour
  setTimeout(checkFirstRun, 800);

  // Load Chart.js for returns charts
  if (typeof Chart === 'undefined') {
    const s = document.createElement('script');
    s.src = 'https://cdnjs.cloudflare.com/ajax/libs/Chart.js/4.4.1/chart.umd.min.js';
    s.onload = () => {
      // Registra o plugin de volume/3D logo que o Chart.js estiver disponível
      try { Chart.register(_chartVolumePlugin); } catch(e) { console.warn('volume plugin:', e); }
    };
    document.head.appendChild(s);
  } else {
    try { Chart.register(_chartVolumePlugin); } catch(e) {}
  }

  // Load cached benchmarks
  loadBenchmarks();
  setDefaultDates();
  initSidebarResize();
  refreshUndoBtn();
  } catch(e) {
    console.error('[Cruzeiro] Init error:', e);
    // Show error in UI rather than blank screen
    const body = document.body;
    if (body) {
      const errDiv = document.createElement('div');
      errDiv.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:#1e293b;color:#f87171;padding:32px;border-radius:12px;font-family:monospace;max-width:600px;z-index:9999;white-space:pre-wrap';
      errDiv.textContent = 'Erro ao iniciar o Cruzeiro:\n\n' + (e.stack || e.message);
      body.appendChild(errDiv);
    }
  }
})();

function initSidebarResize() {
  const sidebar  = G('sidebar');
  const handle   = G('sidebar-resize');
  if (!sidebar || !handle) return;
  let dragging = false, startX = 0, startW = 0;
  handle.addEventListener('mousedown', e => {
    dragging = true; startX = e.clientX; startW = sidebar.offsetWidth;
    handle.classList.add('dragging');
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
  });
  document.addEventListener('mousemove', e => {
    if (!dragging) return;
    const newW = Math.min(420, Math.max(160, startW + (e.clientX - startX)));
    sidebar.style.width = newW + 'px';
  });
  document.addEventListener('mouseup', () => {
    if (!dragging) return;
    dragging = false;
    handle.classList.remove('dragging');
    document.body.style.cursor = '';
    document.body.style.userSelect = '';
  });
}

function setDefaultDates() {
  const now  = new Date();
  const from = new Date(now.getFullYear(), now.getMonth() - 2, 1);
  G('rep-from').value = from.toISOString().slice(0,10);
  G('rep-to').value   = now.toISOString().slice(0,10);
  G('tx-date').value  = todayStr();
  G('tr-date').value  = todayStr();
  G('rec-next').value = todayStr();
}

// ══ FX RATES ══
async function fetchFxRates() {
  try {
    const r = await fetch('https://open.er-api.com/v6/latest/BRL');
    const d = await r.json();
    if (d.rates) {
      // rates are X per BRL, we want BRL per X
      fxRates.USD = 1 / d.rates.USD;
      fxRates.EUR = 1 / d.rates.EUR;
    }
  } catch(e) {
    // fallback approximate rates
    fxRates.USD = 5.10;
    fxRates.EUR = 5.55;
  }
}

function toBRL(amount, currency) {
  if (!currency || currency === 'BRL') return amount;
  const rate = fxRates[currency] || 1;
  return amount * rate;
}
function fxHint(currency) {
  if (!currency || currency === 'BRL') return '';
  const rate = fxRates[currency] || 0;
  return rate ? `1 ${currency} ≈ ${fmtBRL(rate)}` : '';
}

// ══ ACCOUNTS ══
async function loadAccounts() {
  accounts = await ff.listAccounts();
  renderSidebar();
  populateAccountSelects();
}

const TYPE_ORDER  = { bank:0, credit:1, cash:2, investment:3 };
const TYPE_LABELS = { bank:'Contas bancárias', credit:'Cartões de crédito', cash:'Caixa', investment:'Investimentos' };
const TYPE_ICONS  = { bank:'🏦', credit:'💳', cash:'💵', investment:'📈' };
const CURR_SYMBOL = { BRL:'R$', USD:'US$', EUR:'€' };

function currSymbol(currency) { return CURR_SYMBOL[currency] || currency; }

async function renderSidebar() {
  const balances = {};
  await Promise.all(accounts.map(async a => {
    balances[a.id] = await ff.getBalance(a.id); // raw value in account's own currency
  }));

  const visible = accounts.filter(a => !a.hidden);
  const groups  = {};
  visible.forEach(a => { if (!groups[a.type]) groups[a.type] = []; groups[a.type].push(a); });

  let html = '';
  // Nav
  const navItems = [
    { page:'overview',   icon:'🏠', label:t('nav_overview') },
    { page:'projecao',   icon:'📅', label:'Projeção' },
    { page:'reports',    icon:'📊', label:t('nav_reports') },
    { page:'import',     icon:'📥', label:t('nav_import') },
    { page:'search',     icon:'🔍', label:t('nav_search') },
    { page:'goals',      icon:'🎯', label:t('nav_goals') },
    { page:'aposentadoria', icon:'🏖️', label:'Aposentadoria' },
    { page:'budget',     icon:'💰', label:t('nav_budget') },
    { page:'recurring',  icon:`<svg width="15" height="15" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg" style="display:inline-block;vertical-align:-2px"><path d="M13 8A5 5 0 0 1 3 8" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"/><polyline points="1.5,6.5 3,8 4.5,6.2" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" fill="none"/><path d="M3 8A5 5 0 0 1 13 8" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"/><polyline points="11.5,9.8 13,8 14.5,9.8" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" fill="none"/></svg>`, label:t('nav_recurring') },
    { page:'evolucao',   icon:'📈', label:t('nav_evolucao') },
    { page:'patrimonio', icon:'🏛', label:t('nav_patrimonio') },
    // { page:'irpf', icon:'🧾', label:'Relatório IRPF' }, // desativado a pedido do usuário — precisa de mais testes antes de reativar. Código completo continua no app (funções, página, handlers); só essa entrada de navegação foi removida.
    { page:'categories', icon:'🏷', label:t('nav_categories') },
    { page:'ml',         icon:'🧠', label:t('nav_ml') },
    { page:'backup',     icon:'⚙️', label:t('nav_backup') },
  ];
  navItems.forEach(n => {
    const active = currentPage === n.page && !currentAccountId ? 'active' : '';
    const navLabel = (t('nav_' + n.page) !== 'nav_' + n.page) ? t('nav_' + n.page) : n.label;
    html += `<div class="nav-item ${active}" onclick="goPage('${n.page}')" data-page="${n.page}">
      <span class="icon">${n.icon}</span>${navLabel}
    </div>`;
  });

  // Account groups — strictly sorted by TYPE_ORDER
  const sortedTypes = Object.keys(TYPE_LABELS).sort((a,b) => TYPE_ORDER[a] - TYPE_ORDER[b]);
  sortedTypes.forEach(type => {
    const accs = groups[type];
    if (!accs || !accs.length) return;
    html += `<div class="nav-section">${TYPE_LABELS[type]}</div>`;
    accs.forEach(a => {
      const bal    = balances[a.id] || 0; // in account's currency
      const balCls = bal > 0 ? 'pos' : bal < 0 ? 'neg' : 'zero';
      const sym    = currSymbol(a.currency);
      const absVal = Math.abs(bal);
      const sign   = bal < 0 ? '-' : '';
      const balStr = sign + sym + ' ' + absVal.toLocaleString('pt-BR', {minimumFractionDigits:2, maximumFractionDigits:2});
      const isActive = currentAccountId === a.id && currentPage === 'account';
      const iconHtml = a.bank_slug && BANK_REGISTRY[a.bank_slug]
        ? accountChip(a, { size:'sm', nameVisible:false })
        : `<span class="icon">${TYPE_ICONS[a.type]||'💰'}</span>`;
      html += `<div class="nav-item ${isActive ? 'active' : ''}" onclick="openAccount(${a.id})">
        ${iconHtml}
        <span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px">${esc(a.name)}</span>
        <span class="nav-bal ${balCls}">${balStr}</span>
      </div>`;
    });
  });

  G('sidebar-accounts').innerHTML = html;
}

function populateAccountSelects() {
  const visible = accounts.filter(a => !a.hidden);
  const opts = visible.map(a => `<option value="${a.id}">${esc(a.name)}${a.currency!=='BRL'?' ('+a.currency+')':''}</option>`).join('');
  ['tx-account','tr-from','tr-to','rec-account','qif-account'].forEach(id => {
    const el = G(id); if (el) el.innerHTML = opts;
  });
  // Conta de destino da importação: só contas VISÍVEIS fazem sentido como
  // destino de um extrato novo — igual ao seletor de ajuste de corretora.
  const bankSel = G('bank-account');
  if (bankSel) {
    bankSel.innerHTML = '<option value="">— Selecione a conta —</option>' + opts;
    // Só reaplica o valor lembrado se a conta ainda existir e estiver visível
    // (senão o campo fica preso silenciosamente numa conta que já não existe
    // mais, dando a impressão de que "o app escolheu sozinho" sem mostrar
    // nada pra revisar).
    const def = (window._importDefaults || {})[window._selBank || 'itau'];
    if (def && visible.some(a => String(a.id) === String(def))) {
      bankSel.value = def;
    }
    bankSel.onchange = () => {
      if (!window._importDefaults) window._importDefaults = {};
      window._importDefaults[window._selBank || 'itau'] = bankSel.value;
      ff.importDefaultsSave(window._importDefaults).catch(()=>{});
    };
  }
}

// ══ NAV ══
async function goPage(name) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  G('page-' + name)?.classList.add('active');
  currentPage = name;
  if (name !== 'account') currentAccountId = null;
  try { if (name !== 'patrimonio') patSelClearAll(); } catch(e) {}
  const titles = {
    overview:   t('page_overview'),
    import:     t('page_import'),
    search:     t('page_search'),
    returns:    t('page_returns'),
    goals:      t('page_goals'),
    budget:     t('page_budget'),
    patrimonio: t('page_patrimonio'),
    evolucao:   t('page_evolucao'),
    recurring:  t('page_recurring'),
    ml:         t('page_ml'),
    categories: t('page_categories'),
    backup:     t('page_backup'),
    aposentadoria: '🏖️ Aposentadoria',
    reports:    'Relatórios',
    projecao:   '📅 Projeção de Fluxo de Caixa',
    irpf:       '🧾 Relatório IRPF — Bens e Direitos',
  };
  G('page-title').textContent = titles[name] || name;
  G('search-wrap').style.display = name === 'account' ? 'flex' : 'none';
  G('search-input').value = ''; searchQuery = '';
  renderSidebar();
  clearSelection();
  if (name === 'overview')  refreshOverview();
  if (name === 'ml')        { refreshML(); try { guideMark('visitedMl'); } catch(e) {} }
  if (name === 'recurring')  refreshRecurring();
  if (name === 'evolucao')   refreshEvolucao();
  if (name === 'patrimonio') { patSetView(_patView); refreshPatrimonio(); }
  if (name === 'import') initImportPage();
  if (name === 'categories') { refreshCategories(); try { guideMark('visitedCategories'); } catch(e) {} }
  if (name === 'search') initSearchPage();
  if (name === 'goals')  refreshGoals();
  if (name === 'budget') refreshBudget();
  if (name === 'import')    populateAccountSelects();
  if (name === 'reports')   { await initReportFilters(); onReportTypeChange(); try { guideMark('visitedReports'); } catch(e) {} }
  if (name === 'projecao')  { refreshProjecao(); try { guideMark('visitedProjecao'); } catch(e) {} }
  if (name === 'irpf' && !G('irpf-year').options.length) {
    const curY = new Date().getFullYear();
    const sel = G('irpf-year');
    for (let y = curY - 1; y >= curY - 10; y--) sel.innerHTML += `<option value="${y}">${y}</option>`;
  }
  if (name === 'backup') {
    refreshBackup();
    refreshSyncStatus();
    renderThemeSwatches(); // ← render/refresh theme selector
    // Update license badge in settings
    ff.licenseStatus().then(s => {
      const el = G('settings-lic-status');
      if (!el) return;
      const map = { trial:'🟡 Período gratuito', free_social:'🟢 Gratuito', licensed:'✅ Licenciado', payment_required:'🔴 Licença necessária' };
      el.textContent = map[s.status] || s.status;
      el.style.color = s.status === 'payment_required' ? 'var(--red)' : s.status === 'licensed' ? 'var(--green)' : 'var(--text3)';
    }).catch(()=>{});
    refreshAiKeyStatus();
  }
  if (name === 'aposentadoria') { aposInit(); try { guideMark('visitedApos'); } catch(e) {} }
  // Moedinha: atualiza dicas/badge para a nova página (não bloqueia a navegação)
  try { guideOnPageChange(name); } catch(e) {}
}

// ── AI key management (settings) ──
function aiLink(url) {
  return `<a href="#" onclick="ff.openExternal('${url}');return false;" style="color:var(--accent);text-decoration:underline">${url}</a>`;
}
const AI_PROVIDER_HELP = {
  openrouter: () => `Grátis e sem cartão de crédito. Acesse ${aiLink('https://openrouter.ai/keys')}, crie uma conta e gere uma chave (começa com "sk-or-..."). Usa um roteador de modelos gratuitos por baixo dos panos, de forma estável.`,
  gemini:    () => `⚠️ O Google está emitindo chaves no formato "AQ." para algumas contas, que não funcionam com este tipo de integração (problema atual do Google, não do Cruzeiro). Se sua chave começar com "AQ.", use o OpenRouter acima em vez disso. Caso sua chave comece com "AIza...", ela deve funcionar normalmente. Gere em ${aiLink('https://aistudio.google.com/apikey')}.`,
  openai:    () => `Requer conta com API paga (créditos). Acesse ${aiLink('https://platform.openai.com/api-keys')} e gere uma chave (começa com "sk-...").`,
  anthropic: () => `Requer conta com API paga (créditos). Acesse ${aiLink('https://console.anthropic.com')} e gere uma chave (começa com "sk-ant-...").`,
};
function aiProviderChanged() {
  const prov = G('settings-ai-provider')?.value || 'openrouter';
  const help = G('settings-ai-help');
  const helpFn = AI_PROVIDER_HELP[prov];
  if (help) help.innerHTML = helpFn ? helpFn() : '';
}
async function refreshAiKeyStatus() {
  try {
    const st = await ff.aiGetKeyStatus();
    const statusEl = G('settings-ai-status');
    const clearBtn = G('settings-ai-clear-btn');
    const input    = G('settings-ai-key');
    const provSel  = G('settings-ai-provider');
    if (provSel && st.provider) provSel.value = st.provider;
    aiProviderChanged();
    if (st.hasKey) {
      const provName = { openrouter:'OpenRouter', gemini:'Google Gemini', openai:'OpenAI', anthropic:'Anthropic' }[st.provider] || st.provider;
      if (statusEl) { statusEl.textContent = '✅ ' + provName + ' (' + st.masked + ')'; statusEl.style.color = 'var(--green)'; }
      if (clearBtn) clearBtn.style.display = '';
      if (input) input.placeholder = '•••• chave salva ••••';
    } else {
      if (statusEl) { statusEl.textContent = '⚪ Nenhuma chave configurada'; statusEl.style.color = 'var(--text3)'; }
      if (clearBtn) clearBtn.style.display = 'none';
      if (input) input.placeholder = 'cole sua chave aqui';
    }
  } catch(e) {}
}
async function saveAiKey() {
  const input = G('settings-ai-key');
  const provider = G('settings-ai-provider')?.value || 'gemini';
  const key = input?.value?.trim();
  const msg = G('settings-ai-msg');
  if (!key) { if (msg) { msg.textContent = 'Cole a chave antes de salvar.'; msg.style.color = 'var(--red)'; } return; }
  // Validação leve de formato por provedor (apenas aviso, não bloqueia)
  const expected = { openrouter:'sk-or-', gemini:'AIza', openai:'sk-', anthropic:'sk-ant-' }[provider];
  if (expected && !key.startsWith(expected)) {
    if (msg) { msg.textContent = '⚠️ A chave deste provedor normalmente começa com "' + expected + '". Salvando mesmo assim.'; msg.style.color = 'var(--warn)'; }
  } else if (msg) { msg.textContent = '✅ Chave salva.'; msg.style.color = 'var(--green)'; }
  await ff.aiSetKey({ provider, key });
  if (input) input.value = '';
  toast('Chave salva');
  refreshAiKeyStatus();
}
async function clearAiKey() {
  if (!await showConfirmDialog('Remover a chave de API?', 'A entrada por linguagem natural ficará indisponível até você inserir uma nova chave.', 'Remover', true)) return;
  await ff.aiClearKey();
  const msg = G('settings-ai-msg');
  if (msg) { msg.textContent = 'Chave removida.'; msg.style.color = 'var(--text3)'; }
  toast('Chave removida');
  refreshAiKeyStatus();
}

// ══ AI NATURAL-LANGUAGE ENTRY ══
let _aiParsedTxs = [];

async function openAiEntry() {
  const st = await ff.aiGetKeyStatus().catch(() => ({ hasKey: false }));
  if (!st.hasKey) {
    if (!await showConfirmDialog('Configure sua chave de IA', 'A entrada por linguagem natural usa um provedor de IA com sua própria chave (o Google Gemini tem chave gratuita). Deseja abrir as configurações para inseri-la agora?', 'Abrir configurações')) return;
    goPage('backup');
    setTimeout(() => G('settings-ai-key')?.focus(), 300);
    return;
  }
  G('ai-entry-text').value = '';
  G('ai-entry-msg').textContent = '';
  G('ai-entry-preview').innerHTML = '';
  _aiParsedTxs = [];
  openModal('modal-ai-entry');
  setTimeout(() => G('ai-entry-text')?.focus(), 80);
}

// Nota: a entrada por voz (ditado) não está disponível no desktop. A Web Speech
// API do Chromium depende de um serviço de transcrição fechado do Google que só
// funciona no Chrome oficial — ela sempre retorna "network error" dentro do
// Electron, é uma limitação conhecida e sem solução do lado da aplicação. A
// entrada por voz é um recurso do app móvel (usando a transcrição nativa do
// teclado ou a Speech API do próprio sistema iOS/Android).

async function runAiParse() {
  const text = G('ai-entry-text')?.value?.trim();
  const msg = G('ai-entry-msg');
  if (!text) { if (msg) { msg.textContent = 'Digite algo primeiro.'; msg.style.color = 'var(--red)'; } return; }

  const btn = G('ai-parse-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Interpretando...'; }
  if (msg) { msg.textContent = ''; }

  const payload = {
    text,
    accounts: accounts.map(a => ({ id: a.id, name: a.name, type: a.type })),
    categories: [...CATS_RAW].sort(),
    today: todayStr(),
  };

  let res;
  try { res = await ff.aiParseTransaction(payload); }
  catch(e) { res = { ok: false, error: 'NETWORK' }; }

  if (btn) { btn.disabled = false; btn.textContent = 'Interpretar'; }

  if (!res.ok) {
    const errMap = {
      NO_KEY: 'Nenhuma chave de IA configurada. Vá em Configurações.',
      BAD_KEY: 'Chave de API inválida ou sem permissão. Verifique em Configurações.',
      GEMINI_AQ_KEY: 'Sua chave do Gemini está no formato "AQ." — um problema atual do Google que impede o uso direto. Troque para o provedor OpenRouter em Configurações (também grátis e sem cartão).',
      EMPTY: 'Texto vazio.',
      PARSE_FAIL: 'A IA respondeu em formato inesperado. Tente reformular.',
      API_ERROR: 'Erro na API: ' + (res.detail || ''),
      NETWORK: 'Falha de conexão. Verifique sua internet.',
    };
    if (msg) { msg.textContent = '⚠️ ' + (errMap[res.error] || res.error); msg.style.color = 'var(--red)'; }
    return;
  }

  const txs = (res.result?.transactions || []).filter(t => t && typeof t.amount === 'number' && t.amount !== 0);
  if (!txs.length) {
    if (msg) { msg.textContent = 'Não identifiquei nenhum lançamento. Tente ser mais específico (valor e descrição).'; msg.style.color = 'var(--warn)'; }
    return;
  }

  // Em vez de um preview somente-leitura, abre o modal de lançamento padrão
  // (já editável, com todos os campos) pré-preenchido para cada item identificado,
  // um por vez em fila — o usuário confere/corrige e confirma normalmente.
  _aiQueuedTxs = txs;
  closeModal('modal-ai-entry');
  toast(`✨ ${txs.length} lançamento(s) identificado(s) — confira e confirme`);
  openNextAiQueuedTx();
}

let _aiQueuedTxs = [];
let _aiQueueIndex = 0;

function openNextAiQueuedTx() {
  if (_aiQueueIndex >= _aiQueuedTxs.length) {
    window._aiQueueActive = false;
    _aiQueuedTxs = []; _aiQueueIndex = 0;
    loadAccounts();
    if (currentPage === 'account') refreshAccount();
    if (currentPage === 'overview') refreshOverview();
    return;
  }
  const t = _aiQueuedTxs[_aiQueueIndex];
  const accId = accounts.find(a => a.id === t.account_id) ? t.account_id : (currentAccountId || accounts[0]?.id);
  // Pré-preenche o modal padrão de lançamento — totalmente editável, sem travas de conta.
  openTxModal({
    date: t.date || todayStr(),
    amount: t.amount,
    memo: t.memo || '',
    category: t.category || '',
    account_id: accId,
  });
  // Marca que este save deve avançar a fila, e ajusta o rótulo do modal
  window._aiQueueActive = true;
  const remaining = _aiQueuedTxs.length - _aiQueueIndex;
  const titleEl = G('modal-tx-title');
  if (titleEl) titleEl.textContent = `✨ Lançamento via IA (${_aiQueueIndex + 1}/${_aiQueuedTxs.length})${remaining > 1 ? '' : ''}`;
}

// ══ AI PROACTIVE INSIGHTS ══
let _insightsCache = { month: null, data: null };

async function maybeShowInsightsCard() {
  // Only show the card if the user has configured an API key
  const card = G('ai-insights-card');
  if (!card) return;
  const st = await ff.aiGetKeyStatus().catch(() => ({ hasKey: false }));
  if (!st.hasKey) { card.style.display = 'none'; return; }
  card.style.display = '';
  // Auto-render cached insights for this month if present; otherwise show prompt
  const body = G('ai-insights-body');
  const curM = overviewMonthStr();
  const curRealMonth = todayStr().slice(0,7);
  if (_insightsCache.month === curM && _insightsCache.data) {
    renderInsights(_insightsCache.data);
  } else if (curM >= curRealMonth) {
    if (body) body.innerHTML = '<div style="font-size:13px;color:var(--text3)">Os insights ficam disponíveis para meses já encerrados — navegue para um mês anterior para gerá-los.</div>';
  } else if (body) {
    body.innerHTML = '<div style="font-size:13px;color:var(--text3)">Clique em <strong>✨ Gerar</strong> para receber uma análise dos seus gastos deste período.</div>';
  }
}

// targetMonth: 'YYYY-MM' do mês a ser analisado (o mês aberto na Visão Geral).
// Sempre um mês JÁ ENCERRADO — nunca o mês corrente, que ainda está incompleto.
// Constrói os dados por categoria EXATAMENTE como a aba Evolução: corrigidos
// pelo IPCA (valores em R$ de hoje) e suavizados por média móvel de 12 meses.
// Isso evita falsos alarmes de "salto" em categorias episódicas (viagens,
// presentes sazonais) que naturalmente variam mês a mês sem indicar problema —
// a MA12 absorve essa sazonalidade e permite comparação ano a ano de verdade.
async function buildEvolucaoCategorySeries() {
  if (!Object.keys(_ev.ipca).length) await loadEvolucaoConfig().catch(() => {});
  const excl = [..._excludedCats];
  const catRows = await ff.evolucaoByCat({ excludedCats: excl }).catch(() => []);

  const refMonth = getIpcaRefMonth() || todayStr().slice(0,7);
  const corr = (v, m) => inflateMonth(v, m, refMonth);

  const today = todayStr();
  const curM = today.slice(0,7);
  const allMonths = [...new Set(catRows.map(r => r.month))].filter(m => m <= curM).sort();
  const allCats = [...new Set(catRows.map(r => r.category))].sort();

  // net por categoria por mês (despesa positiva, receita negativa — antes da inversão de sinal)
  const byCat = {};
  // Bruto por categoria por mês: {income, expenses} SEM correção de IPCA e SEM MA12.
  // É o valor nominal real daquele mês — usado pelos insights para (a) comparar
  // contra orçamentos (que são definidos em R$ nominais) e (b) citar números
  // concretos do mês, além da tendência suavizada.
  const byCatRaw = {};
  catRows.forEach(r => {
    if (!byCat[r.category]) byCat[r.category] = {};
    byCat[r.category][r.month] = (r.expenses||0) - (r.income||0);
    if (!byCatRaw[r.category]) byCatRaw[r.category] = {};
    byCatRaw[r.category][r.month] = { income: r.income||0, expenses: r.expenses||0 };
  });

  // Para cada categoria: série corrigida por IPCA, depois suavizada por MA12
  const series = {};
  allCats.forEach(cat => {
    const rawNet = allMonths.map(m => corr(byCat[cat]?.[m] || 0, m));
    const ma12 = allMonths.map((_,i) => movAvg12(rawNet, i));
    series[cat] = { months: allMonths, raw: rawNet, ma12 };
  });

  return { allMonths, allCats, series, byCatRaw, refMonth };
}

// targetMonth/filters: período (quantos meses), categorias (lista ou vazio=todas),
// foco (string livre repassada ao prompt), e freeText (pedido em linguagem natural).
async function buildInsightsSummary(targetMonth, filters) {
  filters = filters || {};
  const periodMonths = filters.periodMonths || 6;
  const selectedCats = filters.categories && filters.categories.length ? new Set(filters.categories) : null;

  // Garante que a classificação receita/despesa configurada pelo usuário esteja
  // carregada — é ela que tem prioridade sobre qualquer heurística de sinal.
  try { if (!Object.keys(_catTypes).length) await loadCatTypes(); } catch(e) {}

  const { allMonths, series, byCatRaw } = await buildEvolucaoCategorySeries();
  // 9999 = "desde o início" — usa todos os meses disponíveis
  const months = periodMonths >= 9999
    ? allMonths.filter(m => m <= targetMonth)
    : allMonths.filter(m => m <= targetMonth).slice(-periodMonths);
  if (!months.includes(targetMonth) && allMonths.includes(targetMonth)) months.push(targetMonth);
  const curM = targetMonth;
  const prevMonths = months.filter(m => m !== curM);

  const catsToUse = selectedCats ? [...selectedCats] : Object.keys(series);

  // Classificação de tipo (receita/despesa) em ordem de confiança decrescente:
  //   1. configuração EXPLÍCITA do usuário (_catTypes) — sempre vence;
  //   2. heurística de PALAVRAS-CHAVE (getCatType: salário, juros, dividendo…);
  //   3. só então, como ÚLTIMO recurso, o sinal médio dos dados.
  // Antes usava-se apenas o sinal médio, o que classificava errado categorias de
  // despesa com muitos estornos (ficavam "receita") e categorias de receita com
  // débitos pontuais (ficavam "despesa"). É a causa raiz da IA dizer "ganhos"
  // onde era gasto e vice-versa.
  const classifyType = (cat, avgSign) => {
    if (_catTypes[cat] === 'income' || _catTypes[cat] === 'expense') return _catTypes[cat];
    if (getCatType(cat) === 'income') return 'income';
    return avgSign < 0 ? 'income' : 'expense';
  };

  // Bruto (nominal, sem IPCA/MA12) por categoria no mês alvo e média dos meses
  // anteriores — dá à IA o número REAL do mês, além da tendência suavizada.
  const rawNetOf = (cat, m) => { const d = byCatRaw?.[cat]?.[m]; return d ? (d.expenses - d.income) : 0; };

  // Por categoria: valor MA12 (já suavizado) no mês alvo, média dos meses
  // anteriores (também já em MA12, então a comparação é "tendência vs tendência",
  // não "mês episódico vs média simples" — é isso que evita o falso alarme).
  const categories = catsToUse.map(cat => {
    const s = series[cat];
    if (!s) return null;
    const idxOf = m => s.months.indexOf(m);
    const curIdx = idxOf(curM);
    const cur = curIdx >= 0 ? s.ma12[curIdx] : 0;
    const priorVals = prevMonths.map(m => { const i = idxOf(m); return i>=0 ? s.ma12[i] : 0; }).filter(v => v !== 0);
    const avgPrior = priorVals.length ? priorVals.reduce((a,b)=>a+b,0)/priorVals.length : 0;

    // A série é "despesa positiva, receita negativa" (expenses - income).
    const allVals = s.ma12.filter(v => v !== 0);
    const avgSign = allVals.length ? allVals.reduce((a,b)=>a+b,0)/allVals.length : cur;
    const isIncome = classifyType(cat, avgSign) === 'income';

    // Normaliza pra magnitude intuitiva: despesa positiva = gastou mais;
    // receita positiva = ganhou mais.
    const curNat      = isIncome ? -cur : cur;
    const avgPriorNat = isIncome ? -avgPrior : avgPrior;
    const pctChange = avgPriorNat !== 0 ? ((curNat - avgPriorNat) / Math.abs(avgPriorNat)) * 100 : null;

    // Número BRUTO do mês alvo (nominal), normalizado pelo tipo, e nº de meses
    // com movimento — para a IA evitar conclusões sobre categorias com poucos dados.
    const rawCur = rawNetOf(cat, curM);
    const rawCurNat = isIncome ? -rawCur : rawCur;
    const monthsWithData = months.filter(m => rawNetOf(cat, m) !== 0).length;

    return {
      category: cat,
      type: isIncome ? 'receita' : 'despesa',
      current: Math.round(curNat),           // tendência MA12 (R$ de hoje)
      avgPrior: Math.round(avgPriorNat),      // tendência MA12 média anterior
      actualThisMonth: Math.round(rawCurNat), // valor NOMINAL real do mês alvo
      monthsWithData,                         // quantos meses do período tiveram movimento
      pctChange: pctChange === null ? null : Math.round(pctChange),
      // Para receitas: subindo = bom; Para despesas: aumentando = ruim
      trend: isIncome
        ? (pctChange === null ? 'estável' : pctChange > 5 ? 'subindo' : pctChange < -5 ? 'caindo' : 'estável')
        : (pctChange === null ? 'estável' : pctChange > 5 ? 'aumentando' : pctChange < -5 ? 'reduzindo' : 'estável'),
    };
  }).filter(c => c && (c.current !== 0 || c.avgPrior !== 0 || c.actualThisMonth !== 0))
    .sort((a,b) => Math.abs(b.current) - Math.abs(a.current))
    .slice(0, 20);

  // ── Totais separados por TIPO, em valores NOMINAIS do mês alvo ──
  // Antes existia um único "totalSpentCurrent" que somava todas as séries com
  // receita negativa — ou seja, era o RESULTADO LÍQUIDO, não o total gasto. O
  // nome enganava a IA a dizer "você gastou R$ X" com um número que já descontava
  // as receitas. Agora separamos explicitamente despesa, receita, resultado e
  // taxa de poupança, cada um com rótulo inequívoco.
  const splitTotals = (m) => {
    let income = 0, expenses = 0;
    Object.keys(byCatRaw || {}).forEach(cat => {
      if (selectedCats && !selectedCats.has(cat)) return;
      const d = byCatRaw[cat][m]; if (!d) return;
      const net = d.expenses - d.income;
      const allVals = series[cat] ? series[cat].ma12.filter(v => v !== 0) : [];
      const avgSign = allVals.length ? allVals.reduce((a,b)=>a+b,0)/allVals.length : net;
      if (classifyType(cat, avgSign) === 'income') income += (d.income - d.expenses);
      else expenses += net;
    });
    return { income: Math.max(0, income), expenses: Math.max(0, expenses) };
  };
  const curTot = splitTotals(curM);
  const totalExpenses = curTot.expenses;
  const totalIncome   = curTot.income;
  const netResult     = totalIncome - totalExpenses;
  const savingsRate   = totalIncome > 0 ? Math.round((netResult / totalIncome) * 100) : null;

  const priorTots = prevMonths.map(splitTotals);
  const avgMonthlyExpenses = priorTots.length ? priorTots.reduce((a,b)=>a+b.expenses,0)/priorTots.length : 0;
  const avgMonthlyIncome   = priorTots.length ? priorTots.reduce((a,b)=>a+b.income,0)/priorTots.length : 0;

  // Orçamentos referentes ao mês alvo — agora com SUBCATEGORIAS e valor LÍQUIDO
  // (despesa menos estornos na mesma categoria), exatamente como a aba Orçamento.
  // Antes o casamento era por categoria EXATA, então um orçamento em "Carro" com
  // gasto lançado em "Carro:Combustível" aparecia como gasto = 0.
  let budgets = [];
  try {
    const bl = (await ff.budgetList()).filter(b => b.type !== 'income');
    const actuals = await ff.budgetActuals({ month: curM }); // já livre de transferências
    budgets = bl.map(b => {
      const consolidate = b.consolidate_subs !== 0;
      let spent = 0, received = 0;
      actuals.forEach(a => {
        const c = a.category || '';
        if (c === b.category || (consolidate && c.startsWith(b.category + ':'))) {
          spent += a.spent || 0; received += a.received || 0;
        }
      });
      const netSpent = Math.max(0, spent - received);
      return { category: b.category, limit: b.monthly_limit,
        spent: Math.round(netSpent),
        pctUsed: b.monthly_limit > 0 ? Math.round(netSpent / b.monthly_limit * 100) : null,
        status: b.monthly_limit > 0 ? (netSpent > b.monthly_limit ? 'acima' : netSpent >= b.monthly_limit * 0.85 ? 'perto' : 'ok') : 'sem_limite' };
    });
  } catch(e) {}

  // Maiores transações reais do mês (para a IA citar exemplos concretos)
  let topTransactions = { expenses: [], income: [] };
  try { topTransactions = await ff.insightsTopTransactions({ month: curM, limit: 5 }); } catch(e) {}

  // Dívidas pessoais cadastradas, com taxa de juros real (para a IA comparar
  // contra os encargos de rotativo/cheque especial detectados na importação)
  let personalDebts = [];
  try {
    const debts = await ff.debtList().catch(() => []);
    for (const d of debts) {
      if (d.hidden) continue;
      const contract = await ff.debtContractGet({ debtId: d.id }).catch(() => null);
      if (contract) {
        personalDebts.push({ name: d.name, annualRate: contract.annual_rate,
          principal: contract.principal, system: contract.system });
      }
    }
  } catch(e) {}

  // Juros de dívida pessoal detectados em importações recentes (rotativo, cheque especial)
  let recentDebtInterest = [];
  try {
    const log = JSON.parse(localStorage.getItem('crz-debt-interest-log') || '[]');
    recentDebtInterest = log.filter(e => e.date && e.date.slice(0,7) === curM)
      .map(e => ({ label: e.label, amount: e.amount, rate: e.rate }));
  } catch(e) {}

  // Saldo líquido total disponível hoje (contas bancárias + dinheiro), para a IA
  // avaliar alternativas factíveis (ex.: não sugerir quitar com dinheiro que não existe)
  let liquidBalance = 0;
  try {
    liquidBalance = accounts
      .filter(a => !a.hidden && (a.type === 'bank' || a.type === 'cash'))
      .reduce((s, a) => s + (a.balance || 0), 0);
  } catch(e) {}

  return { currentMonth: curM, monthsAnalyzed: months.length,
           dataSource: 'Aba Evolução. Campos "current"/"avgPrior" das categorias = tendência de 12 meses (MA12) já corrigida por IPCA (R$ de hoje). Campo "actualThisMonth" = valor NOMINAL real do mês. Totais e orçamentos abaixo = valores NOMINAIS reais do mês (sem IPCA/MA12).',
           focus: filters.focus || 'ambos', userRequest: filters.freeText || null,
           categoriesFilter: selectedCats ? [...selectedCats] : 'todas',
           // Totais NOMINAIS do mês alvo, separados sem ambiguidade:
           totalExpenses: Math.round(totalExpenses),   // soma das DESPESAS líquidas do mês
           totalIncome:   Math.round(totalIncome),      // soma das RECEITAS líquidas do mês
           netResult:     Math.round(netResult),        // receitas - despesas (poupança do mês; negativo = déficit)
           savingsRate,                                  // % da receita que sobrou (null se não houve receita)
           avgMonthlyExpenses: Math.round(avgMonthlyExpenses), // média de despesas dos meses anteriores
           avgMonthlyIncome:   Math.round(avgMonthlyIncome),   // média de receitas dos meses anteriores
           categories, budgets, topTransactions,
           personalDebts, recentDebtInterest,
           liquidBalanceToday: Math.round(liquidBalance) };
}

async function generateInsights(force, usePersonalization) {
  const body = G('ai-insights-body');
  const status = G('ai-insights-status');
  const btn = G('ai-insights-refresh');
  if (!body) return;

  const targetMonth = overviewMonthStr(); // respeita o mês aberto na Visão Geral
  const curRealMonth = todayStr().slice(0,7);

  // Nunca analisa o mês corrente — ele ainda está incompleto e distorceria os números
  if (targetMonth >= curRealMonth) {
    body.innerHTML = `<div style="font-size:13px;color:var(--warn)">⚠️ Os insights só funcionam para meses já encerrados (o mês atual ainda não tem todos os dados). Navegue para um mês anterior na Visão Geral e clique em Gerar novamente.</div>`;
    return;
  }

  const st = await ff.aiGetKeyStatus().catch(() => ({ hasKey: false }));
  if (!st.hasKey) {
    body.innerHTML = '<div style="font-size:13px;color:var(--text2)">Configure sua chave de IA em ⚙️ Configurações para ativar os insights.</div>';
    return;
  }

  // Coleta os filtros do painel de personalização, se estiver sendo usado
  const filters = usePersonalization ? collectInsightsFilters() : {};
  const cacheKey = usePersonalization ? `${targetMonth}::${JSON.stringify(filters)}` : targetMonth;

  if (btn) { btn.disabled = true; btn.textContent = '⏳ Analisando...'; }
  if (status) status.textContent = '';

  try {
    const summary = await buildInsightsSummary(targetMonth, filters);
    if (!summary.categories.length) {
      body.innerHTML = '<div style="font-size:13px;color:var(--text3)">Não há dados suficientes neste período para gerar insights. Tente outro período ou outras categorias.</div>';
      return;
    }

    let res;
    try { res = await ff.aiGenerateInsights({ summary }); }
    catch(e) { res = { ok: false, error: 'NETWORK' }; }

    if (!res.ok) {
      const errMap = { NO_KEY:'Configure a chave de IA em Configurações.',
        BAD_KEY:'Chave de API inválida.',
        GEMINI_AQ_KEY: 'Sua chave do Gemini está no formato "AQ." (problema atual do Google). Troque para o provedor OpenRouter em Configurações.',
        PARSE_FAIL:'A IA respondeu em formato inesperado. Tente novamente em alguns segundos.',
        API_ERROR:'Erro na API: ' + (res.detail || ''), NETWORK:'Falha de conexão.' };
      body.innerHTML = `<div style="font-size:13px;color:var(--red)">⚠️ ${errMap[res.error] || res.error}</div>`;
      return;
    }

    const insights = res.result?.insights || [];
    if (!insights.length) {
      body.innerHTML = '<div style="font-size:13px;color:var(--text3)">Nenhum insight relevante neste período.</div>';
      return;
    }

    _insightsCache = { month: cacheKey, data: insights };
    renderInsights(insights);
    if (status) status.textContent = `Mês analisado: ${fmtMonth(targetMonth)}${usePersonalization ? ' (personalizado)' : ''}`;
  } catch(e) {
    body.innerHTML = `<div style="font-size:13px;color:var(--red)">⚠️ Erro ao gerar insights: ${esc(e.message||String(e))}</div>`;
  } finally {
    // SEMPRE reabilita o botão, mesmo se algo lançar exceção acima — corrige o "travamento"
    if (btn) { btn.disabled = false; btn.textContent = '✨ Gerar'; }
  }
}

// ── Personalização do Insight ──────────────────────────────────────────
function toggleInsightsPersonalize() {
  const panel = G('ai-insights-personalize-panel');
  if (!panel) return;
  const opening = panel.style.display === 'none';
  panel.style.display = opening ? '' : 'none';
  if (opening) {
    populateInsightsCatChips();
    renderSavedInsightsAnalyses();
  }
}

function populateInsightsCatChips() {
  const container = G('ai-insights-cat-chips');
  if (!container) return;
  const cats = [...new Set([...CATS_RAW])].sort();
  container.innerHTML = cats.map(c => `
    <label style="display:flex;align-items:center;gap:4px;font-size:11px;background:var(--bg3);border:1px solid var(--border);border-radius:12px;padding:3px 8px;cursor:pointer">
      <input type="checkbox" class="ai-insights-cat-chk" value="${esc2(c)}" style="margin:0;width:11px;height:11px"> ${esc(c)}
    </label>`).join('');
}

function collectInsightsFilters() {
  const categories = [...document.querySelectorAll('.ai-insights-cat-chk:checked')].map(el => el.value);
  const periodMonths = parseInt(G('ai-insights-period')?.value || '6');
  const focus = G('ai-insights-focus')?.value || 'ambos';
  const freeText = G('ai-insights-freetext')?.value?.trim() || '';
  return { categories, periodMonths, focus, freeText };
}

function applyInsightsFilters(filters) {
  document.querySelectorAll('.ai-insights-cat-chk').forEach(el => {
    el.checked = filters.categories?.includes(el.value);
  });
  if (G('ai-insights-period')) G('ai-insights-period').value = String(filters.periodMonths || 6);
  if (G('ai-insights-focus')) G('ai-insights-focus').value = filters.focus || 'ambos';
  if (G('ai-insights-freetext')) G('ai-insights-freetext').value = filters.freeText || '';
}

function getSavedInsightsAnalyses() {
  try { return JSON.parse(localStorage.getItem('crz-insights-saved') || '[]'); } catch(e) { return []; }
}
function setSavedInsightsAnalyses(list) {
  try { localStorage.setItem('crz-insights-saved', JSON.stringify(list)); } catch(e) {}
}

async function saveInsightsAnalysis() {
  const filters = collectInsightsFilters();
  const name = await showPromptDialog('Nome para esta análise', 'Ex.: "Gastos com viagem vs orçamento"');
  if (!name) return;
  const list = getSavedInsightsAnalyses();
  list.push({ id: Date.now(), name, filters });
  setSavedInsightsAnalyses(list);
  toast('💾 Análise salva');
  renderSavedInsightsAnalyses();
}

function renderSavedInsightsAnalyses() {
  const container = G('ai-insights-saved-list');
  if (!container) return;
  const list = getSavedInsightsAnalyses();
  if (!list.length) { container.innerHTML = ''; return; }
  container.innerHTML = `<div style="font-size:11px;color:var(--text3);margin-bottom:5px">Análises salvas:</div>
    <div style="display:flex;flex-wrap:wrap;gap:6px">` +
    list.map(a => `
      <div style="display:flex;align-items:center;gap:4px;background:var(--bg2);border:1px solid var(--border);border-radius:12px;padding:3px 4px 3px 10px">
        <button class="btn-link" style="font-size:11px;background:none;border:none;cursor:pointer;color:var(--accent)" onclick="runSavedInsightsAnalysis(${a.id})">${esc(a.name)}</button>
        <button class="btn-icon" style="font-size:11px;padding:0 4px;color:var(--text3)" title="Remover" onclick="deleteSavedInsightsAnalysis(${a.id})">✕</button>
      </div>`).join('') +
    `</div>`;
}

function runSavedInsightsAnalysis(id) {
  const list = getSavedInsightsAnalyses();
  const a = list.find(x => x.id === id);
  if (!a) return;
  applyInsightsFilters(a.filters);
  generateInsights(true, true);
}

function deleteSavedInsightsAnalysis(id) {
  setSavedInsightsAnalyses(getSavedInsightsAnalyses().filter(a => a.id !== id));
  renderSavedInsightsAnalyses();
}

function renderInsights(insights) {
  const body = G('ai-insights-body');
  if (!body) return;
  const typeStyle = {
    alert:    { bg:'#fef2f2', border:'#fecaca', clr:'var(--red)' },
    positive: { bg:'#f0fdf4', border:'#bbf7d0', clr:'var(--green)' },
    tip:      { bg:'#eff6ff', border:'#bfdbfe', clr:'var(--accent)' },
    trend:    { bg:'#fffbeb', border:'#fde68a', clr:'#b45309' },
  };
  // Normaliza valores fora do esperado (modelos mais simples às vezes ecoam o
  // formato do prompt em vez de preencher de fato) para nunca exibir lixo visível.
  function normalizeType(t) {
    const clean = String(t || '').toLowerCase().trim();
    if (typeStyle[clean]) return clean;
    return 'tip'; // fallback silencioso — não exibe o valor bruto inválido
  }
  function normalizeIcon(ic) {
    const v = String(ic || '').trim();
    // Considera inválido se vier vazio, com mais de 4 caracteres (provável texto
    // tipo "<1 emoji>" ou frase), ou sem nenhum caractere fora do intervalo ASCII básico
    if (!v || v.length > 4 || /^[a-zA-Z0-9<>]+$/.test(v)) return '💡';
    return v;
  }
  body.innerHTML = `<div style="display:flex;flex-direction:column;gap:8px">` +
    insights.map(ins => {
      const ts = typeStyle[normalizeType(ins.type)];
      const icon = normalizeIcon(ins.icon);
      return `<div style="background:${ts.bg};border:1px solid ${ts.border};border-radius:8px;padding:10px 12px;display:flex;gap:10px;align-items:flex-start">
        <span style="font-size:18px;line-height:1.2">${icon}</span>
        <div>
          <div style="font-weight:600;font-size:13px;color:${ts.clr}">${esc(ins.title || '')}</div>
          <div style="font-size:13px;color:var(--text2);margin-top:2px">${esc(ins.detail || '')}</div>
        </div>
      </div>`;
    }).join('') +
    `</div>
    <div style="font-size:11px;color:var(--text3);margin-top:8px">Gerado por IA com base nos seus dados. Pode conter imprecisões — confira os números no app.</div>`;
}

async function openAccount(id) {
  currentAccountId = id;
  _acctView = 'table'; // reset to table on account switch
  currentPage = 'account';
  try { patSelClearAll(); } catch(e) {}
  const acc = accounts.find(a => a.id === id);
  G('acct-name').textContent = acc?.name || 'Conta';
  G('page-title').textContent = acc?.name || 'Conta';
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  G('page-account').classList.add('active');
  G('search-wrap').style.display = 'flex';
  G('search-input').value = ''; searchQuery = '';
  // Default to date ascending (oldest first, scroll to today)
  sortBy = 'date'; sortOrder = 'asc';
  const sortSel = G('sort-select'); if (sortSel) sortSel.value = 'date-asc';
  renderSidebar();
  clearSelection();
  buildLedgerHeader();
  await refreshAccount();
  // Scroll to today after render
  setTimeout(() => scrollToToday(), 200);
  // Moedinha: atualiza as dicas para a tela de conta (openAccount não passa
  // por goPage, então precisa disparar o mesmo hook manualmente — sem isso,
  // as dicas da conta só apareciam ao fechar e reabrir o assistente).
  try { guideOnPageChange('account'); } catch(e) {}
}

// ══ OVERVIEW ══
let _overviewYear  = new Date().getFullYear();
let _overviewMonth = new Date().getMonth() + 1;
let _monthlyByCat  = [];

// Suggested categories to exclude (accounts used as categories, transfers)
const SUGGESTED_EXCLUDE = new Set([
  'Cartão BTG','Cartão XP','Mastercard','Pão de Açúcar','Mastercard Thi',
  'BB Naty','BB Thi','BTG C/C Naty','BTG C/C Thi','Conta Papai','Itaú',
  'BTG','BTG Naty','XP','XP (Inv. Ri)','R2T2','Investimento Corradi',
  'Investimentos Itaú','Empréstimo Zé','Empréstimo Porps','Investimento Loteamento',
  'Itaú Corretora','Euro','Reais','Wise','Transferência','Transferências',
]);
// Pre-populate with suggested so overview works immediately on first run
let _excludedCats = new Set(SUGGESTED_EXCLUDE);

const CHART_COLORS = [
  '#2563eb','#16a34a','#dc2626','#d97706','#7c3aed','#0891b2',
  '#db2777','#65a30d','#ea580c','#0284c7','#9333ea','#059669'
];

function overviewMonthStr() {
  return `${_overviewYear}-${String(_overviewMonth).padStart(2,'0')}`;
}
function overviewPrevMonth() {
  _overviewMonth--;
  if (_overviewMonth < 1) { _overviewMonth = 12; _overviewYear--; }
  refreshOverview();
}
function overviewNextMonth() {
  _overviewMonth++;
  if (_overviewMonth > 12) { _overviewMonth = 1; _overviewYear++; }
  refreshOverview();
}
function overviewToday() {
  const n = new Date();
  _overviewYear = n.getFullYear(); _overviewMonth = n.getMonth() + 1;
  refreshOverview();
}

