async function deleteRecurring(id){
  if(!await showConfirmDialog('Remover recorrência?', 'Seus lançamentos futuros não conciliados serão removidos.', 'Remover', true)) return;
  await ff.deleteRecurring(id);
  await loadAccounts();
  refreshRecurring();
  toast('Recorrência removida');
}

// ══ CATEGORY DROPDOWN ══
let _catKb={};
let _globalCatActiveInput = null; // currently focused cat input

function openCatDrop(inputId, dropId) {
  // For import table: use the global fixed dropdown
  const isImport = inputId && inputId.startsWith('import-cat-');
  if (isImport) {
    openGlobalCatDrop(G(inputId));
    return;
  }
  // Original behavior for other cat dropdowns
  const q=G(inputId)?.value||'', nq=norm(q), drop=G(dropId); if(!drop) return;
  let html='';
  // Recorrência: oferece "Transferência" como opção destacada no topo —
  // ao escolher, o campo de conta destino aparece automaticamente.
  const offerTransfer = inputId === 'rec-category';
  if (!nq) {
    if (offerTransfer) html += `<div class="cat-opt" style="color:var(--accent);font-weight:600" onmousedown="pickCat('${inputId}','${dropId}','Transferência')">⇄ Transferência</div>`;
    const seen=new Set();
    CATS_RAW.forEach(c=>{ const top=c.split(':')[0]; if(!seen.has(top)){seen.add(top);html+=`<div class="cat-section">${esc(top)}</div>`;} if(c.includes(':')) html+=`<div class="cat-opt" onmousedown="pickCat('${inputId}','${dropId}','${esc2(c)}')">${esc(c.split(':').slice(1).join(':'))}</div>`; else html+=`<div class="cat-opt" onmousedown="pickCat('${inputId}','${dropId}','${esc2(c)}')">${esc(c)}</div>`; });
  } else {
    if (offerTransfer && norm('Transferência').includes(nq)) html += `<div class="cat-opt" style="color:var(--accent);font-weight:600" onmousedown="pickCat('${inputId}','${dropId}','Transferência')">⇄ Transferência</div>`;
    const hits=CATS_RAW.filter(c=>norm(c).includes(nq));
    if (!hits.length && !(offerTransfer && norm('Transferência').includes(nq))) html='<div class="cat-opt" style="color:var(--text3);cursor:default">Sem resultado</div>';
    else hits.forEach(c=>{ html+=`<div class="cat-opt" onmousedown="pickCat('${inputId}','${dropId}','${esc2(c)}')">${esc(c)}</div>`; });
  }
  drop.innerHTML=html; drop.style.display='block'; _catKb[dropId]=-1;
}

let _globalCatKbIdx = -1;

function openGlobalCatDrop(inputEl) {
  if (!inputEl) return;
  _globalCatActiveInput = inputEl;
  _globalCatKbIdx = -1;
  const drop = G('global-cat-drop');
  if (!drop) return;
  const q = inputEl.value || '', nq = norm(q);
  // Build transfer category options from existing accounts
  const transferOpts = accounts
    .filter(a => !a.hidden)
    .map(a => `⇄ Transferência: ${a.name}`);

  let html = '';
  if (!nq) {
    html += `<div class="cat-section">Transferências</div>`;
    transferOpts.forEach(t => {
      html += `<div class="cat-opt" style="color:var(--accent)" onmousedown="pickGlobalCat('${esc2(t)}')">${esc(t)}</div>`;
    });
    const seen = new Set();
    CATS_RAW.forEach(c => {
      const top = c.split(':')[0];
      if (!seen.has(top)) { seen.add(top); html += `<div class="cat-section">${esc(top)}</div>`; }
      html += `<div class="cat-opt" onmousedown="pickGlobalCat('${esc2(c)}')">${esc(c)}</div>`;
    });
  } else {
    const tfHits = transferOpts.filter(t => norm(t).includes(nq));
    tfHits.forEach(t => {
      html += `<div class="cat-opt" style="color:var(--accent)" onmousedown="pickGlobalCat('${esc2(t)}')">${esc(t)}</div>`;
    });
    const hits = CATS_RAW.filter(c => norm(c).includes(nq));
    if (!hits.length && !tfHits.length) html = `<div class="cat-opt" style="color:var(--text3);cursor:default">Sem resultado</div>`;
    else hits.forEach(c => { html += `<div class="cat-opt" onmousedown="pickGlobalCat('${esc2(c)}')">${esc(c)}</div>`; });
  }
  drop.innerHTML = html;
  const rect = inputEl.getBoundingClientRect();
  // Evita o dropdown ultrapassar o limite inferior da tela (ficando
  // parcialmente inacessível, sem como rolar até as últimas categorias) —
  // acontecia em monitores mais baixos/janelas menores, quando o campo de
  // categoria está perto do fim da tela (comum na tabela de importação,
  // com muitas linhas).
  positionDropdownAvoidingOverflow(drop, rect, 280, 120);
  drop.style.width = Math.max(rect.width, 260) + 'px';
  drop.style.display = 'block';

  // Attach keyboard handler — remove first to prevent duplicates
  inputEl.removeEventListener('keydown', globalCatKeydown);
  inputEl.addEventListener('keydown', globalCatKeydown);

  // Close dropdown on blur (e.g. Tab moving focus away without selecting)
  // Use setTimeout so mousedown on a cat-opt fires before blur closes the list
  inputEl.removeEventListener('blur', _globalCatBlurHandler);
  inputEl.addEventListener('blur', _globalCatBlurHandler);
}

function _globalCatBlurHandler() {
  setTimeout(() => {
    const drop = G('global-cat-drop');
    // Only close if focus has moved away from both the input and the dropdown
    if (drop && drop.style.display !== 'none') {
      const active = document.activeElement;
      if (!drop.contains(active) && active !== _globalCatActiveInput) {
        drop.style.display = 'none';
        _globalCatKbIdx = -1;
      }
    }
  }, 120);
}

function globalCatKeydown(e) {
  const drop = G('global-cat-drop');
  if (!drop || drop.style.display === 'none') return;
  const opts = [...drop.querySelectorAll('.cat-opt')].filter(o => !o.style.cursor || o.style.cursor !== 'default');
  if (!opts.length) return;

  if (e.key === 'ArrowDown') {
    e.preventDefault();
    _globalCatKbIdx = Math.min(_globalCatKbIdx + 1, opts.length - 1);
    opts.forEach(o => o.classList.remove('kb-active'));
    opts[_globalCatKbIdx].classList.add('kb-active');
    opts[_globalCatKbIdx].scrollIntoView({ block: 'nearest' });
  } else if (e.key === 'ArrowUp') {
    e.preventDefault();
    _globalCatKbIdx = Math.max(_globalCatKbIdx - 1, 0);
    opts.forEach(o => o.classList.remove('kb-active'));
    opts[_globalCatKbIdx].classList.add('kb-active');
    opts[_globalCatKbIdx].scrollIntoView({ block: 'nearest' });
  } else if (e.key === 'Enter' || e.key === 'Tab') {
    if (_globalCatKbIdx >= 0) {
      // Item selected via keyboard navigation — pick it
      e.preventDefault();
      e.stopPropagation();
      const chosen = opts[_globalCatKbIdx];
      if (chosen) {
        const m = chosen.getAttribute('onmousedown')?.match(/pickGlobalCat\('(.+?)'\)/);
        if (m) pickGlobalCat(m[1]);
        else { if (_globalCatActiveInput) _globalCatActiveInput.value = chosen.textContent; drop.style.display = 'none'; }
      }
    } else {
      // Tab/Enter without navigation — just close the dropdown
      drop.style.display = 'none';
      _globalCatKbIdx = -1;
      // For Tab, let the browser move focus normally (don't preventDefault)
    }
  } else if (e.key === 'Escape') {
    drop.style.display = 'none';
    _globalCatKbIdx = -1;
  }
}

function pickGlobalCat(val) {
  const clean = val.replace(/&#39;/g, "'").replace(/&amp;/g, '&');
  const drop = G('global-cat-drop');
  if (drop) drop.style.display = 'none';
  _globalCatKbIdx = -1;

  // Detect transfer category → open transfer modal instead
  const tfMatch = clean.match(/^⇄ Transferência: (.+)$/);
  if (tfMatch) {
    const destName = tfMatch[1];
    const destAcc = accounts.find(a => a.name === destName);
    // Set the input to show the transfer label (for display only)
    if (_globalCatActiveInput) {
      _globalCatActiveInput.value = clean;
      _globalCatActiveInput.dataset.isTransfer = '1';
      _globalCatActiveInput.dataset.transferDest = destAcc?.id || '';
    }
    // Se a categorização ocorreu na tela de edição de importação (extrato ainda não salvo),
    // preenche o modal a partir da própria linha importada (data, valor, memo já conhecidos).
    const importIdMatch = _globalCatActiveInput?.id?.match(/^import-cat-(\d+)$/);
    if (importIdMatch) {
      const idx = parseInt(importIdMatch[1]);
      const row = _importEditRows[idx];
      if (row) { row._importIdx = idx; openTransferFromImportRow(row, destAcc); return; }
    }
    // Caminho padrão: categorização inline de uma transação já salva no extrato
    openTransferFromCat(destAcc);
    return;
  }

  if (_globalCatActiveInput) {
    _globalCatActiveInput.value = clean;
    _globalCatActiveInput.dataset.isTransfer = '';
    _globalCatActiveInput.dispatchEvent(new Event('input', { bubbles: true }));
  }
}

// Open transfer modal pre-filled from a category selection context
// Preenche o modal de transferência automaticamente a partir de uma linha
// ainda em importação (não salva): usa data, valor e conta de origem/destino
// conforme o sinal do lançamento, e o memorando sugerido pelo ML quando houver.
function openTransferFromImportRow(row, destAcc) {
  setupCurrencyInput(G('tr-amount'));

  const srcAccId = row.accountId ?? currentAccountId;
  const isDebit  = row.amount < 0; // saída desta conta = ela é a origem; entrada = ela é o destino

  const fromSel = G('tr-from');
  const toSel   = G('tr-to');
  if (isDebit) {
    if (fromSel && srcAccId) fromSel.value = String(srcAccId);
    if (toSel && destAcc)    toSel.value   = String(destAcc.id);
  } else {
    if (fromSel && destAcc)   fromSel.value = String(destAcc.id);
    if (toSel && srcAccId)    toSel.value   = String(srcAccId);
  }

  G('tr-date').value = row.dateISO || todayStr();
  G('tr-amount').setValue?.(Math.abs(row.amount || 0));
  // Memorando: lê o valor exatamente como está no campo visível da tela de
  // importação (reflete tanto uma edição manual do usuário quanto a sugestão
  // do ML, o que for o caso) — não usa row.sugMemo/row.memo diretamente,
  // porque a edição manual só fica sincronizada em row.memo, e isso criaria
  // ambiguidade com o caso em que o ML sugeriu algo diferente da descrição crua.
  const memoFromDom = (row._importIdx != null)
    ? document.querySelector(`.import-memo-inp[data-idx="${row._importIdx}"]`)?.value
    : null;
  G('tr-memo').value = memoFromDom ?? (row.memo || row.sugMemo || row.desc || '');

  // Não há tx salva ainda (linha de importação) — nada a excluir após salvar.
  // Marca o índice da linha de importação para evitar duplicar a transferência
  // se o usuário também confirmar a importação inteira depois.
  const hidField = G('tr-origin-tx-id');
  if (hidField) hidField.value = '';
  let importIdxField = G('tr-import-row-idx');
  if (!importIdxField) {
    importIdxField = document.createElement('input');
    importIdxField.type = 'hidden'; importIdxField.id = 'tr-import-row-idx';
    G('modal-transfer')?.appendChild(importIdxField);
  }
  importIdxField.value = row._importIdx ?? '';

  openModal('modal-transfer');
}

function openTransferFromCat(destAcc) {
  // Limpa qualquer marcação de linha de importação de uma chamada anterior
  const f = G('tr-import-row-idx'); if (f) f.value = '';
  setupCurrencyInput(G('tr-amount'));
  G('tr-amount').setValue?.(null);
  G('tr-memo').value = '';
  G('tr-date').value = todayStr();

  // Determine source account: current account context OR the tx-account field
  const srcId = currentAccountId || parseInt(G('tx-account')?.value) || null;

  // Pre-select accounts
  const fromSel = G('tr-from');
  const toSel   = G('tr-to');
  if (fromSel && srcId)   fromSel.value = String(srcId);
  if (toSel   && destAcc) toSel.value   = String(destAcc.id);

  // Pre-fill date/memo/amount from the active new-tx form if values exist
  const txDate = G('tx-date')?.value;
  const txMemo = G('tx-memo')?.value;
  const txExp  = G('tx-expense')?.rawValue?.() || 0;
  const txInc  = G('tx-income')?.rawValue?.()  || 0;
  const txAmt  = txExp > 0 ? txExp : txInc;
  if (txDate) G('tr-date').value = txDate;
  if (txMemo) G('tr-memo').value = txMemo;
  if (txAmt > 0) G('tr-amount').setValue?.(txAmt);

  // Also try inline edit row (overrides form values if found)
  const inp = _globalCatActiveInput;
  if (inp) {
    const row = inp.closest('tr[data-id]');
    if (row) {
      const txId = parseInt(row.dataset.id);
      const tx = window._lastTxs?.find(t => t.id === txId);
      if (tx) {
        G('tr-amount').setValue?.(Math.abs(tx.amount));
        G('tr-date').value = tx.date || todayStr();
        G('tr-memo').value = tx.memo || '';
      }
      // Store origin tx id for deletion after save
      let hidField = G('tr-origin-tx-id');
      if (!hidField) {
        hidField = document.createElement('input');
        hidField.type = 'hidden'; hidField.id = 'tr-origin-tx-id';
        G('modal-transfer')?.appendChild(hidField);
      }
      hidField.value = row.dataset.id || '';
    }
  }

  // Se veio do campo de categoria do modal "Novo Lançamento" (tx-category),
  // esse modal fica aberto por baixo do de transferência (mesmo z-index —
  // quem fica visível é só quem tem a classe .open por último). Ao fechar o
  // modal de transferência depois de registrar, o "Novo Lançamento" reaparecia
  // por trás, ainda com data/memo/valor preenchidos e categoria literal
  // "⇄ Transferência: X" — parecia que "o modal não fechou", e um novo clique
  // em Salvar/Registrar criava um lançamento fantasma e/ou outra transferência
  // duplicada. Fechamos o "Novo Lançamento" aqui (sem os efeitos colaterais de
  // closeModal(), como interromper a fila de "Lançar com IA") pra deixar só um
  // modal visível por vez, e ele não reabre sozinho depois.
  if (_globalCatActiveInput?.id === 'tx-category') {
    const txModal = G('modal-tx');
    if (txModal?.classList.contains('open')) {
      const focused = txModal.querySelector(':focus');
      if (focused) focused.blur();
      txModal.classList.remove('open');
    }
  }

  openModal('modal-transfer');
}

function swapTransferAccounts() {
  const fromSel = G('tr-from');
  const toSel   = G('tr-to');
  if (!fromSel || !toSel) return;
  const tmp = fromSel.value;
  fromSel.value = toSel.value;
  toSel.value   = tmp;
}

// Close global cat drop on outside click
document.addEventListener('mousedown', e => {
  const drop = G('global-cat-drop');
  if (drop && drop.style.display !== 'none') {
    if (!drop.contains(e.target) && e.target !== _globalCatActiveInput) {
      drop.style.display = 'none';
      _globalCatKbIdx = -1;
    }
  }
});

function closeCatDrop(id){ setTimeout(()=>{ const d=G(id); if(d) d.style.display='none'; },180); }
function pickCat(inp,drop,val){
  const el = G(inp);
  el.value = val.replace(/&#39;/g,"'").replace(/&amp;/g,'&');
  G(drop).style.display='none';
  el.dispatchEvent(new Event('input', { bubbles: true }));
}
function catKey(e,dropId,inputId){
  const drop=G(dropId); if(!drop||drop.style.display!=='block') return;
  const opts=drop.querySelectorAll('.cat-opt'); if(!opts.length) return;
  if(e.key==='Escape'){drop.style.display='none';return;}
  if(e.key==='ArrowDown'||e.key==='ArrowUp'){
    e.preventDefault();
    const cur=_catKb[dropId]??-1;
    const next=e.key==='ArrowDown'?(cur+1)%opts.length:cur<=0?opts.length-1:cur-1;
    opts.forEach(o=>o.classList.remove('kb-active')); opts[next].classList.add('kb-active'); opts[next].scrollIntoView({block:'nearest'}); _catKb[dropId]=next;
  }
  if(e.key==='Enter'||e.key==='Tab'){
    const cur=_catKb[dropId];
    if(cur>=0&&opts[cur]){e.preventDefault();e.stopPropagation();opts[cur].dispatchEvent(new MouseEvent('mousedown',{bubbles:true}));_catKb[dropId]=-1;}
  }
}

// ══ MODALS ══
// ── Custom confirm dialog (replaces window.confirm to avoid Electron UI freeze) ──
let _confirmResolve = null;
function showConfirmDialog(title, detail = '', okLabel = 'Confirmar', danger = false, detailIsHtml = false) {
  return new Promise(resolve => {
    _confirmResolve = resolve;
    const el = G('modal-confirm');
    if (!el) { resolve(true); return; }
    G('modal-confirm-title').textContent  = title;
    // Por padrão o detalhe é texto puro (.textContent, seguro contra HTML
    // acidental). Só quando quem chama sinaliza detailIsHtml=true usamos
    // innerHTML — usado, por ex., pela exclusão em lote do patrimônio, que
    // monta uma lista formatada do que será apagado.
    const detailEl = G('modal-confirm-detail');
    if (detailIsHtml) detailEl.innerHTML = detail; else detailEl.textContent = detail;
    const okBtn = G('modal-confirm-ok');
    okBtn.textContent = okLabel;
    okBtn.className = danger ? 'btn danger' : 'btn primary';
    el.classList.add('open');
    // Focus the cancel button for safety
    setTimeout(() => G('modal-confirm-cancel')?.focus(), 50);
  });
}
function confirmDialogResolve(result) {
  closeModal('modal-confirm');
  if (_confirmResolve) { _confirmResolve(result); _confirmResolve = null; }
}

let _promptResolve = null;
function showPromptDialog(title, detail = '', defaultValue = '') {
  return new Promise(resolve => {
    _promptResolve = resolve;
    const el = G('modal-prompt');
    if (!el) { resolve(null); return; }
    G('modal-prompt-title').textContent  = title;
    G('modal-prompt-detail').textContent = detail;
    const inp = G('modal-prompt-input');
    inp.value = defaultValue;
    el.classList.add('open');
    setTimeout(() => { inp.focus(); inp.select(); }, 50);
  });
}
function promptDialogResolve(confirmed) {
  const value = G('modal-prompt-input')?.value?.trim() || '';
  closeModal('modal-prompt');
  if (_promptResolve) { _promptResolve(confirmed ? value : null); _promptResolve = null; }
}

// Generic info modal — shows a title + arbitrary HTML body, with just a close button.
function showInfoModal(title, bodyHtml, widthPx) {
  if (G('modal-info-title')) G('modal-info-title').textContent = title;
  if (G('modal-info-body'))  G('modal-info-body').innerHTML    = bodyHtml;
  const modalEl = G('modal-info')?.querySelector('.modal');
  if (modalEl) modalEl.style.width = (widthPx || 560) + 'px';
  openModal('modal-info');
}
function closeInfoModal() { closeModal('modal-info'); }
document.addEventListener('keydown', e => {
  if (!G('modal-confirm')?.classList.contains('open')) return;
  if (e.key === 'Escape') { e.preventDefault(); confirmDialogResolve(false); }
  if (e.key === 'Enter')  { e.preventDefault(); confirmDialogResolve(true);  }
});

function openModal(id){
  G(id)?.classList.add('open');
  // O atalho de Enter (onkeydown na .modal) só dispara pra eventos que
  // borbulham de DENTRO do modal — se o foco ficar em algum elemento de
  // fora (ex: o campo que disparou a abertura, atrás do overlay), o Enter
  // nunca chega no handler. openModal() nunca movia o foco pra dentro do
  // modal, então o Enter parecia simplesmente "não funcionar".
  if (id === 'modal-transfer') setTimeout(() => G('tr-amount')?.focus(), 50);
  else if (id === 'modal-tx') setTimeout(() => G('tx-memo')?.focus(), 50);
}
function closeModal(id){
  const el = G(id);
  if (!el) return;
  // If the user closes the tx modal via X/Cancelar (not Salvar) while an AI queue
  // is running, treat it as "stop the queue" rather than silently skipping ahead.
  if (id === 'modal-tx' && window._aiQueueActive && !window._aiQueueJustSaved) {
    window._aiQueueActive = false;
    _aiQueuedTxs = []; _aiQueueIndex = 0;
  }
  window._aiQueueJustSaved = false;
  // Blur only elements strictly inside this modal
  const focused = el.querySelector(':focus');
  if (focused) focused.blur();
  el.classList.remove('open');
  // Never call document.body.focus() — it freezes subsequent input
}
// Modals close only via explicit Cancel/close buttons or the Escape key —
// clicking outside (or releasing a drag-selection outside) no longer closes
// them, to avoid accidental dismissal while selecting text in a field.
document.addEventListener('keydown', e => {
  if (e.key !== 'Escape') return;
  // Don't interfere with inline-editors or dropdowns that handle their own Escape
  // (they call e.preventDefault()/stopPropagation() in their own listeners, but
  // as a safeguard we only act here if nothing else has already handled it).
  if (e.defaultPrevented) return;
  const openModals = [...document.querySelectorAll('.overlay.open')];
  if (!openModals.length) return;
  // Close the last-opened (topmost) modal only
  const top = openModals[openModals.length - 1];
  if (top.id === 'modal-confirm' || top.id === 'modal-password') return; // handled by their own listeners
  closeModal(top.id);
});

// ── Password prompt (for encrypted XLSX/PDF imports) ──
let _passwordResolve = null;
function showPasswordPrompt(title, detail, errorMsg = '') {
  return new Promise(resolve => {
    _passwordResolve = resolve;
    const el = G('modal-password');
    if (!el) { resolve(null); return; }
    G('modal-password-title').textContent  = title;
    G('modal-password-detail').textContent = detail;
    const inp = G('modal-password-input');
    inp.value = '';
    const errEl = G('modal-password-error');
    if (errorMsg) { errEl.textContent = errorMsg; errEl.style.display = 'block'; }
    else { errEl.style.display = 'none'; }
    el.classList.add('open');
    setTimeout(() => inp?.focus(), 50);
  });
}
function passwordDialogResolve(confirmed) {
  const value = confirmed ? (G('modal-password-input')?.value || '') : null;
  closeModal('modal-password');
  if (_passwordResolve) { _passwordResolve(value); _passwordResolve = null; }
}
document.addEventListener('keydown', e => {
  if (!G('modal-password')?.classList.contains('open')) return;
  if (e.key === 'Escape') { e.preventDefault(); passwordDialogResolve(false); }
});

// ── Pede pro usuário informar manualmente o mês/ano de um extrato quando a
// detecção automática falha (ex: extrato PDF com mês/ano ilegível) ──
// Retorna { month, year } ou null se o usuário cancelar.
let _monthYearResolve = null;
function showMonthYearPrompt(title, detail) {
  return new Promise(resolve => {
    _monthYearResolve = resolve;
    const el = G('modal-monthyear');
    if (!el) { resolve(null); return; }
    G('modal-monthyear-title').textContent  = title;
    G('modal-monthyear-detail').textContent = detail;
    const inp = G('modal-monthyear-input');
    inp.value = '';
    const errEl = G('modal-monthyear-error');
    errEl.style.display = 'none';
    el.classList.add('open');
    setTimeout(() => inp?.focus(), 50);
  });
}
function monthYearDialogResolve(confirmed) {
  if (!confirmed) {
    closeModal('modal-monthyear');
    if (_monthYearResolve) { _monthYearResolve(null); _monthYearResolve = null; }
    return;
  }
  const raw = G('modal-monthyear-input')?.value || ''; // formato 'YYYY-MM' (input type=month)
  const m = raw.match(/^(\d{4})-(\d{2})$/);
  if (!m) {
    const errEl = G('modal-monthyear-error');
    errEl.textContent = '❌ Informe o mês/ano do extrato.';
    errEl.style.display = 'block';
    return;
  }
  closeModal('modal-monthyear');
  if (_monthYearResolve) {
    _monthYearResolve({ year: parseInt(m[1]), month: parseInt(m[2]) });
    _monthYearResolve = null;
  }
}
document.addEventListener('keydown', e => {
  if (!G('modal-monthyear')?.classList.contains('open')) return;
  if (e.key === 'Escape') { e.preventDefault(); monthYearDialogResolve(false); }
});

// ── Decrypt a password-protected XLSX/XLS buffer (e.g. BTG fatura) ──
// Returns the decrypted ArrayBuffer, or null if the user cancels.
// If the file isn't encrypted, returns the original buffer unchanged.
async function decryptOfficeBufferIfNeeded(buffer, fileLabel = 'arquivo') {
  let isEncrypted = false;
  try { isEncrypted = await ff.officeIsEncrypted(buffer); } catch(e) { /* assume not encrypted */ }
  if (!isEncrypted) return buffer;

  let errorMsg = '';
  while (true) {
    const password = await showPasswordPrompt(
      '🔒 Arquivo protegido por senha',
      `O ${fileLabel} está protegido por senha. Informe a senha para abri-lo (geralmente o CPF do titular, sem pontuação).`,
      errorMsg
    );
    if (password === null) return null; // user cancelled
    const result = await ff.officeDecrypt(buffer, password);
    if (result?.ok) return result.buffer;
    errorMsg = '❌ ' + (result?.error?.includes('password') || result?.error?.includes('Decrypt')
      ? 'Senha incorreta. Tente novamente.'
      : (result?.error || 'Senha incorreta. Tente novamente.'));
  }
}






