async function runInvHistoryImport() {
  const fileInput = document.getElementById('inv-import-file-input');
  if (!fileInput.files.length) { toast('Selecione um arquivo .xlsx primeiro.'); return; }

  const btn      = document.getElementById('inv-import-btn');
  const progress = document.getElementById('inv-import-progress');
  const status   = document.getElementById('inv-import-status');
  const bar      = document.getElementById('inv-import-bar');
  const result   = document.getElementById('inv-import-result');

  btn.disabled = true;
  progress.style.display = 'block';
  result.style.display = 'none';

  try {
    // 1. Read file as ArrayBuffer
    status.textContent = 'Lendo arquivo...';
    bar.style.width = '10%';
    const buf = await fileInput.files[0].arrayBuffer();

    // 2. Parse with SheetJS (already available in the app via CDN or bundled)
    status.textContent = 'Interpretando planilha...';
    bar.style.width = '25%';

    // Load SheetJS dynamically if not already loaded
    if (typeof XLSX === 'undefined') {
      await new Promise((resolve, reject) => {
        const s = document.createElement('script');
        s.src = 'https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js';
        s.onload = resolve; s.onerror = reject;
        document.head.appendChild(s);
      });
    }

    const wb = XLSX.read(buf, { type: 'array', cellDates: true });
    const ws = wb.Sheets['Patrimônio'];
    if (!ws) throw new Error('Aba "Patrimônio" não encontrada na planilha.');

    status.textContent = 'Extraindo ativos...';
    bar.style.width = '40%';

    // 3. Build date map: col index -> "YYYY-MM-DD"
    // Col F = 5 (0-based), Col CJ = 87 (0-based)
    const COL_F  = 5;
    const COL_CJ = 87;
    const dateMap = {}; // colIdx -> "YYYY-MM-DD"
    for (let c = COL_F; c <= COL_CJ; c++) {
      const addr = XLSX.utils.encode_cell({ r: 0, c });
      const cell = ws[addr];
      if (cell && cell.t === 'd') {
        const d = cell.v instanceof Date ? cell.v : new Date(cell.v);
        dateMap[c] = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
      } else if (cell && cell.w) {
        // Try to parse formatted date string
        const d = new Date(cell.w);
        if (!isNaN(d)) dateMap[c] = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
      }
    }

    // Helper: get cell value (number) or null
    const cellVal = (r, c) => {
      const cell = ws[XLSX.utils.encode_cell({ r, c })];
      if (!cell) return null;
      if (cell.t === 'n') return cell.v;
      if (cell.t === 's') { const n = parseFloat(cell.v); return isNaN(n) ? null : n; }
      return null;
    };
    const cellStr = (r, c) => {
      const cell = ws[XLSX.utils.encode_cell({ r, c })];
      if (!cell) return '';
      return String(cell.v || '').trim();
    };
    const cellBold = (r, c) => {
      const cell = ws[XLSX.utils.encode_cell({ r, c })];
      return cell && cell.s && cell.s.font && cell.s.font.bold;
    };
    const cellDate = (r, c) => {
      const cell = ws[XLSX.utils.encode_cell({ r, c })];
      if (!cell) return null;
      if (cell.t === 'd') {
        const d = cell.v instanceof Date ? cell.v : new Date(cell.v);
        return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`;
      }
      return null;
    };

    // Range definitions (1-based rows, convert to 0-based)
    const RANGES = [
      { start: 56, end: 103,  categoria: 'renda_fixa',      tipo: 'CDB'                  },
      { start: 112, end: 151, categoria: 'tesouro',          tipo: 'Tesouro IPCA+'        },
      { start: 160, end: 167, categoria: 'previdencia',      tipo: 'PGBL'                 },
      { start: 176, end: 247, categoria: 'fundos',           tipo: 'Fundo de Renda Fixa'  },
      { start: 256, end: 286, categoria: 'fundos',           tipo: 'FII'                  },
      { start: 288, end: 292, categoria: 'renda_variavel',   tipo: 'Ações'                },
      { start: 293, end: 304, categoria: 'fundos',           tipo: 'FII'                  },
      { start: 305, end: 306, categoria: 'renda_variavel',   tipo: 'Ações'                },
    ];

    const assets = [];

    for (const range of RANGES) {
      for (let row1 = range.start; row1 <= range.end; row1++) {
        const r = row1 - 1; // 0-based
        const nameCell = ws[XLSX.utils.encode_cell({ r, c: 0 })];
        if (!nameCell) continue;
        const name = String(nameCell.v || '').trim();
        if (!name) continue;
        // Bold check via style (may not always work with SheetJS in browser, fallback: check row below is "Aportes")
        const isBold = cellBold(r, 0);
        const rowBelow = cellStr(r + 1, 0);
        const isAssetRow = isBold || rowBelow === 'Aportes';
        if (!isAssetRow) continue;

        const broker       = cellStr(r, 1);
        const maturityRaw  = cellDate(r, 2);

        // Collect valores (row r) and aportes (row r+1)
        const valores  = {};
        const aportes  = {};
        for (let c = COL_F; c <= COL_CJ; c++) {
          const dateStr = dateMap[c];
          if (!dateStr) continue;
          const v = cellVal(r, c);
          if (v != null && v !== 0) valores[dateStr] = v;
          const a = cellVal(r + 1, c);
          // Invert: positive in sheet = saída (compra) → negative in FF = aporte positivo
          if (a != null && a !== 0) aportes[dateStr] = -a;
        }

        assets.push({ name, broker, maturity_month: maturityRaw, categoria: range.categoria, tipo: range.tipo, valores, aportes });
      }
    }

    // Special case: linha 318 = valor em caixa (só valores, sem aportes separados)
    {
      const r = 317; // 0-based
      const broker = cellStr(r, 1);
      const valores = {};
      for (let c = COL_F; c <= COL_CJ; c++) {
        const dateStr = dateMap[c];
        if (!dateStr) continue;
        const v = cellVal(r, c);
        if (v != null && v !== 0) valores[dateStr] = v;
      }
      assets.push({ name: 'Valores em Caixa', broker, maturity_month: null, categoria: 'valor_em_caixa', tipo: 'Caixa', valores, aportes: {} });
    }

    status.textContent = `Encontrados ${assets.length} ativos. Salvando no banco...`;
    bar.style.width = '65%';

    // 4. Send to main process
    const res = await ff.invBulkImportHistory({ assets });

    bar.style.width = '100%';
    status.textContent = 'Concluído!';

    result.style.display = 'block';
    result.style.background = 'var(--green-bg, #d4edda)';
    result.style.color = 'var(--green-text, #155724)';
    result.innerHTML = `
      ✅ <strong>Importação concluída!</strong><br>
      • ${res.createdAssets} ativo(s) criado(s)<br>
      • ${res.updatedAssets} ativo(s) atualizado(s)<br>
      • ${res.createdTx} transações importadas
    `;

    const doneBtn = document.getElementById('inv-import-btn');
    doneBtn.textContent = '✓ Feito';
    doneBtn.onclick = () => document.getElementById('inv-history-import-modal').remove();
    doneBtn.disabled = false;
    await refreshPatrimonioTable();

  } catch (err) {
    console.error('Erro na importação:', err);
    bar.style.width = '100%';
    bar.style.background = 'var(--red, #dc3545)';
    result.style.display = 'block';
    result.style.background = 'var(--red-bg, #f8d7da)';
    result.style.color = 'var(--red-text, #721c24)';
    result.innerHTML = `❌ <strong>Erro:</strong> ${err.message}`;
    btn.disabled = false;
  }
}

async function openInvAssetModal(id) {
  const now = new Date();
  G('inv-asset-id').value = id || '';
  G('inv-name').value = '';
  G('inv-code').value = '';
  G('inv-category').value = 'renda_fixa';
  invUpdateTypes();
  G('inv-notes').value   = '';
  G('inv-broker').value  = '';
  G('inv-mat-m').value   = '';
  G('inv-mat-y').value   = '';
  if (G('inv-liq-venc'))  { G('inv-liq-venc').checked = true; }
  if (G('inv-liq-dias'))  { G('inv-liq-dias').checked = false; }
  if (G('inv-liq-days'))  { G('inv-liq-days').value = ''; G('inv-liq-days').disabled = true; }
  if (G('inv-liq-label')) { G('inv-liq-label').textContent = ''; }
  G('inv-sold-m').value   = '';
  G('inv-sold-y').value   = '';
  setupCurrencyInput(G('inv-sold-value'));
  G('inv-sold-value').setValue(null);
  G('inv-hidden').checked = false;
  if (G('inv-benchmark')) G('inv-benchmark').value = 'cdi';
  G('inv-asset-modal-title').textContent = id ? 'Editar investimento' : 'Novo investimento';
  await invLoadBrokers();

  if (id) {
    const a = _inv.assets.find(a => a.id === id);
    if (a) {
      G('inv-name').value     = a.name;
      G('inv-code').value     = a.code || '';
      G('inv-category').value = a.category;
      invUpdateTypes();
      G('inv-type').value     = a.inv_type;
      G('inv-notes').value    = a.notes || '';
      G('inv-broker').value   = a.broker || '';
      if (a.maturity_month) {
        const [my, mm] = a.maturity_month.split('-').map(Number);
        G('inv-mat-y').value = my; G('inv-mat-m').value = mm;
      }
      if (a.liquidity === 'dias' && G('inv-liq-dias')) {
        G('inv-liq-dias').checked = true;
        G('inv-liq-days').value = a.liquidity_days || '';
        G('inv-liq-days').disabled = false;
      }
      invUpdateLiqLabel();
      // Venda / saída
      if (a.closed_month) {
        const [sy, sm] = a.closed_month.split('-').map(Number);
        G('inv-sold-y').value = sy;
        G('inv-sold-m').value = sm;
      }
      if (a.hidden) G('inv-hidden').checked = true;
      if (G('inv-benchmark')) G('inv-benchmark').value = a.benchmark || 'cdi';
      const txs = await ff.invTxList({ assetId: id });
      // Pre-fill sold value from existing venda transaction
      const vendaTx = [...txs].reverse().find(t => t.tx_type === 'venda' && t.notes === 'Venda registrada na saída');
      if (vendaTx) G('inv-sold-value').setValue(vendaTx.total_value);
      renderInvHistoryTable(txs);
    }
  } else {
    // Se vier de "Inserir dados manualmente" ou de "🆕 Ativo novo" numa
    // movimentação não identificada, pré-preenche o primeiro mês com o que
    // já se sabe — evita repetir a posição/movimentação no modal completo,
    // e evita salvar a mesma coisa duas vezes (aqui E depois de novo).
    const pending = _pendingBrokerAssetLink;
    let prefillMonth = null, prefillValue = null, prefillExt = null, prefillInc = null;
    if (pending?.kind === 'manual') {
      prefillMonth = pending.month;
      prefillValue = pending.positionValue || null;
      prefillExt = pending.movType === 'compra' ? -(pending.movValue||0) : pending.movType === 'venda' ? (pending.movValue||0) : null;
      prefillInc = pending.movType === 'dividendo' ? (pending.movValue||0) : pending.movType === 'taxa' ? -(pending.movValue||0) : null;
    } else if (pending?.kind === 'unresolved') {
      const p = G('broker-preview')?._parsed;
      const m = p?.unresolvedMovements?.[pending.movementIdx];
      if (m) {
        prefillMonth = (m.date || '').slice(0,7);
        if (m.suggestedFlowType === 'external')   prefillExt = m.amount;
        else if (m.suggestedFlowType === 'income') prefillInc = m.amount;
        else prefillExt = m.amount; // sem classificação sugerida — trata como fluxo externo por padrão
      }
    }
    G('inv-history-table').innerHTML = invHistoryHeaderHtml() + invHistoryRowHtml(
      prefillMonth || `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`,
      prefillValue, prefillExt, prefillInc, 0
    );
  }
  openModal('modal-inv-asset');
}

async function invCloseAsset() {
  const id = parseInt(G('inv-asset-id').value);
  if (!id) return;
  // Find last month with data to use as close month
  const rows = G('inv-history-table')?.querySelectorAll('[data-month]') || [];
  const months = [...rows].map(r => r.dataset.month).sort();
  const closedMonth = months[months.length - 1] || null;
  if (!closedMonth) { toast('Adicione pelo menos um mês de dados antes de encerrar'); return; }
  if (!await showConfirmDialog(`Encerrar este ativo em ${fmtMonth(closedMonth)}?`, 'O ativo será marcado como encerrado nesta data.', 'Encerrar', true)) return;
  const a = _inv.assets.find(a => a.id === id);
  await ff.invAssetSave({ ...a, closed_month: closedMonth });
  toast(`✅ Ativo encerrado em ${fmtMonth(closedMonth)}`);
  closeModal('modal-inv-asset');
  await refreshInvestimentos();
  refreshPatrimonioTable();
}

async function saveInvAsset() {
  // Read ALL values from DOM FIRST
  const id       = G('inv-asset-id').value ? parseInt(G('inv-asset-id').value) : null;
  const name     = G('inv-name').value.trim();
  const code     = G('inv-code').value.trim() || null;
  const category = G('inv-category').value;
  const inv_type = G('inv-type').value;
  const notes    = G('inv-notes').value.trim() || null;
  const broker   = G('inv-broker').value.trim() || null;
  const matM     = parseInt(G('inv-mat-m')?.value);
  const matY     = parseInt(G('inv-mat-y')?.value);
  const maturity_month = (matM >= 1 && matM <= 12 && matY >= 2000) ? `${matY}-${String(matM).padStart(2,'0')}` : null;
  const isDias   = G('inv-liq-dias')?.checked;
  const liquidity      = isDias ? 'dias' : 'vencimento';
  const liquidity_days = isDias ? (parseInt(G('inv-liq-days')?.value) || null) : null;
  const soldM    = parseInt(G('inv-sold-m')?.value);
  const soldY    = parseInt(G('inv-sold-y')?.value);
  const invSoldEl = G('inv-sold-value'); const soldValue = invSoldEl?.rawValue ? (invSoldEl.rawValue()||null) : (parseFloat(invSoldEl?.value)||null);
  const closed_month = (soldM >= 1 && soldM <= 12 && soldY >= 2000) ? `${soldY}-${String(soldM).padStart(2,'0')}` : null;
  const hidden    = G('inv-hidden')?.checked ? 1 : 0;
  const benchmark = G('inv-benchmark')?.value || 'cdi';

  // Read all history rows before closing modal
  const rows = [...document.querySelectorAll('#inv-history-table [data-month]')].map(row => {
    const mo = row.querySelector('.inv-hist-mo')?.value;
    const yr = row.querySelector('.inv-hist-yr')?.value;
    const month = (mo && yr) ? `${yr}-${String(mo).padStart(2,'0')}` : row.dataset.month;
    return {
      month,
      valueStr:    row.querySelector('.inv-hist-value')?.value?.trim()    || '',
      externalStr: row.querySelector('.inv-hist-external')?.value?.trim() || '',
      incomeStr:   row.querySelector('.inv-hist-income')?.value?.trim()   || '',
      // Legacy: if old single-column format was in use, fall back to it
      cashStr:     row.querySelector('.inv-hist-cash')?.value?.trim()     || '',
    };
  }).filter(r => r.month);

  if (!name) { toast('Informe o nome do ativo'); return; }

  closeModal('modal-inv-asset');

  try {
    // 1. Save asset record
    const existing = id ? _inv.assets.find(a => a.id === id) : null;
    const result = await ff.invAssetSave({
      id, name, code, category, inv_type,
      sort_order:    existing?.sort_order ?? _inv.assets.length,
      closed_month,
      hidden,
      notes, broker, maturity_month, liquidity, liquidity_days, benchmark,
    });
    const assetId = result?.id;
    if (!assetId) throw new Error('Asset ID não retornado pelo servidor');

    // 2. Delete all existing transactions for this asset
    const existingTxs = await ff.invTxList({ assetId });
    for (const t of existingTxs) {
      await ff.invTxDelete({ id: t.id });
    }

    // 3. Save each row sequentially
    let savedRows = 0;
    for (const row of rows) {
      const { month, valueStr, externalStr, incomeStr, cashStr } = row;
      if (!month) continue;
      const value    = valueStr ? parseFloat(valueStr.replace(',','.')) : null;
      const external = externalStr ? evalFormula(externalStr) : null;
      const income   = incomeStr   ? evalFormula(incomeStr)   : null;
      // Legacy fallback: if only old cashStr is present, route by sign
      const legacyCash = (!externalStr && !incomeStr && cashStr) ? evalFormula(cashStr) : null;

      if (value != null && isFinite(value) && value > 0) {
        await ff.invTxSave({
          id: null, asset_id: assetId, month,
          tx_type: 'atualizacao', qty: null, unit_value: null, total_value: value, notes: null
        });
        savedRows++;
      }
      // External capital flow (compra if negative, venda if positive)
      if (external != null && external !== 0) {
        const txType = external < 0 ? 'compra' : 'venda';
        await ff.invTxSave({
          id: null, asset_id: assetId, month,
          tx_type: txType, qty: null, unit_value: null, total_value: Math.abs(external), notes: null
        });
        savedRows++;
      }
      // Income / cost flow (dividendo if positive, taxa if negative)
      if (income != null && income !== 0) {
        const txType = income > 0 ? 'dividendo' : 'taxa';
        await ff.invTxSave({
          id: null, asset_id: assetId, month,
          tx_type: txType, qty: null, unit_value: null, total_value: Math.abs(income), notes: null
        });
        savedRows++;
      }
      // Legacy single-column fallback
      if (legacyCash != null && legacyCash !== 0) {
        const txType = legacyCash < 0 ? 'compra' : 'dividendo';
        await ff.invTxSave({
          id: null, asset_id: assetId, month,
          tx_type: txType, qty: null, unit_value: null, total_value: Math.abs(legacyCash), notes: null
        });
        savedRows++;
      }
    }

    // 4. If a sale value was provided, insert venda transaction + zero valuation on closed_month
    if (soldValue != null && closed_month) {
      await ff.invTxSave({
        id: null, asset_id: assetId, month: closed_month,
        tx_type: 'venda', qty: null, unit_value: null, total_value: soldValue, notes: 'Venda registrada na saída'
      });
      // Zero out the asset value in the sale month so it shows 0, not negative
      await ff.invTxSave({
        id: null, asset_id: assetId, month: closed_month,
        tx_type: 'atualizacao', qty: null, unit_value: null, total_value: 0, notes: 'Zeragem na venda'
      });
      savedRows++;
    }

    // 5. Auto-insert purchase if no significant negative flow in first month
    const purchaseCheck = await ff.invEnsurePurchase({ assetId });
    if (purchaseCheck?.inserted) {
      console.log(`[auto-purchase] Inserted for asset ${assetId}: ${purchaseCheck.month} = ${purchaseCheck.value}`);
    }

    // 6. Full reload from DB then render
    await refreshPatrimonio();
    toast(`✅ Investimento ${id ? 'atualizado' : 'criado'} (${savedRows} registros)`);

    // Se este ativo foi criado a partir da importação de corretora (botão
    // "🆕 Ativo novo" numa movimentação não identificada, ou "criar ativo
    // manualmente"), conclui o vínculo automaticamente com o ativo
    // recém-criado.
    if (_pendingBrokerAssetLink && !id) {
      const link = _pendingBrokerAssetLink;
      _pendingBrokerAssetLink = null;
      await completeBrokerAssetLink(assetId, name, link);
    }
  } catch(e) {
    toast(`❌ Erro ao salvar: ${e.message}`);
    console.error('saveInvAsset error:', e);
  }
}

// Conclui o vínculo pendente de uma movimentação de corretora com o ativo
// de investimento recém-criado — salva a movimentação direto no banco (o
// ativo já existe de fato, diferente do array p.assets da pré-visualização,
// que é só um rascunho ainda não persistido). Usa o MESMO mapeamento
// flow_type → tx_type do backend (broker:save-parsed), pra ficar
// consistente com o que a importação normal gera.
async function completeBrokerAssetLink(assetId, assetName, link) {
  // A posição/movimentação já foi salva pelo fluxo normal do modal (estava
  // pré-preenchida na tabela de histórico) — aqui só falta, no caso de uma
  // movimentação que estava "não identificada", removê-la da lista e
  // atualizar a pré-visualização.
  if (link.kind === 'unresolved') {
    const preview = G('broker-preview');
    const p = preview?._parsed;
    if (!p) return;
    if (p.unresolvedMovements[link.movementIdx]) p.unresolvedMovements.splice(link.movementIdx, 1);
    toast(`✅ Movimentação vinculada ao novo ativo "${assetName}"`);
    renderBrokerPreview(p);
  }
}

// Salva posição (atualizacao) e/ou movimentação direto num ativo de
// investimento JÁ EXISTENTE, a partir do formulário "Inserir dados
// manualmente" — quando o ativo é novo, os mesmos dados vão pelo modal
// completo (pré-preenchidos) em vez de passar por aqui.
async function applyManualEntryToAsset(assetId, month, posValue, movType, movValue, assetName) {
  try {
    if (posValue) {
      await ff.invTxSave({ id:null, asset_id:assetId, month, tx_type:'atualizacao', qty:null, unit_value:null, total_value: Math.abs(posValue), notes: '__manual_entry__' });
    }
    if (movType && movValue) {
      await ff.invTxSave({ id:null, asset_id:assetId, month, tx_type: movType, qty:null, unit_value:null, total_value: Math.abs(movValue), notes: '__manual_entry__' });
    }
    toast(assetName ? `✅ Dados adicionados ao ativo "${assetName}"` : '✅ Dados adicionados manualmente');
  } catch(e) {
    console.error('Erro ao inserir dados manualmente:', e);
    toast('❌ Erro ao salvar — tente novamente');
  }
}

// ── Detail modal ──
async function openInvDetail(assetId) {
  const a = _inv.assets.find(a => a.id === assetId);
  if (!a) return;
  const txs = await ff.invTxList({ assetId });
  G('inv-detail-title').textContent = `${a.name}${a.code ? ` (${a.code})` : ''}`;

  const cat = INV_CATEGORIES[a.category]?.label || a.category;
  const liqLabel = a.liquidity === 'dias'
    ? `D+${a.liquidity_days || 0} dias`
    : a.maturity_month ? `No vencimento (${fmtMonth(a.maturity_month)})` : 'No vencimento';
  let html = `<div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px;margin-bottom:16px">
    <div><div style="font-size:11px;color:var(--text3)">Categoria</div><div style="font-size:13px">${cat}</div></div>
    <div><div style="font-size:11px;color:var(--text3)">Tipo</div><div style="font-size:13px">${a.inv_type}</div></div>
    <div><div style="font-size:11px;color:var(--text3)">Status</div><div style="font-size:13px">${a.closed_month?`Encerrado ${fmtMonth(a.closed_month)}`:'Ativo'}</div></div>
    ${a.broker?`<div><div style="font-size:11px;color:var(--text3)">Corretora</div><div style="font-size:13px">${esc(a.broker)}</div></div>`:''}
    ${a.maturity_month?`<div><div style="font-size:11px;color:var(--text3)">Vencimento</div><div style="font-size:13px">${fmtMonth(a.maturity_month)}</div></div>`:''}
    <div><div style="font-size:11px;color:var(--text3)">Liquidez</div><div style="font-size:13px">${liqLabel}</div></div>
    ${a.notes?`<div style="grid-column:1/-1"><div style="font-size:11px;color:var(--text3)">Notas</div><div style="font-size:13px">${esc(a.notes)}</div></div>`:''}
  </div>`;

  html += `<table style="width:100%;border-collapse:collapse;font-size:12px">
    <thead><tr style="border-bottom:2px solid var(--border2)">
      <th style="padding:6px 10px;text-align:left">Tipo</th>
      <th style="padding:6px 10px;text-align:left">Mês</th>
      <th style="padding:6px 10px;text-align:right">Qtd</th>
      <th style="padding:6px 10px;text-align:right">Valor unit.</th>
      <th style="padding:6px 10px;text-align:right">Total</th>
    </tr></thead><tbody>`;

  let totalFlow = 0;
  txs.forEach(t => {
    const sign = INV_TX_TYPES[t.tx_type]?.sign ?? 1;
    const signedTotal = sign * t.total_value;
    totalFlow += signedTotal;
    const label = INV_TX_TYPES[t.tx_type]?.label || t.tx_type;
    const cls = signedTotal >= 0 ? 'amt-inc' : 'amt-exp';
    html += `<tr style="border-bottom:1px solid var(--border)">
      <td style="padding:5px 10px">${label}</td>
      <td style="padding:5px 10px;color:var(--text2)">${fmtMonth(t.month)}</td>
      <td class="right" style="padding:5px 10px;color:var(--text2)">${t.qty ? t.qty.toLocaleString('pt-BR',{maximumFractionDigits:4}) : '—'}</td>
      <td class="right" style="padding:5px 10px;color:var(--text2)">${t.unit_value ? fmtBRL(t.unit_value) : '—'}</td>
      <td class="${cls} right" style="padding:5px 10px;font-family:'DM Mono',monospace">${fmtBRL(t.total_value)}</td>
    </tr>`;
  });

  const lclTotal = totalFlow >= 0 ? 'amt-inc' : 'amt-exp';
  html += `</tbody><tfoot><tr style="border-top:2px solid var(--border2);font-weight:700">
    <td colspan="4" style="padding:7px 10px">Resultado (entradas − saídas)</td>
    <td class="${lclTotal} right" style="padding:7px 10px;font-family:'DM Mono',monospace">${fmtBRL(totalFlow)}</td>
  </tr></tfoot></table>`;

  G('inv-detail-body').innerHTML = html;
  openModal('modal-inv-detail');
}

async function deleteInvAsset(id) {
  const a = _inv.assets.find(a => a.id === id);
  if (!await showConfirmDialog(`Excluir "${a?.name}"?`, 'Todas as movimentações serão removidas. Esta ação não pode ser desfeita.', 'Excluir', true)) return;
  await ff.invAssetDelete({ id });
  toast('Investimento removido');
  await refreshInvestimentos();
  refreshPatrimonioTable();
}

// ── IRR calculation (XIRR monthly → annual) ──
// TIR real por ativo individual — mesma lógica usada na tabela de Patrimônio (buildInvRows),
// extraída para reuso (ex.: sugestões de liquidação na Projeção de Fluxo de Caixa).
// txs: transações do ativo (qualquer formato com tx_type, month, total_value)
// ipcaCumFn: função(mês) → fator de correção IPCA acumulado até curM
// curM: mês corrente 'YYYY-MM'
function calcAssetRealIRR(txs, ipcaCumFn, curM) {
  if (!txs.length) return null;
  const txMonths = [...new Set(txs.map(t => t.month.slice(0,7)))].sort();
  if (!txMonths.length) return null;

  const monthlyNetCash = {};
  const bookValueByM = {};
  let running = 0;

  txMonths.forEach(m => {
    let lastValuation = null;
    txs.filter(t => t.month.slice(0,7) === m).forEach(t => {
      if (t.tx_type in INV_TX_EXTERNAL) {
        const sign = INV_TX_EXTERNAL[t.tx_type].sign;
        monthlyNetCash[m] = (monthlyNetCash[m] || 0) + sign * t.total_value;
      } else if (t.tx_type in INV_TX_INCOME) {
        const sign = INV_TX_INCOME[t.tx_type].sign;
        monthlyNetCash[m] = (monthlyNetCash[m] || 0) + sign * t.total_value;
      } else if (t.tx_type in INV_TX_VALUATION) {
        lastValuation = t.total_value;
      }
    });
    if (lastValuation !== null) { running = lastValuation; bookValueByM[m] = running; }
  });

  // Propaga o valor contábil até o mês corrente
  let lastVal = 0;
  const allM = [];
  let m = txMonths[0];
  while (m <= curM) { allM.push(m); const [y,mo]=m.split('-').map(Number); m = mo===12?`${y+1}-01`:`${y}-${String(mo+1).padStart(2,'0')}`; }
  allM.forEach(mm => { if (bookValueByM[mm] !== undefined) lastVal = bookValueByM[mm]; });
  const latestVal = bookValueByM[curM] ?? lastVal;

  const hasCashFlows = Object.keys(monthlyNetCash).length > 0;
  if (!hasCashFlows) return null;

  const realFlows = allM.map(mm => (monthlyNetCash[mm] ?? 0) * ipcaCumFn(mm));
  realFlows[realFlows.length - 1] += latestVal; // venda hipotética hoje
  return calcIRR(realFlows);
}

function calcIRR(cashflows) {
  // Newton-Raphson monthly IRR, then annualize
  if (!cashflows.length) return null;
  let rate = 0.01;
  for (let iter = 0; iter < 200; iter++) {
    let npv = 0, dnpv = 0;
    cashflows.forEach((cf, i) => {
      npv  += cf / Math.pow(1 + rate, i);
      dnpv -= i * cf / Math.pow(1 + rate, i + 1);
    });
    if (Math.abs(dnpv) < 1e-10) break;
    const newRate = rate - npv / dnpv;
    if (Math.abs(newRate - rate) < 1e-8) { rate = newRate; break; }
    rate = newRate;
  }
  if (!isFinite(rate) || rate <= -1) return null;
  return Math.pow(1 + rate, 12) - 1; // annualize
}

// ── Build inv rows for the patrimônio table ──
function buildInvRows(months, curM, STICKY, COL_W, stripe, showHidden, visMonths) {
  visMonths = visMonths || months;
  if (!_inv.assets.length) return '';

  const showReal = _inv.showRealFlow;
  let visibleAssets = _inv.assets.filter(a => showHidden || !a.hidden);

  // Filtros (corretora / categoria / tipo / liquidez)
  const fBroker = G('patf-inv-broker')?.value || '';
  const fCat    = G('patf-inv-category')?.value || '';
  const fType   = G('patf-inv-type')?.value || '';
  const fLiq    = G('patf-inv-liquidity')?.value || '';
  if (fBroker) visibleAssets = visibleAssets.filter(a => (a.broker||'') === fBroker);
  if (fCat)    visibleAssets = visibleAssets.filter(a => (_isCashAsset(a) ? 'valor_em_caixa' : (a.category||'renda_fixa')) === fCat);
  if (fType)   visibleAssets = visibleAssets.filter(a => (a.inv_type||'') === fType);
  if (fLiq) {
    visibleAssets = visibleAssets.filter(a => {
      const d = _invLiquidityDays(a);
      if (fLiq === 'immediate') return d <= 30;
      if (fLiq === 'short')     return d > 30 && d <= 365;
      if (fLiq === 'long')      return d > 365 && d !== Infinity;
      if (fLiq === 'undefined') return d === Infinity;
      return true;
    });
  }
  if (!visibleAssets.length) return '';

  // Group transactions by asset and month
  const txByAsset = {};
  _inv.txAll.forEach(t => {
    const tm = t.month.slice(0,7); // normalize YYYY-MM-DD → YYYY-MM
    if (!txByAsset[t.asset_id]) txByAsset[t.asset_id] = {};
    if (!txByAsset[t.asset_id][tm]) txByAsset[t.asset_id][tm] = [];
    txByAsset[t.asset_id][tm].push(t);
  });

  // Ordenação — aplicada antes do agrupamento por categoria abaixo, então a
  // ordem escolhida vale DENTRO de cada categoria (o agrupamento em si não
  // muda, só a ordem dos ativos dentro de cada grupo).
  const sortInvBy = G('patf-inv-sort')?.value || 'manual';
  if (sortInvBy === 'name') {
    visibleAssets = [...visibleAssets].sort((a,b) => a.name.localeCompare(b.name, 'pt-BR'));
  } else if (sortInvBy === 'broker') {
    visibleAssets = [...visibleAssets].sort((a,b) => (a.broker||'').localeCompare(b.broker||'', 'pt-BR'));
  } else if (sortInvBy === 'liquidity') {
    visibleAssets = [...visibleAssets].sort((a,b) => _invLiquidityDays(a) - _invLiquidityDays(b));
  } else if (sortInvBy === 'value_desc' || sortInvBy === 'value_asc') {
    const valOf = a => _invAssetCurrentValue(a, txByAsset, curM);
    visibleAssets = [...visibleAssets].sort((a,b) => sortInvBy === 'value_desc' ? valOf(b)-valOf(a) : valOf(a)-valOf(b));
  } // else 'manual' — mantém sort_order

  // IPCA cumulative from a month to curM
  function ipcaCumulative(fromMonth) {
    let cum = 1;
    let m = fromMonth;
    while (m < curM) {
      const [y, mo] = m.split('-').map(Number);
      const next = mo === 12 ? `${y+1}-01` : `${y}-${String(mo+1).padStart(2,'0')}`;
      const rate = _pat.ipcaMonthly[next] ?? 0;
      cum *= (1 + rate);
      m = next;
    }
    return cum;
  }

  const now = new Date();
  const nextM = (() => {
    const d = new Date(now.getFullYear(), now.getMonth() + 1, 1);
    return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
  })();

  // Group visible assets by category (for rendering rows)
  const byCategory = {};
  visibleAssets.forEach(a => {
    const cat = _isCashAsset(a) ? 'valor_em_caixa' : (a.category || 'renda_fixa');
    if (!byCategory[cat]) byCategory[cat] = [];
    byCategory[cat].push(a);
  });
  // Group ALL assets by category (including hidden) — for correct subtotal P&L
  const byCategoryAll = {};
  _inv.assets.forEach(a => {
    const cat = _isCashAsset(a) ? 'valor_em_caixa' : (a.category || 'renda_fixa');
    if (!byCategoryAll[cat]) byCategoryAll[cat] = [];
    byCategoryAll[cat].push(a);
  });
  const catKeys = INV_CAT_ORDER.filter(k => byCategory[k]);
  // Any unknown categories at the end
  Object.keys(byCategory).forEach(k => { if (!INV_CAT_ORDER.includes(k)) catKeys.push(k); });

  // Ordem visual dos investimentos (categoria a categoria, na mesma ordem em
  // que as linhas aparecem) — usada para resolver o intervalo do shift+clique.
  patSelResetOrder('inv', catKeys.flatMap(k => byCategory[k].map(a => a.id)));

  // Helper: build a category subtotal row (value + optional cash flow rows)
  function buildCatSubtotalRow(catKey, catAssets, allMonths, txByAsset2, curM2, STICKY2, COL_W2, stripe2, ipcaCumFn, showReal2, nextM2, visAllMonths2) {
    visAllMonths2 = visAllMonths2 || allMonths;
    const catLabel = INV_CATEGORIES[catKey]?.label || catKey;
    const catTotalByMonth = {};
    const catNetCashByMonth = {};

    catAssets.forEach(a => {
      const txs = txByAsset2[a.id] || {};
      const txMonths = [...new Set(Object.keys(txs))].sort();
      if (!txMonths.length) return;

      let running2 = 0;
      const bv = {};
      txMonths.forEach(m2 => {
        let cd = 0, lv = null;
        (txs[m2] || []).forEach(t => {
          if (t.tx_type in INV_TX_CASH) {
            if (t.tx_type in INV_TX_EXTERNAL && INV_TX_EXTERNAL[t.tx_type].sign < 0) cd += t.total_value;
            if (['venda','amortizacao'].includes(t.tx_type)) cd -= t.total_value;
            const sign = INV_TX_CASH[t.tx_type]?.sign ?? 1;
            if (!catNetCashByMonth[m2]) catNetCashByMonth[m2] = 0;
            catNetCashByMonth[m2] += sign * t.total_value;
          } else if (t.tx_type in INV_TX_VALUATION) {
            lv = t.total_value;
          }
        });
        running2 += cd;
        if (lv !== null) running2 = lv;
        bv[m2] = running2;
      });

      let lastVal2 = 0;
      allMonths
        .filter(m2 => m2 >= txMonths[0] && m2 <= (a.closed_month || allMonths[allMonths.length-1]))
        .forEach(m2 => {
          if (bv[m2] !== undefined) lastVal2 = bv[m2];
          catTotalByMonth[m2] = (catTotalByMonth[m2] || 0) + lastVal2;
        });
    });

    const latestCatVal = catTotalByMonth[curM2] || 0;
    const hasCatCash = Object.keys(catNetCashByMonth).length > 0;

    // TIR for this category
    let catIrr = null;
    if (hasCatCash && latestCatVal > 0) {
      const irrMs = allMonths.filter(m2 => {
        const firstCashM = Object.keys(catNetCashByMonth).sort()[0];
        return m2 >= firstCashM;
      });
      const realFlows2 = irrMs.map(m2 => (catNetCashByMonth[m2] ?? 0) * ipcaCumFn(m2));
      realFlows2.push(latestCatVal);
      catIrr = calcIRR(realFlows2);
    }

    const irrLabel2 = catIrr !== null ? `TIR: ${(catIrr*100).toFixed(1)}% a.a.` : '';
    const irrColor2 = catIrr !== null ? (catIrr >= 0 ? 'var(--green)' : 'var(--red)') : 'var(--text3)';

    // Ganho/Perda por categoria: soma simples do fluxo nominal + valor atual
    const _catFlowSum = Object.values(catNetCashByMonth).reduce((s, v) => s + v, 0);
    const catGanho2 = Object.keys(catNetCashByMonth).length > 0 ? _catFlowSum + latestCatVal : null;
    const catGanhoLabel2 = catGanho2 !== null
      ? `${catGanho2 >= 0 ? '▲' : '▼'} ${fmtBRL(Math.abs(catGanho2))}`
      : '';
    const catGanhoColor2 = catGanho2 !== null ? (catGanho2 >= 0 ? 'var(--green)' : 'var(--red)') : 'var(--text3)';

    const BG_SUB = 'var(--bg4)';
    const valueCells2 = visAllMonths2.map(m2 => {
      const v = catTotalByMonth[m2];
      const isCur = m2 === curM2;
      const cellBg = isCur ? 'var(--accent-lt)' : BG_SUB;
      if (!v) return `<td style="padding:5px 8px;background:${cellBg}"></td>`;
      return `<td class="amt-inc right" style="font-weight:600;font-size:12px;padding:5px 8px;background:${cellBg};font-family:'DM Mono',monospace">${fmtBRL(v)}</td>`;
    }).join('');

    const nomFlowCells2 = visAllMonths2.map(m2 => {
      const cf = catNetCashByMonth[m2] ?? 0;
      const isCur = m2 === curM2;
      const cellBg = isCur ? 'var(--accent-lt)' : BG_SUB;
      if (!cf) return `<td class="right" style="font-size:11px;padding:3px 8px;background:${cellBg};color:var(--text3)">—</td>`;
      const cls = cf >= 0 ? 'amt-inc' : 'amt-exp';
      return `<td class="${cls} right" style="font-size:11px;padding:3px 8px;background:${cellBg};font-family:'DM Mono',monospace">${fmtBRL(cf)}</td>`;
    }).join('');

    const realFlowCells2 = visAllMonths2.map(m2 => {
      const cf = catNetCashByMonth[m2] ?? 0;
      const isCur = m2 === curM2;
      const cellBg = isCur ? 'var(--accent-lt)' : BG_SUB;
      if (!cf) return `<td class="right" style="font-size:11px;padding:3px 8px;background:${cellBg};color:var(--text3)">—</td>`;
      const real = cf * ipcaCumFn(m2);
      const cls = real >= 0 ? 'amt-inc' : 'amt-exp';
      return `<td class="${cls} right" style="font-size:11px;padding:3px 8px;background:${cellBg};font-family:'DM Mono',monospace;font-style:italic">${fmtBRL(real)}</td>`;
    }).join('');

    const projVal2 = `<td style="min-width:0;max-width:0;padding:0;border:none;overflow:hidden"></td>`;
    const projNom2 = `<td style="min-width:0;max-width:0;padding:0;border:none;overflow:hidden"></td>`;
    const projReal2= `<td style="min-width:0;max-width:0;padding:0;border:none;overflow:hidden"></td>`;
    const editEmpty= `<td style="${STICKY2};right:0;min-width:60px;background:${BG_SUB}"></td>`;

    const _cgkSub = 'cat-' + catKey;
    const _isCollapsed = _pat.collapsed && _pat.collapsed[_cgkSub];
    const _toggleIcon = _isCollapsed ? '▶' : '▼';
    return `
      <tr style="background:${BG_SUB};border-top:2px solid var(--border2);cursor:pointer"
          onclick="patToggleCatCollapse('${_cgkSub}')">
        <td style="${STICKY2};left:0;min-width:350px;padding:7px 12px;background:${BG_SUB}" colspan="4">
          <span style="font-size:11px;color:var(--text3);margin-right:5px;user-select:none">${_toggleIcon}</span>
          <span style="font-size:12px;font-weight:700;color:var(--text1)">${catLabel}</span>
          ${irrLabel2 ? `<span style="font-size:11px;color:${irrColor2};margin-left:8px" title="${TIR_TOOLTIP}">${irrLabel2}</span>` : ''}
          ${catGanhoLabel2 ? `<span style="font-size:11px;font-weight:700;color:${catGanhoColor2};margin-left:6px" title="Ganho/Perda absoluto">${catGanhoLabel2}</span>` : ''}
        </td>
        ${valueCells2}${projVal2}${editEmpty}
      </tr>
      <tr style="background:${BG_SUB}">
        <td style="${STICKY2};left:0;font-size:10px;color:var(--text3);padding:2px 12px;background:${BG_SUB}" colspan="4">📊 Fluxo nominal</td>
        ${nomFlowCells2}${projNom2}${editEmpty}
      </tr>
      ${showReal2 ? `<tr style="background:${BG_SUB}">
        <td style="${STICKY2};left:0;font-size:10px;color:var(--text3);padding:2px 12px;background:${BG_SUB}" colspan="4">📈 Fluxo real (IPCA)</td>
        ${realFlowCells2}${projReal2}${editEmpty}
      </tr>` : ''}`;
  }

  let rows = '';
  let globalRi = 0; // global stripe index across all categories
  catKeys.forEach(catKey => {
    const catAssets = byCategory[catKey];
    catAssets.forEach(a => {
    const isCashAsset = _isCashAsset(a);
    const bg = stripe(globalRi);
    globalRi++;
    const cat = INV_CATEGORIES[a.category]?.label || a.category;
    const txs = txByAsset[a.id] || {};

    // Build cumulative book value and cash flows per month
    const monthlyNetCash  = {}; // all cash flows combined (for IRR/flow line)
    const monthlyExtFlow  = {}; // external capital only (compra/aporte/venda/amortizacao)
    const monthlyIncFlow  = {}; // income/cost only (dividendo/juros/taxa etc.)
    const bookValue       = {}; // cumulative asset value
    let running = 0;

    const txMonths = [...new Set(Object.keys(txs))].sort();

    txMonths.forEach(m => {
      // Step 1: apply cash transactions to running value
      let cashDelta = 0;
      let lastValuation = null;

      (txs[m] || []).forEach(t => {
        if (t.tx_type in INV_TX_EXTERNAL) {
          const sign = INV_TX_EXTERNAL[t.tx_type].sign;
          cashDelta += sign < 0 ? t.total_value : -t.total_value;
          if (!monthlyNetCash[m]) monthlyNetCash[m] = 0;
          monthlyNetCash[m] += sign * t.total_value;
          if (!monthlyExtFlow[m]) monthlyExtFlow[m] = 0;
          monthlyExtFlow[m] += sign * t.total_value;
        } else if (t.tx_type in INV_TX_INCOME) {
          const sign = INV_TX_INCOME[t.tx_type].sign;
          if (!monthlyNetCash[m]) monthlyNetCash[m] = 0;
          monthlyNetCash[m] += sign * t.total_value;
          if (!monthlyIncFlow[m]) monthlyIncFlow[m] = 0;
          monthlyIncFlow[m] += sign * t.total_value;
        } else if (t.tx_type in INV_TX_VALUATION) {
          lastValuation = t.total_value;
        }
      });

      // bookValue only comes from real valuations (atualizacao)
      // cashDelta does NOT contribute to displayed asset value
      if (lastValuation !== null) {
        running = lastValuation;
        bookValue[m] = running;
      }
    });

    // Propagate book value to all months up to curM
    const allM = months.filter(m => m >= (txMonths[0] || curM) && m <= (a.closed_month || curM));
    let lastVal = 0;
    allM.forEach(m => {
      if (bookValue[m] !== undefined) lastVal = bookValue[m];
      else bookValue[m] = lastVal;
    });

    // Latest value (for IRR projection)
    const latestVal = bookValue[curM] ?? lastVal;

    // Only compute IRR and P&L when there are actual cash flows
    const hasCashFlows = Object.keys(monthlyNetCash).length > 0;

    // Build IRR cashflow: sign convention — outflows negative
    // Use only months where the asset is active (from first tx to curM), no leading zeros
    let irr = null;      // real (IPCA-adjusted), shown as TIR label
    let irrNominal = null; // nominal, used for benchmark comparison and nomRetLabel
    if (hasCashFlows) {
      const firstM = txMonths[0];
      const activeMonths = months.filter(m => m >= firstM);
      // Real cashflows (IPCA-adjusted to curM)
      const realFlows = activeMonths.map(m => {
        const cf = monthlyNetCash[m] ?? 0;
        return cf * ipcaCumulative(m);
      });
      realFlows[realFlows.length - 1] += latestVal; // add current value at final period
      irr = calcIRR(realFlows);
      // Nominal cashflows (no IPCA adjustment)
      const nomFlows = activeMonths.map(m => monthlyNetCash[m] ?? 0);
      nomFlows[nomFlows.length - 1] += latestVal; // add current value at final period
      irrNominal = calcIRR(nomFlows);
    }
    const irrColor = (irr === null || isCashAsset) ? 'var(--text3)' : irr >= 0 ? 'var(--green)' : 'var(--red)';
    const irrLabel = isCashAsset ? '' : irr !== null ? `TIR: ${(irr*100).toFixed(1)}% a.a.` : 'TIR: —';

    // P&L = soma simples do fluxo nominal + valor atual (os sinais já estão corretos)
    let pnlLabel = '', pnlColor = 'var(--text3)';
    if (hasCashFlows && !isCashAsset) {
      const pnl = Object.values(monthlyNetCash).reduce((s, v) => s + v, 0) + latestVal;
      pnlLabel = pnl >= 0 ? `▲ ${fmtBRL(pnl)}` : `▼ ${fmtBRL(Math.abs(pnl))}`;
      pnlColor = pnl >= 0 ? 'var(--green)' : 'var(--red)';
    }

    // Benchmark label: compare nominal TIR vs CDI/IBOV (same nominal base)
    let bmkLabel = '';
    if (!isCashAsset && a.benchmark && a.benchmark !== 'nenhum' && irrNominal !== null && txMonths.length) {
      const bmkData = a.benchmark === 'ibov' ? _benchmarks.ibov : _benchmarks.cdi;
      const firstCashM = txMonths[0];
      // Accumulate monthly benchmark rates over the asset's active period
      const bmkRates = [];
      let bm = firstCashM;
      while (bm <= curM) {
        if (bmkData[bm] != null) bmkRates.push(bmkData[bm]);
        const [y, mo] = bm.split('-').map(Number);
        bm = mo === 12 ? `${y+1}-01` : `${y}-${String(mo+1).padStart(2,'0')}`;
      }
      if (bmkRates.length >= 1) {
        // Annualize from the average monthly rate (consistent with IRR annualization)
        const avgMonthlyRate = bmkRates.reduce((a, r) => a + r, 0) / bmkRates.length;
        const bmkAnn = Math.pow(1 + avgMonthlyRate, 12) - 1;
        const diff = irrNominal - bmkAnn;
        const sign = diff >= 0 ? '+' : '';
        const col  = diff >= 0 ? 'var(--green)' : 'var(--red)';
        const name = a.benchmark === 'ibov' ? 'IBOV' : 'CDI';
        bmkLabel = ` <span style="color:${col};font-size:10px">${sign}${(diff*100).toFixed(1)}% a.a. vs ${name}</span>`;
      }
    }

    // nomRetLabel: annualized nominal return (CAGR) shown next to "Fluxo nominal" row
    // Uses the already-computed nominal IRR for consistency
    function nomRetLabel(netCash, latVal, cM) {
      if (irrNominal === null || isCashAsset) return '';
      const col = irrNominal >= 0 ? 'var(--green)' : 'var(--red)';
      const sign = irrNominal >= 0 ? '+' : '';
      return ` <span style="color:${col};font-size:9px">(${sign}${(irrNominal*100).toFixed(1)}% a.a. nominal)</span>`;
    }

    const nameCell = `<td style="${STICKY};left:0;min-width:200px;max-width:200px;font-size:12px;font-weight:500;padding:4px 12px;background:${bg};overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${esc(a.name)}">
      <span style="cursor:pointer;color:var(--accent)" onclick="openInvDetail(${a.id})">${esc(a.name)}</span>
      <div style="display:flex;gap:8px;font-size:10px;margin-top:1px;flex-wrap:wrap">
        ${a.broker ? `<span style="color:var(--text3)">${esc(a.broker)}</span>` : ''}
        <span style="color:${pnlColor}">${pnlLabel}</span>
        <span style="color:${irrColor}" title="${TIR_TOOLTIP}">${irrLabel}</span>${bmkLabel}
      </div>
    </td>`;
    const codeCell  = `<td style="${STICKY};left:200px;min-width:80px;max-width:80px;font-size:11px;color:var(--text3);padding:4px 6px;background:${bg}">${esc(a.code||'—')}</td>`;
    const catCell   = `<td style="${STICKY};left:280px;min-width:90px;max-width:90px;font-size:11px;color:var(--text3);padding:4px 6px;background:${bg}">${cat}</td>`;
    const typeCell  = `<td style="${STICKY};left:370px;min-width:90px;max-width:90px;font-size:11px;color:var(--text3);padding:4px 6px;background:${bg}">${esc(a.inv_type)}</td>`;

    // Value row
    const valueCells = visMonths.map(m => {
      const v = bookValue[m];
      const isCur = m === curM;
      const cellBg = isCur ? 'var(--accent-lt)' : bg;
      if (v === undefined || v === 0) return `<td class="right" style="font-size:12px;padding:4px 8px;background:${cellBg};color:var(--text3)">—</td>`;
      return `<td class="right" style="font-size:12px;padding:4px 8px;background:${cellBg};font-family:'DM Mono',monospace">${fmtBRL(v)}</td>`;
    }).join('');
    const projValueCell = `<td style="min-width:0;max-width:0;padding:0;border:none;overflow:hidden"></td>`;

    // Nominal flow row
    // External capital flow row
    const extFlowCells = visMonths.map(m => {
      const cf = monthlyExtFlow[m] ?? 0;
      const isCur = m === curM;
      const cellBg = isCur ? 'var(--accent-lt)' : bg;
      if (!cf) return `<td class="right" style="font-size:11px;padding:3px 8px;background:${cellBg};color:var(--text3)">—</td>`;
      const cls = cf >= 0 ? 'amt-inc' : 'amt-exp';
      return `<td class="${cls} right" style="font-size:11px;padding:3px 8px;background:${cellBg};font-family:'DM Mono',monospace">${fmtBRL(cf)}</td>`;
    }).join('');

    // Income/cost flow row
    const incFlowCells = visMonths.map(m => {
      const cf = monthlyIncFlow[m] ?? 0;
      const isCur = m === curM;
      const cellBg = isCur ? 'var(--accent-lt)' : bg;
      if (!cf) return `<td class="right" style="font-size:11px;padding:3px 8px;background:${cellBg};color:var(--text3)">—</td>`;
      const cls = cf >= 0 ? 'amt-inc' : 'amt-exp';
      return `<td class="${cls} right" style="font-size:11px;padding:3px 8px;background:${cellBg};font-family:'DM Mono',monospace">${fmtBRL(cf)}</td>`;
    }).join('');

    // Combined nominal flow cells (for total row — kept for IRR label)
    const nomFlowCells = visMonths.map(m => {
      const cf = monthlyNetCash[m] ?? 0;
      const isCur = m === curM;
      const cellBg = isCur ? 'var(--accent-lt)' : bg;
      if (!cf) return `<td class="right" style="font-size:11px;padding:3px 8px;background:${cellBg};color:var(--text3)">—</td>`;
      const cls = cf >= 0 ? 'amt-inc' : 'amt-exp';
      return `<td class="${cls} right" style="font-size:11px;padding:3px 8px;background:${cellBg};font-family:'DM Mono',monospace">${fmtBRL(cf)}</td>`;
    }).join('');
    const projFlowCell = `<td style="min-width:0;max-width:0;padding:0;border:none;overflow:hidden"></td>`;

    // Real flow row (IPCA-adjusted, combined)
    const realFlowCells = visMonths.map(m => {
      const cf = monthlyNetCash[m] ?? 0;
      const isCur = m === curM;
      const cellBg = isCur ? 'var(--accent-lt)' : bg;
      if (!cf) return `<td class="right" style="font-size:11px;padding:3px 8px;background:${cellBg};color:var(--text3)">—</td>`;
      const real = cf * ipcaCumulative(m);
      const cls = real >= 0 ? 'amt-inc' : 'amt-exp';
      return `<td class="${cls} right" style="font-size:11px;padding:3px 8px;background:${cellBg};font-family:'DM Mono',monospace;font-style:italic">${fmtBRL(real)}</td>`;
    }).join('');
    const projRealCell = `<td style="min-width:0;max-width:0;padding:0;border:none;overflow:hidden"></td>`;

    const editCell = `<td style="text-align:center;${STICKY};right:0;min-width:60px;background:${bg}">
      <input type="checkbox" class="pat-sel-chk" data-seltype="inv" data-selid="${a.id}" ${_patSel.inv.ids.has(a.id)?'checked':''} onclick="patSelToggle('inv',${a.id},event)" title="Selecionar para exclusão em lote" style="vertical-align:middle;margin-right:2px;cursor:pointer">
      <button class="btn-icon" onclick="openInvAssetModal(${a.id})" title="Editar">✎</button>
      <button class="btn-icon" onclick="deleteInvAsset(${a.id})" style="color:var(--red)" title="Excluir">✕</button>
    </td>`;
    const editCellSub = `<td style="${STICKY};right:0;min-width:60px;background:${bg}"></td>`;

    const _cgk = 'cat-'+catKey;
    const _cgh = (_pat.collapsed && _pat.collapsed[_cgk]) ? 'display:none;' : '';
    rows += `
      <tr draggable="true" data-group="${_cgk}" style="background:${bg};height:36px;cursor:grab;${_cgh}"
        ondragstart="patDragStart(event,${a.id},'inv')"
        ondragend="patDragEnd(event)"
        ondragover="patDragOver(event,${a.id},'inv')"
        ondragleave="patDragLeave(event)"
        ondrop="patDrop(event,${a.id},'inv')">
        ${nameCell}${codeCell}${catCell}${typeCell}
        ${valueCells}${projValueCell}${editCell}
      </tr>
      <tr data-group="${_cgk}" style="background:${bg};${_cgh}">
        <td style="${STICKY};left:0;font-size:10px;color:var(--accent);padding:2px 12px;background:${bg}" colspan="4">📥 Aporte/Resgate</td>
        ${extFlowCells}${projFlowCell}${editCellSub}
      </tr>
      ${isCashAsset ? '' : `<tr data-group="${_cgk}" style="background:${bg};${_cgh}">
        <td style="${STICKY};left:0;font-size:10px;color:var(--green);padding:2px 12px;background:${bg}" colspan="4">💰 Rendimento/Custo${nomRetLabel(monthlyNetCash, latestVal, curM)}</td>
        ${incFlowCells}${projFlowCell}${editCellSub}
      </tr>`}
      ${showReal ? `<tr data-group="${_cgk}" style="background:${bg};${_cgh}">
        <td style="${STICKY};left:0;font-size:10px;color:var(--text3);padding:2px 12px;background:${bg}" colspan="4">📈 Fluxo real total (IPCA)</td>
        ${realFlowCells}${projRealCell}${editCellSub}
      </tr>` : ''}`;
    }); // end catAssets.forEach

    // Category subtotal row
    // Skip subtotal for cash categories
    if (!['caixa','valor_em_caixa'].includes(catKey)) {
      rows += buildCatSubtotalRow(catKey, byCategoryAll[catKey] || catAssets, months, txByAsset, curM, STICKY, COL_W, stripe, ipcaCumulative, showReal, nextM, visMonths);
    }
  }); // end catKeys.forEach

  return rows;
}

function patToggleCatCollapse(cgk) {
  if (!_pat.collapsed) _pat.collapsed = {};
  _pat.collapsed[cgk] = !_pat.collapsed[cgk];
  // Toggle visibility of all rows with this data-group
  document.querySelectorAll(`tr[data-group="${cgk}"]`).forEach(row => {
    row.style.display = _pat.collapsed[cgk] ? 'none' : '';
  });
  // Update the toggle icon in the header row
  const headerTd = document.querySelector(`tr[onclick*="${cgk}"] td`);
  if (headerTd) {
    const iconSpan = headerTd.querySelector('span:first-child');
    if (iconSpan) iconSpan.textContent = _pat.collapsed[cgk] ? '▶' : '▼';
  }
}

// ── Total investimentos por mês (returns {totals, totalsExCash, netCashByMonth}) ──
function calcInvTotalByMonth(months) {
  const totals          = {};
  // Mesmo total, mas sem os ativos de categoria "caixa"/"valor_em_caixa" — usado
  // só para TIR/Ganho-Perda, já que caixa não tem aporte/resgate registrado e
  // qualquer valor ali apareceria como "ganho" puro se entrasse nessa conta.
  const totalsExCash    = {};
  const netCashByMonth  = {}; // all cash flows combined (for IRR)
  const extFlowByMonth  = {}; // external capital only (compra/aporte/venda/amortizacao)
  const incFlowByMonth  = {}; // income/cost only (dividendo/juros/taxa etc.)
  months.forEach(m => { totals[m] = 0; totalsExCash[m] = 0; });

  const txByAsset = {};
  _inv.txAll.forEach(t => {
    const tm = t.month.slice(0,7);
    if (!txByAsset[t.asset_id]) txByAsset[t.asset_id] = {};
    if (!txByAsset[t.asset_id][tm]) txByAsset[t.asset_id][tm] = [];
    txByAsset[t.asset_id][tm].push(t);
  });

  _inv.assets.forEach(a => {
    const txs = txByAsset[a.id] || {};
    const txMonths = [...new Set(Object.keys(txs))].sort();
    if (!txMonths.length) return;

    // Track asset value (from atualizacao only) and cash flows separately
    const valByM    = {}; // month -> asset value (from atualizacao)
    const cashDeltaByM = {}; // month -> net external cash delta

    txMonths.forEach(m => {
      let cashDelta = 0;
      (txs[m] || []).forEach(t => {
        if (t.tx_type in INV_TX_EXTERNAL) {
          const sign = INV_TX_EXTERNAL[t.tx_type].sign;
          cashDelta += sign < 0 ? t.total_value : -t.total_value;
          netCashByMonth[m] = (netCashByMonth[m] || 0) + sign * t.total_value;
          extFlowByMonth[m] = (extFlowByMonth[m] || 0) + sign * t.total_value;
        } else if (t.tx_type in INV_TX_INCOME) {
          const sign = INV_TX_INCOME[t.tx_type].sign;
          netCashByMonth[m] = (netCashByMonth[m] || 0) + sign * t.total_value;
          incFlowByMonth[m] = (incFlowByMonth[m] || 0) + sign * t.total_value;
        } else if (t.tx_type in INV_TX_VALUATION) {
          valByM[m] = t.total_value; // actual asset value — the only thing that goes into totals
        }
      });
      if (cashDelta !== 0) cashDeltaByM[m] = (cashDeltaByM[m] || 0) + cashDelta;
    });

    // totals: use only real valuations (atualizacao), carry forward the last known value
    // Never use cashDelta as a proxy for asset value — that distorts the portfolio total
    const valMonthsSorted = Object.keys(valByM).sort();
    if (!valMonthsSorted.length) return; // no valuations = don't include in portfolio total

    let lastVal = 0;
    const isCash = _isCashAsset(a);
    months
      .filter(m => m >= valMonthsSorted[0] && m <= (a.closed_month || months[months.length-1]))
      .forEach(m => {
        if (valByM[m] !== undefined) lastVal = valByM[m];
        totals[m] += lastVal;
        if (!isCash) totalsExCash[m] += lastVal;
      });
  });
  return { totals, totalsExCash, netCashByMonth, extFlowByMonth, incFlowByMonth };
}

// ══ APOSENTADORIA ══════════════════════════════════════════════════════════

const APOS_STORAGE_KEY = 'cruzeiro_apos_config';

let _aposView = 'table';
let _aposChart1 = null, _aposChart2 = null;
let _aposFocusData = null;

async function aposSaveConfig() {
  // Salva o valor exibido no campo (texto formatado) — aposParseInput sabe interpretar.
  // Usa o mesmo arquivo de configurações já usado por Relatórios/Evolução
  // (por usuário, em disco) em vez de localStorage — que não é separado
  // por usuário e não tem a mesma garantia de persistência entre sessões.
  const aposFields = {
    apos_goalType:   document.querySelector('input[name="apos-goal-type"]:checked')?.value || 'patrimonio',
    apos_goalValue:  G('apos-goal-value')?.value || '',
    apos_ageNow:     G('apos-age-now')?.value || '',
    apos_ageRet:     G('apos-age-ret')?.value || '',
    apos_patAtual:   G('apos-patrimonio-atual')?.value || '',
    apos_rateReal:   G('apos-rate-real')?.value || '',
    apos_rateInfl:   G('apos-rate-infl')?.value || '',
    // aposTglMode() dispara este save (via aposCalc()) e o de apos2SaveConfig()
    // em paralelo, sem aguardar um pelo outro — ambos fazem leitura+escrita
    // do mesmo arquivo, e o que escrever por último "vence". Sem incluir
    // apos_mode aqui também, essa corrida podia fazer o modo salvo reverter
    // sozinho pro valor antigo (ex: usuário troca pra "Rumo à Aposentadoria",
    // mas na próxima vez que abre a aba volta pra "Pós-Aposentadoria") — os
    // dois salvamentos concorrentes agora sempre escrevem o mesmo _aposMode
    // atual, então não importa qual "vence" a corrida.
    apos_mode:       _aposMode,
  };
  try {
    const cfg = await ff.overviewConfigGet().catch(() => null) || {};
    await ff.overviewConfigSave({ ...cfg, ...aposFields });
  } catch(e) { console.error('aposSaveConfig:', e); }
}

async function aposResetConfig() {
  try {
    const cfg = await ff.overviewConfigGet().catch(() => null) || {};
    ['apos_goalType','apos_goalValue','apos_ageNow','apos_ageRet','apos_patAtual','apos_rateReal','apos_rateInfl'].forEach(k => delete cfg[k]);
    await ff.overviewConfigSave(cfg);
  } catch(e) {}
  // Limpa todos os campos
  ['apos-goal-value','apos-patrimonio-atual','apos-age-now','apos-age-ret','apos-rate-real'].forEach(id => {
    const el = G(id); if (el) el.value = '';
  });
  const r = document.querySelector('input[name="apos-goal-type"][value="renda"]');
  if (r) r.checked = true;
  if (G('apos-kpis')) G('apos-kpis').innerHTML = '';
  if (G('apos-table-body')) G('apos-table-body').innerHTML = '';
}

async function aposLoadConfig() {
  try {
    let cfg = await ff.overviewConfigGet().catch(() => null) || {};

    // Migração única: se ainda não há dados no novo formato (arquivo por
    // usuário), mas existem dados do mecanismo antigo (localStorage, que
    // não persistia de forma confiável), migra pra não perder o que já
    // tinha sido digitado.
    if (!cfg.apos_ageNow && !cfg.apos_patAtual) {
      try {
        const legacyRaw = localStorage.getItem(APOS_STORAGE_KEY);
        if (legacyRaw) {
          const legacy = JSON.parse(legacyRaw);
          const migrated = {
            apos_goalType:  legacy.goalType  || '',
            apos_goalValue: legacy.goalValue || '',
            apos_ageNow:    legacy.ageNow    || '',
            apos_ageRet:    legacy.ageRet    || '',
            apos_patAtual:  legacy.patAtual  || '',
            apos_rateReal:  legacy.rateReal  || '',
            apos_rateInfl:  legacy.rateInfl  || '',
          };
          cfg = { ...cfg, ...migrated };
          await ff.overviewConfigSave(cfg).catch(() => {});
          localStorage.removeItem(APOS_STORAGE_KEY);
        }
      } catch(e) { console.error('Migração apos config:', e); }
    }

    if (!cfg) return;

    // Sanity-check: se patAtual parseado for suspeito (< 100), descarta SÓ
    // esse campo (ele é sobrescrito por um valor ao vivo de qualquer jeito,
    // via aposPullPatrimonio) — sem abortar a restauração dos outros
    // campos (tipo de meta, valor da meta, idades, taxa), que é o que
    // estava acontecendo antes e deixava a tela com dados desencontrados.
    if (cfg.apos_patAtual) {
      const testPat = parseFloat(String(cfg.apos_patAtual).replace(/\./g,'').replace(',','.'));
      if (!isNaN(testPat) && testPat < 100) {
        console.warn('[Aposentadoria] patAtual suspeito (' + cfg.apos_patAtual + '), descartando só esse campo.');
        delete cfg.apos_patAtual;
        await ff.overviewConfigSave(cfg).catch(() => {});
      }
    }

    if (cfg.apos_goalType) {
      document.querySelectorAll('input[name="apos-goal-type"]').forEach(el => el.checked = false);
      const r = document.querySelector(`input[name="apos-goal-type"][value="${cfg.apos_goalType}"]`);
      if (r) r.checked = true;
    }
    if (cfg.apos_goalValue)  { const inp = G('apos-goal-value');        if (inp) (inp.setValue ? inp.setValue(parseBRLStr(cfg.apos_goalValue)) : (inp.value = cfg.apos_goalValue)); }
    if (cfg.apos_ageNow)     G('apos-age-now').value  = cfg.apos_ageNow;
    if (cfg.apos_ageRet)     G('apos-age-ret').value  = cfg.apos_ageRet;
    if (cfg.apos_patAtual)   { const inp = G('apos-patrimonio-atual');   if (inp) (inp.setValue ? inp.setValue(parseBRLStr(cfg.apos_patAtual)) : (inp.value = cfg.apos_patAtual)); }
    if (cfg.apos_rateReal)   G('apos-rate-real').value = cfg.apos_rateReal;
    if (cfg.apos_rateInfl)   G('apos-rate-infl').value = cfg.apos_rateInfl;
  } catch(e) {}
}

function focusDate() {
  // Focus is published weekly (Fridays). Go back up to 14 days to find the last release.
  const d = new Date();
  d.setDate(d.getDate() - 3); // start 3 days ago
  return d.toISOString().slice(0,10);
}

// Fetch Focus BCB — tries multiple endpoints and date ranges
async function fetchFocusWithRetry(indicator) {
  const enc = encodeURIComponent;

  // Strategy 1: ExpectativasMercadoAnuais with date filter, going back up to 21 days
  const base = 'https://olinda.bcb.gov.br/olinda/servico/Expectativas/versao/v1/odata/';
  for (let daysBack = 2; daysBack <= 21; daysBack++) {
    const d = new Date();
    d.setDate(d.getDate() - daysBack);
    const date = d.toISOString().slice(0,10);
    try {
      const url = `${base}ExpectativaMercadoAnuais(Indicador=@I,Data=@D)?@I=${enc("'"+indicator+"'")}&@D=${enc("'"+date+"'")}&$top=1&$orderby=Data%20desc&$format=json&$select=Indicador,Data,Mediana`;
      const r = await fetch(url);
      if (!r.ok) continue;
      const data = await r.json();
      if (data?.value?.length > 0) return data;
    } catch(e) { continue; }
  }

  // Strategy 2: No date filter — just get the most recent entry
  try {
    const url = `${base}ExpectativaMercadoAnuais?$filter=Indicador%20eq%20'${enc(indicator)}'&$top=1&$orderby=Data%20desc&$format=json&$select=Indicador,Data,Mediana`;
    const r = await fetch(url);
    if (r.ok) {
      const data = await r.json();
      if (data?.value?.length > 0) return data;
    }
  } catch(e) {}

  return null;
}

async function aposUpdateFocus() {
  const hint = G('apos-focus-hint');
  if (hint) hint.textContent = '📡 Buscando Boletim Focus (BCB)…';
  try {
    // Try multiple dates going back to find the most recent Focus release
    const [d1, d2] = await Promise.all([
      fetchFocusWithRetry('IPCA'),
      fetchFocusWithRetry('Selic'),
    ]);
    const ipca  = parseFloat(d1?.value?.[0]?.Mediana);
    const selic = parseFloat(d2?.value?.[0]?.Mediana);
    if (!isNaN(ipca) && !isNaN(selic)) {
      _aposFocusData = { ipca, selic };
      const realRate = ((1 + selic/100) / (1 + ipca/100) - 1) * 100;
      if (hint) hint.textContent = `Focus BCB: Selic ${selic.toFixed(1)}% · IPCA ${ipca.toFixed(1)}% → retorno real estimado: ${realRate.toFixed(1)}% a.a.`;
      if (!G('apos-rate-real')?.value) G('apos-rate-real').value = Math.max(2, realRate - 2).toFixed(1);
      if (!G('apos-rate-infl')?.value) G('apos-rate-infl').value = ipca.toFixed(1);
      aposCalc();
    } else {
      if (hint) hint.textContent = 'Focus: sem dados disponíveis para a data solicitada';
    }
  } catch(e) {
    if (hint) hint.textContent = `Focus: erro — ${e.message}`;
  }
}

async function aposPullPatrimonio() {
  try {
    // Use the grand total from patrimônio tab if available (most accurate)
    let total = 0;
    if (window._patGrandTotal && typeof window._patGrandTotal.value === 'number' && window._patGrandTotal.value > 0) {
      total = window._patGrandTotal.value;
    } else {
      // Fallback: sum account balances. accounts (global) só tem metadados
      // (nome, tipo, banco...) — NÃO tem saldo; saldo por conta vive em
      // _pat.accountBalances[].history (mesmo dado que a aba Patrimônio usa
      // pro card "Contas"). accounts.reduce(...a.balance...) sempre dava 0.
      const now2 = new Date();
      const curM2 = `${now2.getFullYear()}-${String(now2.getMonth()+1).padStart(2,'0')}`;
      total = (_pat?.accountBalances || []).reduce((s, a) => {
        const up = (a.history || []).filter(h => h.month <= curM2);
        return s + (up.length ? up[up.length - 1].balance : 0);
      }, 0);
    }
    const inp = G('apos-patrimonio-atual');
    if (inp) {
      if (inp.setValue) inp.setValue(Math.max(0, total));
      else inp.value = Math.max(0, total).toLocaleString('pt-BR',{minimumFractionDigits:2});
      inp.dataset.raw = Math.max(0, total).toString();
      aposCalc();
    }
  } catch(e) { toast('Erro ao buscar patrimônio: ' + e.message); }
}

// Converte uma string em formato brasileiro ("R$ 1.234,56" ou "1234,56" ou
// "1234") num número — usado ao restaurar valores salvos para dentro de
// campos com máscara de moeda (setupCurrencyInput).
function parseBRLStr(str) {
  let v = String(str || '').replace(/R\$[ \s]*/g, '').trim();
  if (v.includes(',')) v = v.replace(/\./g, '').replace(',', '.');
  const n = parseFloat(v);
  return isNaN(n) ? 0 : n;
}

function aposParseInput(id) {
  const el = G(id);
  if (!el) return 0;
  let v = el.value
    .replace(/R\$[ \s]*/g, '')
    .trim();
  // Brazilian format: comma = decimal separator, dots = thousand separators.
  // Detect by presence of comma anywhere.
  if (v.includes(',')) {
    v = v.replace(/\./g, '').replace(',', '.');
  }
  // No comma: dots are thousand separators if there are multiple, leave single dot as decimal.
  const parsed = parseFloat(v);
  return isNaN(parsed) ? 0 : parsed;
}
async function aposGetRealizedSavings() {
  const months = {};
  try {
    // report:monthly agora retorna uma linha por (mês, categoria) — soma o
    // saldo líquido de todas as categorias de cada mês. O total líquido é
    // o mesmo independente de como cada categoria é classificada, então
    // isso não é afetado pela mudança feita no Resumo/Comparação mensal.
    const rows = await ff.reportMonthly({
      fromDate: '2000-01-01',
      toDate: new Date().toISOString().slice(0,10),
      excludeTransfers: true,
    });
    (rows || []).forEach(row => {
      if (row.month) months[row.month] = (months[row.month] || 0) + (row.income || 0) - (row.expenses || 0);
    });
  } catch(e) { console.error('aposGetRealizedSavings:', e); }
  return months;
}

// ── Meta automática de Aposentadoria ──
// Busca o patrimônio total mais recente — usa o que já estiver carregado
// (de uma visita à Patrimônio nesta sessão); se não houver nada, força um
// refresh pra não depender do usuário ter visitado aquela aba antes.
async function getCurrentPatrimonioTotalLive() {
  try {
    if (!window._patTotalByMonth || !Object.keys(window._patTotalByMonth).length) {
      await refreshPatrimonio();
    }
    const months = Object.keys(window._patTotalByMonth || {}).sort();
    if (!months.length) return 0;
    return window._patTotalByMonth[months[months.length-1]] || 0;
  } catch(e) { console.error('getCurrentPatrimonioTotalLive:', e); return 0; }
}
// Média móvel de 12 meses do lucro (receitas - despesas) — reaproveita
// DIRETAMENTE window._evMA12LucroByMonth, o mesmo valor já calculado e
// usado pela Aposentadoria/Evolução (computeEvMA12LucroData), em vez de
// recalcular do zero. Recalcular por conta própria arriscava divergir da
// metodologia de lá (exclusão de categorias e correção pelo IPCA
// aplicadas de forma diferente), o que já causou resultados errados.
async function getCurrentMA12LucroLive() {
  try {
    if (!window._evMA12LucroByMonth || !Object.keys(window._evMA12LucroByMonth).length) {
      await computeEvMA12LucroData();
    }
    const months = Object.keys(window._evMA12LucroByMonth || {}).sort();
    if (!months.length) return 0;
    return window._evMA12LucroByMonth[months[months.length-1]] || 0;
  } catch(e) { console.error('getCurrentMA12LucroLive:', e); return 0; }
}
// Cria (na primeira vez que a Aposentadoria for preenchida) ou atualiza a
// meta "Aposentadoria" com os dados mais recentes do cálculo. Dois
// acompanhamentos: longo prazo (patrimônio-alvo) e curto prazo (poupança
// mensal necessária = aporte externo + rendimento do patrimônio).
async function syncRetirementGoal({ metaPatrimonio, retYear, needPMT, patAtual, rateReal }) {
  const yieldMonthlyCur = patAtual * rateReal / 12;
  const monthlyTarget = needPMT + yieldMonthlyCur;
  const deadline = `${retYear}-12-31`;

  const allGoals = await ff.goalList().catch(() => []);
  const existing = allGoals.find(g => g.type === 'retirement');
  const isFirstTime = !existing;
  await ff.goalSave({
    id: existing?.id || null,
    name: existing?.name || 'Aposentadoria',
    type: 'retirement',
    target_amount: metaPatrimonio,
    monthly_amount: monthlyTarget,
    deadline,
    icon: existing?.icon || '🏖️',
    color: existing?.color || '#43a047',
  });
  if (isFirstTime) {
    toast('🎯 Meta "Aposentadoria" criada automaticamente — veja na aba Metas');
  }
}

async function aposCalc() {
  aposSaveConfig();

  const goalType = document.querySelector('input[name="apos-goal-type"]:checked')?.value || 'patrimonio';
  const goalRaw  = aposParseInput('apos-goal-value');
  const ageNow   = parseInt(G('apos-age-now')?.value  || '0');
  const ageRet   = parseInt(G('apos-age-ret')?.value  || '0');
  const patAtual = aposParseInput('apos-patrimonio-atual');
  const rateReal = (parseFloat(G('apos-rate-real')?.value) || 4) / 100;

  // Update labels
  const lbl = G('apos-goal-label');
  if (lbl) lbl.textContent = goalType === 'patrimonio' ? '💰 Patrimônio desejado (R$)' : '💸 Renda mensal desejada (R$)';
  const ghint = G('apos-goal-hint');
  if (ghint) ghint.textContent = goalType === 'patrimonio'
    ? 'Patrimônio líquido total a acumular (em R$ de hoje)'
    : 'Renda mensal sustentável em R$ de hoje (regra dos juros reais)';

  if (!goalRaw || !ageNow || !ageRet || ageRet <= ageNow) {
    const missing = [];
    if (!goalRaw) missing.push('meta');
    if (!ageNow)  missing.push('idade atual');
    if (!ageRet || ageRet <= ageNow) missing.push('idade na aposentadoria (maior que atual)');
    G('apos-kpis').innerHTML = `<div style="color:var(--text3);font-size:13px;padding:12px">Preencha: ${missing.join(', ')}.</div>`;
    if (G('apos-table-body')) G('apos-table-body').innerHTML = '';
    return;
  }

  // ── Meta em patrimônio ──────────────────────────────────────────────
  const metaPatrimonio = goalType === 'patrimonio'
    ? goalRaw
    : (goalRaw * 12) / Math.max(0.01, rateReal);

  const curYear    = new Date().getFullYear();
  const yearsTotal = ageRet - ageNow;
  const retYear    = curYear + yearsTotal;

  // ── Patrimônio real por ano (de _patTotalByMonth) ───────────────────
  // Exclude years that only have bank account data (no investments or fixed assets)
  // Those years show in _patTotalByMonth but inv+asset totals are zero
  const patByMonth = window._patTotalByMonth || {};
  const invByMonth  = window._invTotalByMonth  || {};   // populated by refreshInvTable
  const assetByMonth = window._assetTotalByMonth || {};  // populated by refreshInvTable

  const patByYear = {};
  Object.entries(patByMonth).forEach(([m, v]) => {
    const y = parseInt(m.slice(0,4));
    // Only include months where there's some investment or fixed asset data
    const hasNonBank = (invByMonth[m] || 0) + (assetByMonth[m] || 0) > 0;
    if (!hasNonBank) return;
    // Keep December if available, else last available month
    if (!patByYear[y] || m.slice(5,7) === '12') patByYear[y] = { val: v, month: m };
  });

  // ── Poupança realizada por ano (de _evMA12LucroByMonth) ─────────────
  // Read the IPCA-corrected MA12 lucro at December of each year
  const evMA12 = window._evMA12LucroByMonth || {};
  const savingsByYear = {};
  Object.entries(evMA12).forEach(([m, v]) => {
    const y = parseInt(m.slice(0,4));
    if (!savingsByYear[y] || m.slice(5,7) === '12') savingsByYear[y] = v;
  });

  // ── Aporte externo fixo (x) ──────────────────────────────────────────
  // Fórmula: meta = patAtual*(1+r)^n + x*12*((1+r)^n - 1)/r
  // → x_mensal = (meta - patAtual*(1+r)^n) / (12 * ((1+r)^n - 1) / r)
  // x é constante todo mês. O rendimento do patrimônio cresce e cobre cada vez mais.
  // A poupança total (rendimento + x) é crescente ao longo do tempo.
  const fatorN      = Math.pow(1 + rateReal, yearsTotal);
  const pvGrown     = patAtual * fatorN;
  let xAnual = 0;
  if (yearsTotal <= 0) {
    xAnual = 0; // já é (ou passou) o ano de aposentadoria
  } else if (pvGrown >= metaPatrimonio) {
    xAnual = 0; // patrimônio atual já alcança a meta
  } else if (Math.abs(rateReal) < 1e-9) {
    // Limite r→0: sem juros, aporte linear puro
    xAnual = (metaPatrimonio - patAtual) / yearsTotal;
  } else {
    xAnual = (metaPatrimonio - pvGrown) / ((fatorN - 1) / rateReal);
  }
  const needPMT     = xAnual / 12; // aporte externo mensal fixo
  const annuityPerYear = xAnual;   // aporte externo anual fixo

  // Mantém a meta "Aposentadoria" sincronizada com este cálculo — criada
  // automaticamente na primeira vez que os campos forem preenchidos.
  syncRetirementGoal({ metaPatrimonio, retYear, needPMT, patAtual, rateReal }).catch(e => console.error('syncRetirementGoal:', e));

  // ── Build table rows ─────────────────────────────────────────────────
  const patHistYears = Object.keys(patByYear).map(Number).sort();
  const firstPatYear = patHistYears.length ? patHistYears[0] : curYear;

  const rows = [];
  let projPat = patAtual;

  for (let year = firstPatYear; year <= retYear; year++) {
    const age        = ageNow + (year - curYear);
    const isPast     = year < curYear;
    const isCur      = year === curYear;
    const isFuture   = year > curYear;
    const isRetired  = age > ageRet; // ano de aposentadoria ainda acumula PMT normalmente
    const isRetYear  = age === ageRet; // apenas para exibição (emoji, highlight)

    // Patrimônio real: only from patByYear (excludes bank-only years)
    const patRealVal  = patByYear[year]?.val ?? null;
    const patReal     = (isPast && patRealVal != null) ? patRealVal
                      : isCur ? patAtual : null;

    // Poupança realizada: December MA12 IPCA-corrected from Evolução (apenas anos passados fechados)
    const savingReal  = isPast ? (savingsByYear[year] ?? null) : null;

    // Aporte externo fixo (anos futuros pré-aposentadoria, incluindo ano corrente)
    const savingNeeded = (!isRetired && !isPast) ? needPMT : null;

    // Rendimento mensal do patrimônio = saldo_início_ano × rateReal / 12
    const yieldPatMonthly = (!isRetired && !isPast && projPat > 0)
      ? projPat * rateReal / 12 : null;

    // Poupança por outros meios = aporte externo fixo (needPMT)
    // já é constante — exibimos separado do rendimento
    const savingExternal = savingNeeded; // fixo, não depende do rendimento

    // projPat já é o saldo acumulado até o início deste ano.
    // Para todos os anos (incluindo aposentadoria) mostramos projPat diretamente.
    const projPatDisplay = projPat;

    const displayPat = patReal ?? (isFuture || isCur ? projPatDisplay : null);
    const pctMeta = displayPat != null ? displayPat / metaPatrimonio : null;

    rows.push({
      year, age, isPast, isCur, isFuture, isRetired, isRetYear,
      patReal,
      projPat: (isFuture || isCur) ? projPatDisplay : null,
      savingReal, savingNeeded, yieldPat: yieldPatMonthly, savingExternal, pctMeta,
    });

    // Avança projPat para o próximo ano (juros anuais + aporte externo fixo)
    // Anos passados: não alteramos — projeção parte sempre de patAtual no ano corrente.
    if (!isPast && !isRetired) {
      projPat = projPat * (1 + rateReal) + annuityPerYear;
    } else if (isRetired) {
      projPat = projPat * (1 + rateReal) - metaPatrimonio * rateReal;
    }
  }

  renderAposKPIs({ needPMT, metaPatrimonio, goalType, goalRaw, rateReal, yearsTotal });
  if (_aposView === 'table') renderAposTable(rows);
  else renderAposCharts(rows, metaPatrimonio);
}


function renderAposKPIs({ needPMT, metaPatrimonio, goalType, goalRaw, rateReal, yearsTotal }) {
  const reached = needPMT === 0;
  const kpis = [
    { icon:'🎯', label: goalType==='patrimonio' ? 'Meta de patrimônio' : 'Patrimônio necessário',
      value: fmtBRL(metaPatrimonio), color:'var(--green)',
      sub: goalType==='renda' ? `para sustentar renda de ${fmtBRL(goalRaw)}/mês` : '' },
    { icon:'📅', label:'Anos até a aposentadoria', value:`${yearsTotal} anos`, color:'#0891b2', sub:'' },
    { icon:'💵', label:'Poupança total necessária/mês',
      value: reached ? '🎉 Meta já alcançável!' : fmtBRL(needPMT)+'/mês',
      sub: reached ? 'Patrimônio atual já cobre a meta' : `fixo todo mês · a poupança total cresce com o rendimento`,
      color: reached ? '#43a047' : '#d97706', accent: !reached && needPMT > 0 },
    { icon:'📈', label:'Retorno real esperado',
      value: `${(rateReal*100).toFixed(1)}% a.a.`, color:'#7c3aed',
      sub: 'parte da poupança virá do rendimento do próprio patrimônio' },
  ];
  G('apos-kpis').innerHTML = kpis.map(k => `
    <div style="background:var(--bg2);border:1px solid var(--border);border-left:4px solid ${k.color};border-radius:12px;padding:14px 16px;box-shadow:0 1px 3px rgba(20,30,50,.04)">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">
        <span style="font-size:18px">${k.icon}</span>
        <span style="font-size:11px;color:var(--text3);font-weight:600;text-transform:uppercase;letter-spacing:.02em">${k.label}</span>
      </div>
      <div style="font-size:17px;font-weight:800;color:${k.color}">${k.value}</div>
      ${k.sub?`<div style="font-size:11px;color:var(--text3);margin-top:3px">${k.sub}</div>`:''}
    </div>`).join('');
}

function renderAposTable(rows) {
  const tbody = G('apos-table-body');
  if (!tbody) return;

  const thead = G('apos-table')?.querySelector('thead tr');
  if (thead) thead.innerHTML = `
    <th>Ano</th><th>Idade</th>
    <th class="right">Patrimônio<br><span style="font-size:10px;font-weight:400;color:var(--text3)">real · projetado</span></th>
    <th class="right">Poupança realizada/mês<br><span style="font-size:10px;font-weight:400;color:var(--text3)">Média 12m Lucro (dez) — anos passados</span></th>
    <th class="right">Rendimento do patrimônio/mês<br><span style="font-size:10px;font-weight:400;color:var(--text3)">retorno real sobre saldo projetado</span></th>
    <th class="right">Aporte externo/mês<br><span style="font-size:10px;font-weight:400;color:var(--text3)">fixo · independe do rendimento do patrimônio</span></th>
    <th class="right">% da meta</th>`;

  tbody.innerHTML = rows.map(r => {
    let rowStyle = r.isCur ? 'background:var(--bg3);font-weight:700'
                 : r.isPast ? 'opacity:0.75' : '';
    if (r.isRetired || r.isRetYear) rowStyle = 'background:rgba(37,99,235,0.06)';

    const pct      = r.pctMeta;
    const pctColor = pct>=1?'color:var(--green)' : pct>=0.75?'color:#66bb6a' : pct>=0.5?'color:#f59e0b':'color:var(--red)';
    const barW     = Math.min(80, Math.round(Math.min(pct,1)*80));
    const barClr   = pct>=1?'var(--green)':pct>=0.5?'var(--accent)':'var(--red)';
    const bar      = `<div style="display:inline-block;width:${barW}px;height:4px;background:${barClr};border-radius:2px;vertical-align:middle;margin-left:4px"></div>`;

    const yearLabel = `${r.year}${r.isRetYear?' 🏖️':r.isCur?' ◀':''}`;
    const mono      = `font-family:'DM Mono',monospace`;

    // Patrimônio
    let patCell;
    if (r.patReal != null) {
      patCell = fmtBRL(r.patReal);
    } else if (r.projPat != null) {
      patCell = `<span style="color:var(--accent)">${fmtBRL(r.projPat)}</span>`;
    } else {
      patCell = '—';
    }

    // Poupança realizada (passado + corrente)
    const savRealCell = r.savingReal != null
      ? `<span class="${r.savingReal>=0?'amt-inc':'amt-exp'}">${fmtBRL(r.savingReal)}</span>` : '—';

    // Rendimento mensal do patrimônio (futuro pré-aposentadoria)
    const yieldCell = r.yieldPat != null
      ? `<span style="color:var(--green)">${fmtBRL(r.yieldPat)}</span>` : '—';

    // Poupança por outros meios (futuro pré-aposentadoria)
    const extCell = r.savingExternal != null
      ? `<span style="color:var(--accent);font-weight:600">${fmtBRL(r.savingExternal)}</span>` : '—';

    return `<tr style="${rowStyle}">
      <td style="font-size:12px;padding:5px 8px">${yearLabel}</td>
      <td style="font-size:12px;padding:5px 8px;text-align:center">${r.age}</td>
      <td class="right" style="font-size:12px;padding:5px 8px;${mono}">${patCell}</td>
      <td class="right" style="font-size:12px;padding:5px 8px;${mono}">${savRealCell}</td>
      <td class="right" style="font-size:12px;padding:5px 8px;${mono}">${yieldCell}</td>
      <td class="right" style="font-size:12px;padding:5px 8px;${mono}">${extCell}</td>
      <td class="right" style="font-size:12px;padding:5px 8px;${pctColor};font-weight:600">${(pct*100).toFixed(0)}%${bar}</td>
    </tr>`;
  }).join('');
}

function renderAposCharts(rows, metaPatrimonio) {
  // Chart 1 (patrimônio vs meta): start only from first year with real patrimônio data
  const firstPatIdx = rows.findIndex(r => r.patReal != null);
  const patRows  = firstPatIdx >= 0 ? rows.slice(firstPatIdx) : rows;

  const labels    = patRows.map(r => r.year.toString());
  const patReal   = patRows.map(r => r.patReal  != null ? Math.round(r.patReal)  : null);
  const patProj   = patRows.map(r => r.projPat  != null ? Math.round(r.projPat)  : null);
  const metaLine  = patRows.map(() => Math.round(metaPatrimonio));
  const yieldData = patRows.map(r => r.yieldPat       != null ? Math.round(r.yieldPat)       : null);
  const extData   = patRows.map(r => r.savingExternal  != null ? Math.round(r.savingExternal)  : null);
  const savReal   = patRows.map(r => r.savingReal      != null ? Math.round(r.savingReal)      : null);

  if (_aposChart1) { try{_aposChart1.destroy();}catch(e){} _aposChart1=null; }
  if (_aposChart2) { try{_aposChart2.destroy();}catch(e){} _aposChart2=null; }

  const fmtY  = v => v==null?'':('R$'+(Math.abs(v)>=1e6?(v/1e6).toFixed(1)+'M':Math.abs(v)>=1e3?(v/1e3).toFixed(0)+'k':v));
  const GREEN = '#43a047', RED = '#ef5350', BLUE = '#3b82f6', AMBER = '#f59e0b';

  const ctx1 = G('apos-chart')?.getContext('2d');
  if (ctx1) _aposChart1 = new Chart(ctx1, {
    type: 'line',
    data: { labels, datasets: [
      { label:'Patrimônio real', data:patReal, borderColor:GREEN, backgroundColor:evChartGradient(ctx1,GREEN,380),
        fill:true, tension:.4, borderWidth:2.5, pointRadius:0, pointHoverRadius:6, pointHoverBackgroundColor:GREEN, pointHoverBorderColor:'#fff', pointHoverBorderWidth:2, spanGaps:false },
      { label:'Patrimônio projetado', data:patProj, borderColor:GREEN, borderDash:[6,4],
        backgroundColor:'rgba(67,160,71,.05)', fill:true, tension:.4, borderWidth:2, pointRadius:0, pointHoverRadius:5, pointHoverBackgroundColor:GREEN, pointHoverBorderColor:'#fff', pointHoverBorderWidth:2, spanGaps:false },
      { label:'Meta', data:metaLine, borderColor:RED, borderDash:[8,4],
        borderWidth:2, pointRadius:0, pointHoverRadius:0, fill:false },
    ]},
    options: { responsive:true, maintainAspectRatio:false,
      interaction:{ mode:'index', intersect:false },
      plugins:{
        legend:{ position:'top', align:'end', labels:{boxWidth:10,boxHeight:10,usePointStyle:true,pointStyle:'circle',font:{size:11,weight:'600'}} },
        title:{ display:true, text:'Patrimônio real e projetado vs meta', font:{size:13,weight:'700'}, color:'var(--green)', padding:{bottom:12} },
        tooltip:{ enabled:false, external:(context) => dashTooltip(context, {
          getTitle: (dp) => labels[dp[0].dataIndex],
          getRows:  (dp) => dp.filter(d=>d.parsed.y!=null).map(d => ({ color:d.dataset.borderColor, label:d.dataset.label, value:fmtBRL(d.parsed.y) })),
        }) },
      },
      scales:{ x:{ grid:{display:false}, ticks:{font:{size:10}} }, y:{ grid:{color:themeGridColor()}, ticks:{ font:{size:10}, callback:fmtY } } },
      animation:{ duration:600 },
    }
  });

  const ctx2 = G('apos-chart2')?.getContext('2d');
  if (ctx2) _aposChart2 = new Chart(ctx2, {
    type: 'bar',
    data: { labels, datasets: [
      { label:'Rendimento do patrimônio/mês', data:yieldData, backgroundColor:GREEN+'b3',
        borderColor:GREEN, borderWidth:1, borderRadius:5, maxBarThickness:28, stack:'future' },
      { label:'Poupança por outros meios/mês', data:extData, backgroundColor:BLUE+'b3',
        borderColor:BLUE, borderWidth:1, borderRadius:5, maxBarThickness:28, stack:'future' },
      { label:'Poupança realizada/mês (Média 12m)', data:savReal, backgroundColor:AMBER+'b3',
        borderColor:AMBER, borderWidth:1, borderRadius:5, maxBarThickness:28, stack:'future' },
    ]},
    options: { responsive:true, maintainAspectRatio:false,
      interaction:{ mode:'index', intersect:false },
      plugins:{
        legend:{ position:'top', align:'end', labels:{boxWidth:10,boxHeight:10,usePointStyle:true,pointStyle:'circle',font:{size:11,weight:'600'}} },
        title:{ display:true, text:'Poupança necessária (futura) e realizada (histórica)', font:{size:13,weight:'700'}, color:'var(--green)', padding:{bottom:12} },
        tooltip:{ enabled:false, external:(context) => dashTooltip(context, {
          getTitle: (dp) => labels[dp[0].dataIndex],
          getRows:  (dp) => dp.filter(d=>d.parsed.y!=null).map(d => ({ color:d.dataset.borderColor, label:d.dataset.label, value:fmtBRL(d.parsed.y) })),
        }) },
      },
      scales:{ x:{ stacked:true, grid:{display:false}, ticks:{font:{size:10}} },
               y:{ stacked:false, grid:{color:themeGridColor()}, ticks:{ font:{size:10}, callback:v=>'R$'+(Math.abs(v)>=1e3?(v/1e3).toFixed(0)+'k':v) } } },
      animation:{ duration:600 },
    }
  });
}

function aposTglView(view) {
  _aposView = view;
  G('apos-table-view').style.display = view==='table' ? '' : 'none';
  G('apos-chart-view').style.display = view==='chart' ? '' : 'none';
  G('apos-view-table').classList.toggle('primary', view==='table');
  G('apos-view-chart').classList.toggle('primary', view==='chart');
  aposCalc();
}

// Compute IPCA-corrected MA12 lucro without any DOM changes (used by Aposentadoria tab)
async function computeEvMA12LucroData() {
  try {
    const { byCatFull } = await getEvolucaoData();
    const now2 = new Date();
    const curM2 = `${now2.getFullYear()}-${String(now2.getMonth()+1).padStart(2,'0')}`;
    const allMonths = [...new Set(Object.keys(byCatFull))].filter(m => m <= curM2).sort();
    if (!allMonths.length) return;

    // Mesmo referencial de mês usado em refreshEvolucao
    const refMonth  = getIpcaRefMonth();
    const useIPCA   = G('ev-ipca')?.checked !== false;
    const corr = (v, m) => useIPCA && refMonth ? inflateMonth(v, m, refMonth) : (v || 0);

    const allSummary = computeSummaryFromByCat(allMonths, byCatFull);
    const allInc = allMonths.map(m => corr(allSummary[m]?.income   || 0, m));
    const allExp = allMonths.map(m => corr(allSummary[m]?.expenses || 0, m));
    const allLuc = allInc.map((v, i) => v - allExp[i]);
    const allMA12 = allMonths.map((_, i) => movAvg12(allLuc, i));

    window._evMA12LucroByMonth = {};
    allMonths.forEach((m, i) => { window._evMA12LucroByMonth[m] = allMA12[i]; });
  } catch(e) { console.error('computeEvMA12LucroData:', e); }
}

async function aposInit() {
  setupCurrencyInput(G('apos-goal-value'), aposCalc);
  setupCurrencyInput(G('apos-patrimonio-atual'));
  await aposLoadConfig();
  // Ensure patrimônio tab data is loaded so _patTotalByMonth is available
  if (!window._patTotalByMonth || Object.keys(window._patTotalByMonth).length === 0) {
    try { await refreshPatrimonio(); } catch(e) {}
  }
  // Ensure evolução IPCA-corrected MA12 data is available (data-only, no DOM changes)
  if (!window._evMA12LucroByMonth || Object.keys(window._evMA12LucroByMonth).length === 0) {
    try { await computeEvMA12LucroData(); } catch(e) {}
  }
  // Patrimônio atual é sempre puxado automaticamente do total real (não editável manualmente)
  await aposPullPatrimonio();
  await apos2Init();
  // Restaura qual das duas visões (projeção vs. pós-aposentadoria) estava
  // ativa — apos2Init() já carregou _aposMode do config junto com os outros
  // campos da visão 2.
  aposTglMode(_aposMode === 'inverso' ? 'inverso' : 'projecao');
  // Also update Focus in background
  if (!_aposFocusData) aposUpdateFocus().catch(() => {});
}

// ══ APOSENTADORIA — VISÃO 2: PÓS-APOSENTADORIA (drawdown) ══
// Simula o consumo do patrimônio já na aposentadoria: dado um patrimônio
// inicial e juros reais (sempre informados pelo usuário — não entram na
// rotação de "campo calculado"), mais renda não financeira mensal (ex:
// INSS/pensão) e despesa mensal, até quando o patrimônio dura? Ou, dado até
// quando quer garantir renda (idade-limite), qual a despesa mensal máxima
// sustentável? Exatamente um dos 3 campos (renda não financeira /
// idade-limite / despesa mensal) é calculado a partir dos outros 4 — o
// usuário escolhe qual via os rádios "🧮 calcular este campo".
let _aposMode = 'projecao'; // 'projecao' | 'inverso'
let _apos2View = 'table';
let _apos2Chart = null;
let _apos2CalcField = 'idade';
let _apos2IncomeAssetIds   = new Set(); // bens e direitos considerados geradores de renda (afeta "usar atual" do patrimônio inicial)
let _apos2PreserveAssetIds = new Set(); // bens e direitos a preservar (viram o patrimônio desejado na idade limite)

// Bens e direitos (_pat.assets) com o valor mais recente conhecido —
// mesmo padrão de leitura de histMap usado no gráfico de Patrimônio
// (renderer.js, refreshPatrimonioChart). Investimentos financeiros não
// entram aqui de propósito — o usuário pediu que eles sempre contem como
// geradores de renda, sem precisar aparecer nesta lista de seleção.
function apos2GetPatAssetsWithValues() {
  if (!_pat?.assets?.length) return [];
  const now = new Date();
  const curM = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
  const histMap = {};
  (_pat.historyAll || []).forEach(h => {
    if (!histMap[h.asset_id]) histMap[h.asset_id] = {};
    histMap[h.asset_id][h.month] = h.value;
  });
  return _pat.assets
    .filter(a => !a.hidden)
    .map(a => {
      const months = Object.keys(histMap[a.id] || {}).filter(m => m <= curM).sort();
      const value = months.length ? (histMap[a.id][months[months.length - 1]] || 0) : 0;
      return { id: a.id, name: a.name, value };
    })
    .filter(a => a.value > 0.01);
}

// Renderiza a lista de checkboxes de bens e direitos dentro de `containerId`
// — usado tanto pelo seletor de "geram renda" quanto pelo de "preservar".
function apos2RenderAssetPicker(containerId, selectedIds, toggleFnName) {
  const el = G(containerId);
  if (!el) return;
  const assets = apos2GetPatAssetsWithValues();
  el.innerHTML = assets.length
    ? assets.map(a => `
      <label style="display:flex;align-items:center;gap:6px;font-size:12px;padding:3px 0;cursor:pointer">
        <input type="checkbox" ${selectedIds.has(a.id)?'checked':''} onchange="${toggleFnName}(${a.id})" style="margin:0">
        <span style="flex:1">${esc(a.name)}</span>
        <span style="font-family:'DM Mono',monospace;color:var(--text3);font-size:11px">${fmtBRL(a.value)}</span>
      </label>`).join('')
    : '<div style="font-size:11px;color:var(--text3)">Nenhum bem/direito cadastrado na aba Patrimônio.</div>';
}

function apos2ToggleIncomeAssetsPanel() {
  const panel = G('apos2-income-assets-panel');
  if (!panel) return;
  const willOpen = panel.style.display === 'none';
  panel.style.display = willOpen ? '' : 'none';
  if (willOpen) apos2RenderAssetPicker('apos2-income-assets-panel', _apos2IncomeAssetIds, 'apos2ToggleIncomeAsset');
}
function apos2TogglePreserveAssetsPanel() {
  const panel = G('apos2-preserve-assets-panel');
  if (!panel) return;
  const willOpen = panel.style.display === 'none';
  panel.style.display = willOpen ? '' : 'none';
  if (willOpen) apos2RenderAssetPicker('apos2-preserve-assets-panel', _apos2PreserveAssetIds, 'apos2TogglePreserveAsset');
}
function apos2ToggleIncomeAsset(id) {
  if (_apos2IncomeAssetIds.has(id)) _apos2IncomeAssetIds.delete(id); else _apos2IncomeAssetIds.add(id);
  apos2SaveConfig();
  // Recalcula o "usar atual" na hora — antes só atualizava se o usuário
  // clicasse em "usar atual" de novo, o que não era nada óbvio depois de
  // mexer nos checkboxes.
  apos2PullPatrimonio();
}
function apos2TogglePreserveAsset(id) {
  if (_apos2PreserveAssetIds.has(id)) _apos2PreserveAssetIds.delete(id); else _apos2PreserveAssetIds.add(id);
  apos2SaveConfig();
  apos2UpdatePatFinalDisplay();
  apos2Calc();
}
// Quando há ativos marcados pra preservar, o campo "patrimônio desejado"
// passa a ser a SOMA deles, travado — igual ao padrão dos campos
// calculados (apos2SetCalcField). Desmarcando todos, volta a ser um campo
// normal, editável manualmente.
function apos2UpdatePatFinalDisplay() {
  const inp = G('apos2-pat-final');
  if (!inp) return;
  const selected = apos2GetPatAssetsWithValues().filter(a => _apos2PreserveAssetIds.has(a.id));
  if (selected.length) {
    const sum = selected.reduce((s,a) => s + a.value, 0);
    if (inp.setValue) inp.setValue(sum); else inp.value = sum;
    inp.readOnly = true;
    inp.style.background = '#f1f8e9'; inp.style.borderColor = '#c8e6c9'; inp.style.color = '#2e7d32';
  } else {
    inp.readOnly = false;
    inp.style.background = ''; inp.style.borderColor = ''; inp.style.color = '';
  }
}
function apos2TryEditPatFinal() {
  const inp = G('apos2-pat-final');
  if (inp?.readOnly) toast('Desmarque os ativos selecionados abaixo pra editar esse valor manualmente.');
}

// Valor futuro do patrimônio após n anos, com juros reais anuais r e
// retirada líquida anual fixa W (despesa − renda não financeira, já anual)
// — fórmula padrão de valor futuro de uma anuidade com principal inicial.
function apos2FV(P0, r, n, W) {
  if (Math.abs(r) < 1e-9) return P0 - W * n;
  const f = Math.pow(1 + r, n);
  return P0 * f - W * (f - 1) / r;
}
// Retirada líquida anual sustentável que leva o patrimônio de P0 a
// exatamente Pf (patrimônio desejado na idade limite — 0 por padrão, mas
// pode ser um valor positivo se o usuário quiser garantir uma herança) em
// exatamente n anos.
function apos2SolveW(P0, r, n, Pf) {
  if (n <= 0) return P0 - Pf;
  if (Math.abs(r) < 1e-9) return (P0 - Pf) / n;
  const f = Math.pow(1 + r, n);
  if (Math.abs(f - 1) < 1e-9) return (P0 - Pf) / n;
  return (P0 * f - Pf) * r / (f - 1);
}
// Quantos anos até o patrimônio atingir Pf, dada uma retirada líquida
// anual fixa W. Usa bisseção sobre apos2FV (monótona em n, pra qualquer
// combinação de sinais de r/W/Pf) em vez de fórmula fechada — mais robusto
// contra os vários casos-limite que Pf≠0 introduz (patrimônio podendo
// crescer rumo a um alvo positivo, nunca convergir, etc). Retorna Infinity
// se o patrimônio nunca CAI abaixo de Pf (fica sempre seguro), ou NaN se
// nunca ALCANÇA Pf (ex: já começa abaixo do alvo e só piora).
function apos2SolveN(P0, r, W, Pf) {
  const f0 = P0 - Pf;
  if (Math.abs(f0) < 1e-6) return 0; // já começa exatamente no alvo
  const f1 = apos2FV(P0, r, 1, W) - Pf;
  const movingToward = (f0 > 0 && f1 < f0) || (f0 < 0 && f1 > f0);
  if (!movingToward) return f0 > 0 ? Infinity : NaN;
  let hi = 1;
  while (hi <= 200 && Math.sign(apos2FV(P0, r, hi, W) - Pf) === Math.sign(f0)) hi *= 2;
  if (hi > 200) return f0 > 0 ? Infinity : NaN;
  let lo = hi / 2;
  for (let i = 0; i < 60; i++) {
    const mid = (lo + hi) / 2;
    if (Math.sign(apos2FV(P0, r, mid, W) - Pf) === Math.sign(f0)) lo = mid; else hi = mid;
  }
  return (lo + hi) / 2;
}

// Se o campo `field` está travado (é o "calculado" no momento), chacoalha
// o rótulo do rádio "🧮 calcular este campo" correspondente — dá pro
// usuário perceber onde precisa mexer pra poder editar aquele valor, em
// vez de só o campo ficar mudo sem explicação.
function apos2TryEdit(field) {
  if (_apos2CalcField !== field) return;
  const label = G(`apos2-radiolabel-${field}`);
  if (!label) return;
  label.classList.remove('apos2-shake');
  void label.offsetWidth; // força reflow pra poder reiniciar a animação
  label.classList.add('apos2-shake');
}

// Marca qual dos 3 campos elegíveis é "calculado" (travado/readonly,
// preenchido pelo app) — patrimônio inicial e juros reais nunca entram
// aqui, ficam sempre editáveis (o usuário pediu pra tirar esse botão dos
// dois, prefere sempre informar os dois manualmente).
function apos2SetCalcField(field) {
  _apos2CalcField = field;
  const map = { renda:'apos2-renda-nao-fin', idade:'apos2-age-limit', despesa:'apos2-despesa' };
  Object.entries(map).forEach(([k, id]) => {
    const el = G(id);
    if (!el) return;
    const isCalc = k === field;
    el.readOnly = isCalc;
    el.style.background  = isCalc ? '#f1f8e9' : '';
    el.style.borderColor = isCalc ? '#c8e6c9' : '';
    el.style.color       = isCalc ? '#2e7d32' : '';
  });
  apos2Calc();
}

// Média mensal (últimos 12 meses com dado) de receita ou despesa — de uma
// categoria específica (e subcategorias) ou de todas somadas juntas.
async function apos2Compute12mAvg(type, category) {
  try {
    const catRows = await ff.evolucaoByCat({ excludedCats: [] }).catch(() => []);
    const curMonthStr = todayStr().slice(0,7);
    const months = [];
    let d = new Date(curMonthStr + '-02');
    for (let i = 0; i < 12; i++) { d.setMonth(d.getMonth() - 1); months.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`); }
    const byMonth = {};
    catRows.forEach(r => { if (months.includes(r.month)) (byMonth[r.month] = byMonth[r.month]||[]).push(r); });
    const monthTotals = months.map(m => (byMonth[m]||[])
      .filter(r => !category || r.category === category || r.category.startsWith(category + ':'))
      .reduce((s,r) => s + (type === 'income' ? (r.income||0) : (r.expenses||0)), 0));
    const withData = monthTotals.filter(v => v > 0);
    return withData.length ? withData.reduce((a,b)=>a+b,0) / withData.length : null;
  } catch(e) { return null; }
}

async function apos2PopulateCategoryDropdown() {
  const sel = G('apos2-renda-cat');
  if (!sel) return;
  try {
    const rows = await ff.evolucaoByCat({ excludedCats: [] }).catch(() => []);
    const cats = [...new Set(rows.filter(r => (r.income||0) > 0).map(r => r.category))].sort((a,b) => a.localeCompare(b,'pt-BR'));
    const cur = sel.value;
    sel.innerHTML = '<option value="">— Escolher categoria de renda —</option>' + cats.map(c => `<option value="${esc(c)}"${c===cur?' selected':''}>${esc(c)}</option>`).join('');
  } catch(e) {}
}

async function apos2UpdateRendaHint() {
  const hintEl = G('apos2-renda-hint');
  if (!hintEl) return;
  const cat = G('apos2-renda-cat')?.value || '';
  if (!cat) { hintEl.textContent = ''; return; }
  const avg = await apos2Compute12mAvg('income', cat);
  hintEl.innerHTML = avg
    ? `📊 Média 12m: <a href="#" onclick="event.preventDefault();G('apos2-renda-nao-fin').setValue(${avg.toFixed(2)});apos2Calc()" style="font-weight:700;color:var(--green);text-decoration:none">${fmtBRL(avg)}</a> <span style="color:var(--text3)">(clique para usar)</span>`
    : `<span style="color:var(--text3)">Sem histórico de receita para "${esc(cat)}" nos últimos 12 meses</span>`;
}

// Média 12 meses de despesa — usa EXATAMENTE o mesmo dado da coluna "Média
// 12M desp." da aba Evolução (Resumo mensal): computeSummaryFromByCat (que
// agrupa por categoria-mãe e classifica pelo NET, não pelo campo `expenses`
// cru de cada categoria isolada) + movAvg12. Um cálculo ingênuo somando
// `expenses` de cada categoria direto (o que esta função fazia antes)
// ignora esse líquido — estornos/reembolsos dentro de uma categoria inflam
// o total, exatamente o tipo de distorção que a convenção do projeto já
// evita em outros lugares (ver getCatType/netClassify). Transferências já
// são excluídas antes disso, na própria query SQL (evolucao:monthly-by-category).
async function apos2GetDespesaMA12() {
  try {
    const { byCatFull } = await getEvolucaoData();
    const now2 = new Date();
    const curM2 = `${now2.getFullYear()}-${String(now2.getMonth()+1).padStart(2,'0')}`;
    const allMonths = [...new Set(Object.keys(byCatFull))].filter(m => m <= curM2).sort();
    if (!allMonths.length) return null;
    const refMonth = getIpcaRefMonth();
    const useIPCA  = G('ev-ipca')?.checked !== false;
    const corr = (v, m) => useIPCA && refMonth ? inflateMonth(v, m, refMonth) : (v || 0);
    const summary = computeSummaryFromByCat(allMonths, byCatFull);
    const allExp  = allMonths.map(m => corr(summary[m]?.expenses || 0, m));
    const allMA12 = allMonths.map((_, i) => movAvg12(allExp, i));
    return allMA12[allMA12.length - 1] || null; // valor do último mês disponível — igual à tabela de Evolução
  } catch(e) { console.error('apos2GetDespesaMA12:', e); return null; }
}

async function apos2UpdateDespesaHint() {
  const hintEl = G('apos2-despesa-hint');
  if (!hintEl) return;
  const avg = await apos2GetDespesaMA12();
  hintEl.innerHTML = avg
    ? `📊 Média 12m (igual à aba Evolução): <a href="#" onclick="event.preventDefault();G('apos2-despesa').setValue(${avg.toFixed(2)});apos2Calc()" style="font-weight:700;color:var(--green);text-decoration:none">${fmtBRL(avg)}</a> <span style="color:var(--text3)">(clique para usar)</span>`
    : '';
}

// "Usar atual" do patrimônio inicial — diferente do "patrimônio atual" cru
// da visão 1 (que soma TUDO), aqui só entram investimentos financeiros e
// contas bancárias (sempre — capital líquido, presumidamente rentável) mais
// os bens e direitos que o usuário marcou como geradores de renda no
// seletor abaixo (ex: um imóvel alugado entra, a casa onde mora não).
async function apos2PullPatrimonio() {
  try {
    const now = new Date();
    const curM = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
    const invTotal    = (window._invTotalByMonth || {})[curM] || 0;
    // accounts (global) só tem metadados (nome, tipo, banco...), NÃO tem
    // saldo — saldo por conta vive em _pat.accountBalances[].history, o
    // mesmo dado que a aba Patrimônio usa pra somar o card "Contas".
    const contasTotal = (_pat?.accountBalances || []).reduce((s, a) => {
      const up = (a.history || []).filter(h => h.month <= curM);
      return s + (up.length ? up[up.length - 1].balance : 0);
    }, 0);
    const bensTotal   = apos2GetPatAssetsWithValues()
      .filter(a => _apos2IncomeAssetIds.has(a.id))
      .reduce((s, a) => s + a.value, 0);
    const total = invTotal + contasTotal + bensTotal;
    const inp = G('apos2-pat-inicial');
    if (inp) {
      if (inp.setValue) inp.setValue(Math.max(0, total));
      else inp.value = Math.max(0, total).toLocaleString('pt-BR',{minimumFractionDigits:2});
      apos2Calc();
    }
  } catch(e) { toast('Erro ao buscar patrimônio: ' + e.message); }
}

async function apos2SaveConfig() {
  const fields = {
    apos2_ageRet:      G('apos2-age-ret')?.value || '',
    apos2_patInicial:  G('apos2-pat-inicial')?.value || '',
    apos2_rateReal:    G('apos2-rate-real')?.value || '',
    apos2_rendaNaoFin: G('apos2-renda-nao-fin')?.value || '',
    apos2_rendaCat:    G('apos2-renda-cat')?.value || '',
    apos2_ageLimit:    G('apos2-age-limit')?.value || '',
    apos2_despesa:     G('apos2-despesa')?.value || '',
    apos2_patFinal:    G('apos2-pat-final')?.value || '',
    apos2_calcField:   _apos2CalcField,
    apos2_incomeAssetIds:   [..._apos2IncomeAssetIds],
    apos2_preserveAssetIds: [..._apos2PreserveAssetIds],
    apos_mode:         _aposMode,
  };
  try { const cfg = await ff.overviewConfigGet().catch(() => null) || {}; await ff.overviewConfigSave({ ...cfg, ...fields }); }
  catch(e) { console.error('apos2SaveConfig:', e); }
}

async function apos2LoadConfig() {
  try {
    const cfg = await ff.overviewConfigGet().catch(() => null) || {};
    if (!cfg) return;
    if (cfg.apos2_ageRet)      G('apos2-age-ret').value = cfg.apos2_ageRet;
    if (cfg.apos2_patInicial) { const inp=G('apos2-pat-inicial');   if (inp) (inp.setValue?inp.setValue(parseBRLStr(cfg.apos2_patInicial)):(inp.value=cfg.apos2_patInicial)); }
    if (cfg.apos2_rateReal)   G('apos2-rate-real').value = cfg.apos2_rateReal;
    if (cfg.apos2_rendaNaoFin){ const inp=G('apos2-renda-nao-fin'); if (inp) (inp.setValue?inp.setValue(parseBRLStr(cfg.apos2_rendaNaoFin)):(inp.value=cfg.apos2_rendaNaoFin)); }
    if (cfg.apos2_rendaCat)   { const sel=G('apos2-renda-cat'); if (sel) sel.value = cfg.apos2_rendaCat; }
    if (cfg.apos2_ageLimit)   G('apos2-age-limit').value = cfg.apos2_ageLimit;
    if (cfg.apos2_despesa)    { const inp=G('apos2-despesa'); if (inp) (inp.setValue?inp.setValue(parseBRLStr(cfg.apos2_despesa)):(inp.value=cfg.apos2_despesa)); }
    if (cfg.apos2_patFinal)   { const inp=G('apos2-pat-final'); if (inp) (inp.setValue?inp.setValue(parseBRLStr(cfg.apos2_patFinal)):(inp.value=cfg.apos2_patFinal)); }
    if (cfg.apos2_calcField)  _apos2CalcField = cfg.apos2_calcField;
    if (Array.isArray(cfg.apos2_incomeAssetIds))   _apos2IncomeAssetIds   = new Set(cfg.apos2_incomeAssetIds);
    if (Array.isArray(cfg.apos2_preserveAssetIds)) _apos2PreserveAssetIds = new Set(cfg.apos2_preserveAssetIds);
    if (cfg.apos_mode)        _aposMode = cfg.apos_mode;
  } catch(e) {}
}

async function apos2Init() {
  setupCurrencyInput(G('apos2-pat-inicial'), apos2Calc);
  setupCurrencyInput(G('apos2-renda-nao-fin'), apos2Calc);
  setupCurrencyInput(G('apos2-despesa'), apos2Calc);
  setupCurrencyInput(G('apos2-pat-final'), apos2Calc);
  await apos2PopulateCategoryDropdown();
  await apos2LoadConfig();
  // O campo mostra "4.0" como placeholder, mas placeholder nunca é o
  // .value real do input — sem isso, o cálculo lia string vazia (rate=0)
  // até o usuário clicar e digitar algo, mesmo já vendo "4.0" na tela.
  // Preenche de verdade com o padrão, igual ao texto exibido, só quando
  // não há valor salvo (config antiga já continua funcionando normal).
  if (!G('apos2-rate-real')?.value?.toString()?.trim()) G('apos2-rate-real').value = '4.0';
  apos2UpdatePatFinalDisplay(); // se havia ativos a preservar salvos, já trava o campo antes do primeiro cálculo
  const radio = document.querySelector(`input[name="apos2-calc-field"][value="${_apos2CalcField}"]`);
  if (radio) radio.checked = true;
  apos2SetCalcField(_apos2CalcField); // aplica o readonly visual certo e já recalcula
  apos2UpdateDespesaHint();
  if (G('apos2-renda-cat')?.value) apos2UpdateRendaHint();
}

async function apos2Calc() {
  apos2SaveConfig();

  const ageRet = parseInt(G('apos2-age-ret')?.value || '0');
  const calcField = _apos2CalcField;

  const fieldEls = { renda:'apos2-renda-nao-fin', idade:'apos2-age-limit', despesa:'apos2-despesa' };
  const labels   = { renda:'renda não financeira', idade:'idade limite', despesa:'despesa mensal' };
  const missing = [];
  if (!ageRet) missing.push('idade inicial');
  if (!G('apos2-pat-inicial')?.value?.trim()) missing.push('patrimônio inicial');
  if (!G('apos2-rate-real')?.value?.toString()?.trim()) missing.push('juros reais');
  Object.keys(fieldEls).forEach(k => {
    if (k === calcField) return;
    const el = G(fieldEls[k]);
    if (!el || el.value.trim() === '') missing.push(labels[k]);
  });
  if (missing.length) {
    G('apos2-kpis').innerHTML = `<div style="color:var(--text3);font-size:13px;padding:12px">Preencha: ${missing.join(', ')}.</div>`;
    if (G('apos2-table-body')) G('apos2-table-body').innerHTML = '';
    return;
  }

  const P0   = aposParseInput('apos2-pat-inicial');
  const rate = (parseFloat(G('apos2-rate-real').value) || 0) / 100;
  const Pf   = aposParseInput('apos2-pat-final'); // patrimônio desejado na idade limite — 0 se em branco (comportamento antigo)
  let Rm     = calcField === 'renda'   ? null : aposParseInput('apos2-renda-nao-fin');
  let ageLim = calcField === 'idade'   ? null : parseInt(G('apos2-age-limit').value || '0');
  let Dm     = calcField === 'despesa' ? null : aposParseInput('apos2-despesa');

  if (calcField !== 'idade' && ageLim <= ageRet) {
    G('apos2-kpis').innerHTML = `<div style="color:var(--red);font-size:13px;padding:12px">A idade limite precisa ser maior que a idade inicial.</div>`;
    if (G('apos2-table-body')) G('apos2-table-body').innerHTML = '';
    return;
  }

  const n = calcField === 'idade' ? null : (ageLim - ageRet);
  let resultMsg = '', infinite = false;

  if (calcField === 'idade') {
    const W = (Dm - Rm) * 12;
    const nCalc = apos2SolveN(P0, rate, W, Pf);
    if (nCalc === Infinity) {
      infinite = true;
      ageLim = ageRet + 60; // horizonte de exibição
      resultMsg = Pf > 0
        ? `Patrimônio nunca cai abaixo dos ${fmtBRL(Pf)} desejados`
        : 'Patrimônio nunca se esgota (renda não financeira + juros cobrem a despesa)';
    } else if (isNaN(nCalc)) {
      G('apos2-kpis').innerHTML = `<div style="color:var(--red);font-size:13px;padding:12px">Com esses valores, o patrimônio nunca chega a ${fmtBRL(Pf)} — ajuste a despesa, a renda não financeira ou o patrimônio desejado.</div>`;
      if (G('apos2-table-body')) G('apos2-table-body').innerHTML = '';
      return;
    } else {
      ageLim = ageRet + nCalc;
      resultMsg = `Patrimônio ${Pf>0?`chega a ${fmtBRL(Pf)}`:'dura'} até os ${ageLim.toFixed(1)} anos`;
      G('apos2-age-limit').value = Math.round(ageLim);
    }
  } else if (calcField === 'despesa') {
    const W = apos2SolveW(P0, rate, n, Pf);
    Dm = W / 12 + Rm;
    resultMsg = `Despesa mensal máxima sustentável: ${fmtBRL(Dm)}`;
    G('apos2-despesa').setValue(Math.max(0, Dm));
  } else if (calcField === 'renda') {
    const W = apos2SolveW(P0, rate, n, Pf);
    Rm = Dm - W / 12;
    resultMsg = `Renda não financeira necessária: ${fmtBRL(Math.max(0, Rm))}`;
    G('apos2-renda-nao-fin').setValue(Math.max(0, Rm));
  }

  const W = (Dm - Rm) * 12;
  const rows = apos2BuildRows(P0, rate, ageRet, ageLim, W, Pf);
  renderApos2KPIs({ resultMsg, P0, rate, Rm, Dm, ageLim, W, infinite, Pf });
  if (_apos2View === 'table') renderApos2Table(rows);
  else renderApos2Charts(rows);
}

function apos2BuildRows(P0, rate, ageRet, ageLim, W, Pf) {
  const curYear = new Date().getFullYear();
  const nYears = Math.max(1, Math.round(ageLim - ageRet));
  const rows = [];
  let pat = P0;
  for (let y = 0; y <= nYears; y++) {
    rows.push({ ano: curYear + y, idade: ageRet + y, patInicio: pat, rendimento: pat * rate, retirada: W });
    const patNext = pat * (1 + rate) - W;
    // Só interrompe cedo mostrando "zerou" quando o alvo TAMBÉM é zero —
    // se o alvo é positivo (herança), a trajetória segue até o fim (deve
    // terminar perto do valor desejado, não de zero).
    if (Pf <= 0 && patNext <= 0 && pat > 0) {
      // Linha final só marca "patrimônio zerado" — sem rendimento nem
      // retirada de verdade nesse ano (o que sobrava já foi consumido no
      // ano anterior), diferente de mostrar W cheio como se ainda tivesse
      // saindo dinheiro de um patrimônio que já é zero.
      rows.push({ ano: curYear + y + 1, idade: ageRet + y + 1, patInicio: 0, rendimento: 0, retirada: 0 });
      break;
    }
    pat = patNext;
  }
  return rows;
}

function renderApos2KPIs({ resultMsg, P0, rate, Rm, Dm, ageLim, W, infinite, Pf }) {
  const kpis = [
    { icon:'🧮', label:'Resultado calculado', value: resultMsg, color:'#7c3aed' },
    { icon:'🏛️', label:'Patrimônio inicial', value: fmtBRL(P0), color:'var(--green)' },
    { icon:'📊', label:'Juros reais', value:`${(rate*100).toFixed(2)}% a.a.`, color:'#0891b2' },
    { icon:'💵', label:'Retirada líquida/mês', value: fmtBRL(W/12), sub:`despesa ${fmtBRL(Dm)} − renda não fin. ${fmtBRL(Rm)}`, color: W>0?'#d97706':'#43a047' },
    { icon:'⏳', label:'Idade limite', value: infinite ? '∞ (nunca acaba)' : Math.round(ageLim)+' anos', color:'#ef5350' },
    { icon:'🎁', label:'Patrimônio desejado na idade limite', value: fmtBRL(Pf), sub: Pf>0?'herança/reserva a garantir':'patrimônio pode zerar', color:'#0d9488' },
  ];
  G('apos2-kpis').innerHTML = kpis.map(k => `
    <div style="background:var(--bg2);border:1px solid var(--border);border-left:4px solid ${k.color};border-radius:12px;padding:14px 16px;box-shadow:0 1px 3px rgba(20,30,50,.04)">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">
        <span style="font-size:18px">${k.icon}</span>
        <span style="font-size:11px;color:var(--text3);font-weight:600;text-transform:uppercase;letter-spacing:.02em">${k.label}</span>
      </div>
      <div style="font-size:16px;font-weight:800;color:${k.color}">${k.value}</div>
      ${k.sub?`<div style="font-size:11px;color:var(--text3);margin-top:3px">${k.sub}</div>`:''}
    </div>`).join('');
}

function renderApos2Table(rows) {
  const tbody = G('apos2-table-body');
  if (!tbody) return;
  const mono = `font-family:'DM Mono',monospace`;
  tbody.innerHTML = rows.map((r,i) => {
    const isLast = i === rows.length - 1;
    return `<tr style="${isLast?'background:rgba(239,83,80,.08)':''}">
      <td style="font-size:12px;padding:5px 8px">${r.ano}</td>
      <td style="font-size:12px;padding:5px 8px;text-align:center">${r.idade}</td>
      <td class="right" style="font-size:12px;padding:5px 8px;${mono}">${fmtBRL(r.patInicio)}</td>
      <td class="right" style="font-size:12px;padding:5px 8px;${mono};color:var(--green)">${fmtBRL(r.rendimento)}</td>
      <td class="right" style="font-size:12px;padding:5px 8px;${mono};color:var(--red)">${fmtBRL(r.retirada)}</td>
    </tr>`;
  }).join('');
}

function renderApos2Charts(rows) {
  if (_apos2Chart) { try{_apos2Chart.destroy();}catch(e){} _apos2Chart=null; }
  const labels = rows.map(r => `${r.idade}a`);
  const patData = rows.map(r => Math.round(r.patInicio));
  const fmtY = v => v==null?'':('R$'+(Math.abs(v)>=1e6?(v/1e6).toFixed(1)+'M':Math.abs(v)>=1e3?(v/1e3).toFixed(0)+'k':v));
  const GREEN = '#43a047';
  const ctx = G('apos2-chart')?.getContext('2d');
  if (!ctx) return;
  _apos2Chart = new Chart(ctx, {
    type: 'line',
    data: { labels, datasets: [
      { label:'Patrimônio', data:patData, borderColor:GREEN, backgroundColor:evChartGradient(ctx,GREEN,380),
        fill:true, tension:.4, borderWidth:2.5, pointRadius:0, pointHoverRadius:6, pointHoverBackgroundColor:GREEN, pointHoverBorderColor:'#fff', pointHoverBorderWidth:2, spanGaps:false },
    ]},
    options: { responsive:true, maintainAspectRatio:false,
      interaction:{ mode:'index', intersect:false },
      plugins:{
        legend:{ display:false },
        title:{ display:true, text:'Patrimônio pós-aposentadoria, por idade', font:{size:13,weight:'700'}, color:GREEN, padding:{bottom:12} },
        tooltip:{ enabled:false, external:(context) => dashTooltip(context, {
          getTitle: (dp) => labels[dp[0].dataIndex],
          getRows:  (dp) => dp.filter(d=>d.parsed.y!=null).map(d => ({ color:d.dataset.borderColor, label:d.dataset.label, value:fmtBRL(d.parsed.y) })),
        }) },
      },
      scales:{ x:{ grid:{display:false}, ticks:{font:{size:10}} }, y:{ grid:{color:themeGridColor()}, ticks:{ font:{size:10}, callback:fmtY } } },
      animation:{ duration:600 },
    }
  });
}

function apos2TglView(view) {
  _apos2View = view;
  G('apos2-table-view').style.display = view==='table' ? '' : 'none';
  G('apos2-chart-view').style.display = view==='chart' ? '' : 'none';
  G('apos2-view-table').classList.toggle('primary', view==='table');
  G('apos2-view-chart').classList.toggle('primary', view==='chart');
  apos2Calc();
}

function aposTglMode(mode) {
  _aposMode = mode;
  G('apos-view-projecao').style.display = mode==='projecao' ? '' : 'none';
  G('apos-view-inverso').style.display  = mode==='inverso'  ? '' : 'none';
  G('apos-mode-projecao').classList.toggle('primary', mode==='projecao');
  G('apos-mode-inverso').classList.toggle('primary', mode==='inverso');
  apos2SaveConfig();
  if (mode === 'inverso') apos2Calc(); else aposCalc();
}

// ══ ACCOUNT CHART ══════════════════════════════════════════════════════════

let _acctView = 'table';   // 'table' | 'chart'
let _acctChart = null;

function acctSetView(view) {
  _acctView = view;
  const tableView = G('acct-table-view');
  const chartView = G('acct-chart-view');
  const btnTable  = G('acct-view-table');
  const btnChart  = G('acct-view-chart');
  if (!tableView || !chartView) return;

  tableView.style.display = view === 'table' ? '' : 'none';
  chartView.style.display = view === 'chart' ? '' : 'none';

  if (btnTable) {
    btnTable.style.background = view === 'table' ? 'var(--accent)' : 'var(--bg2)';
    btnTable.style.color      = view === 'table' ? '#fff' : 'var(--text2)';
  }
  if (btnChart) {
    btnChart.style.background = view === 'chart' ? 'var(--accent)' : 'var(--bg2)';
    btnChart.style.color      = view === 'chart' ? '#fff' : 'var(--text2)';
  }

  if (view === 'chart') refreshAccountChart();
}

async function refreshAccountChart() {
  if (!currentAccountId) return;
  const canvas = G('acct-chart-canvas');
  if (!canvas) return;

  const acc = accounts.find(a => a.id === currentAccountId);
  const projMonths     = parseInt(G('acct-proj-months')?.value || '3');
  const inclRecurring  = G('acct-proj-recurring')?.checked !== false;
  const inclFuture     = G('acct-proj-future')?.checked !== false;

  // Fetch all transactions for this account (no date limit for chart)
  const allTxs = await ff.listTx({ accountId: currentAccountId, sortBy: 'date', order: 'asc' });

  const today = new Date();
  today.setHours(0,0,0,0);
  const todayStr2 = today.toISOString().slice(0,10);

  // Build daily balance series from all past transactions
  const dailyBalance = {};
  let running = 0;

  // Sort all transactions chronologically
  const sorted = [...allTxs].sort((a,b) => a.date.localeCompare(b.date) || a.id - b.id);

  // Find earliest date
  const firstDate = sorted.length ? sorted[0].date : todayStr2;

  sorted.forEach(tx => {
    if (!inclFuture && tx.date > todayStr2) return;
    running += tx.amount;
    dailyBalance[tx.date] = running;
  });

  // Build series: one point per day from firstDate to today
  const seriesDates = [];
  const seriesVals  = [];
  let lastBal = 0;
  const start = new Date(firstDate);
  const end   = new Date(today);

  for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
    const ds = d.toISOString().slice(0,10);
    if (dailyBalance[ds] !== undefined) lastBal = dailyBalance[ds];
    seriesDates.push(ds);
    seriesVals.push(parseFloat(lastBal.toFixed(2)));
  }

  // ── Projection ──
  const projDates = [];
  const projVals  = [];
  const projToday = new Date(today);

  if (projMonths > 0) {
    // Get recurring transactions for this account
    let recurringTxs = [];
    if (inclRecurring) {
      try {
        const allRecurring = await ff.listRecurring();
        recurringTxs = (allRecurring || []).filter(r => r.account_id === currentAccountId && !r.paused);
      } catch(e) {}
    }

    // Get already-scheduled future transactions (date > today)
    const futureTxs = inclFuture
      ? sorted.filter(t => t.date > todayStr2)
      : [];

    const projEndDate = new Date(today);
    projEndDate.setMonth(projEndDate.getMonth() + projMonths);

    // Build projection day by day
    let projBal = lastBal;
    const projDailyDelta = {};

    // Add future scheduled transactions
    futureTxs.forEach(tx => {
      projDailyDelta[tx.date] = (projDailyDelta[tx.date] || 0) + tx.amount;
    });

    // Add recurring projections
    if (inclRecurring) {
      recurringTxs.forEach(rec => {
        const freqDays = {
          'daily': 1, 'weekly': 7, 'biweekly': 14, 'monthly': null, 'annual': null
        }[rec.frequency];

        let cur = new Date(Math.max(new Date(rec.next_date), today));
        const endRec = rec.end_date ? new Date(rec.end_date) : projEndDate;

        while (cur <= projEndDate && cur <= endRec) {
          const ds = cur.toISOString().slice(0,10);
          if (ds > todayStr2) {
            projDailyDelta[ds] = (projDailyDelta[ds] || 0) + rec.amount;
          }
          if (freqDays) {
            cur.setDate(cur.getDate() + freqDays);
          } else if (rec.frequency === 'monthly') {
            cur.setMonth(cur.getMonth() + 1);
          } else if (rec.frequency === 'annual') {
            cur.setFullYear(cur.getFullYear() + 1);
          } else {
            break;
          }
        }
      });
    }

    for (let d = new Date(today); d <= projEndDate; d.setDate(d.getDate() + 1)) {
      const ds = d.toISOString().slice(0,10);
      projBal += projDailyDelta[ds] || 0;
      projDates.push(ds);
      projVals.push(parseFloat(projBal.toFixed(2)));
    }
  }

  // ── Downsample to weekly points for readability ──
  function downsample(dates, vals, maxPoints = 200) {
    if (dates.length <= maxPoints) return { dates, vals };
    const step = Math.ceil(dates.length / maxPoints);
    const od = [], ov = [];
    for (let i = 0; i < dates.length; i += step) {
      od.push(dates[i]); ov.push(vals[i]);
    }
    // Always include last point
    if (od[od.length-1] !== dates[dates.length-1]) {
      od.push(dates[dates.length-1]); ov.push(vals[vals.length-1]);
    }
    return { dates: od, vals: ov };
  }

  const hist = downsample(seriesDates, seriesVals);
  const proj = downsample(projDates, projVals);

  // ── Chart ──
  if (_acctChart) { try { _acctChart.destroy(); } catch(e) {} _acctChart = null; }

  const allLabels = [...hist.dates, ...proj.dates.slice(1)];
  const histData  = [...hist.vals, ...Array(proj.dates.length > 1 ? proj.dates.length - 1 : 0).fill(null)];
  const projData  = [...Array(hist.dates.length - 1).fill(null), hist.vals[hist.vals.length-1], ...proj.vals.slice(1)];

  const currentBal = seriesVals[seriesVals.length - 1] || 0;
  const zeroLine   = allLabels.map(() => 0);

  const ctx = canvas.getContext('2d');
  _acctChart = new Chart(ctx, {
    type: 'line',
    data: {
      labels: allLabels,
      datasets: [
        {
          label: 'Saldo histórico',
          data: histData,
          borderColor: currentBal >= 0 ? '#2563eb' : '#dc2626',
          backgroundColor: currentBal >= 0 ? 'rgba(37,99,235,0.08)' : 'rgba(220,38,38,0.08)',
          borderWidth: 2,
          pointRadius: 0,
          pointHoverRadius: 4,
          fill: true,
          tension: 0.2,
        },
        ...(projMonths > 0 ? [{
          label: `Projeção (+${projMonths}m)`,
          data: projData,
          borderColor: '#f59e0b',
          backgroundColor: 'rgba(245,158,11,0.06)',
          borderWidth: 2,
          borderDash: [6, 4],
          pointRadius: 0,
          pointHoverRadius: 4,
          fill: true,
          tension: 0.2,
        }] : []),
        {
          label: 'Zero',
          data: zeroLine,
          borderColor: 'rgba(100,100,100,0.3)',
          borderWidth: 1,
          borderDash: [2, 2],
          pointRadius: 0,
          fill: false,
        },
      ],
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { display: false },
        tooltip: {
          callbacks: {
            title: items => {
              const d = new Date(items[0].label + 'T12:00:00');
              return d.toLocaleDateString('pt-BR', { day:'2-digit', month:'short', year:'numeric' });
            },
            label: item => {
              if (item.dataset.label === 'Zero') return null;
              const v = item.raw;
              if (v === null) return null;
              return `${item.dataset.label}: ${fmtBRL(v)}`;
            },
          },
        },
      },
      scales: {
        x: {
          ticks: {
            maxTicksLimit: 10,
            callback: function(val, idx) {
              const label = this.getLabelForValue(val);
              const d = new Date(label + 'T12:00:00');
              return d.toLocaleDateString('pt-BR', { day:'2-digit', month:'short' });
            },
            font: { size: 10 },
          },
          grid: { color: 'rgba(128,128,128,0.1)' },
        },
        y: {
          ticks: {
            callback: v => {
              if (Math.abs(v) >= 1e6) return 'R$' + (v/1e6).toFixed(1) + 'M';
              if (Math.abs(v) >= 1e3) return 'R$' + (v/1e3).toFixed(0) + 'k';
              return 'R$' + v.toFixed(0);
            },
            font: { size: 10 },
          },
          grid: { color: 'rgba(128,128,128,0.1)' },
        },
      },
    },
  });

  // Legend
  const legend = G('acct-chart-legend');
  if (legend) {
    const endProj = projVals[projVals.length - 1];
    const diff    = projMonths > 0 ? endProj - currentBal : null;
    legend.innerHTML = [
      `<span>● Saldo atual: <strong>${fmtBRL(currentBal)}</strong></span>`,
      projMonths > 0 && diff !== null
        ? `<span>◆ Projeção em ${projMonths}m: <strong class="${diff>=0?'amt-inc':'amt-exp'}">${fmtBRL(endProj)}</strong> (${diff>=0?'+':''}${fmtBRL(diff)})</span>`
        : '',
      seriesDates.length > 0
        ? `<span style="color:var(--text3)">${fmtDate(seriesDates[0])} → ${fmtDate(seriesDates[seriesDates.length-1])}</span>`
        : '',
    ].filter(Boolean).join('  ·  ');
  }
}

// ══ LICENSING ══════════════════════════════════════════════════════════════

let _licStatus = null;

async function checkLicense() {
  try {
    _licStatus = await ff.licenseStatus();
  } catch(e) {
    _licStatus = { status: 'trial', daysLeft: 999 };
  }

  const modal = G('modal-license');
  if (!modal) return;

  const { status, reason, daysLeft, avgIncome, avgExpense, totalWealth } = _licStatus;

  // Update UI sections
  G('lic-trial-banner').style.display    = status === 'trial'           ? '' : 'none';
  G('lic-social-banner').style.display   = status === 'free_social'     ? '' : 'none';
  G('lic-payment-section').style.display = (status === 'payment_required' || status === 'trial' || status === 'free_social') ? '' : 'none';
  G('lic-licensed-section').style.display= status === 'licensed'        ? '' : 'none';

  // During trial / free-social, the payment section is shown but framed as
  // "already have a code?" — the warning banner about the trial ending is hidden,
  // and the price card is collapsed since the user isn't required to pay yet.
  const payWarning  = G('lic-payment-warning');
  const payPriceBox = G('lic-payment-price');
  const payIntro    = G('lic-payment-intro');
  if (status === 'trial' || status === 'free_social') {
    if (payWarning)  payWarning.style.display  = 'none';
    if (payPriceBox) payPriceBox.style.display = 'none';
    if (payIntro)    payIntro.innerHTML = 'Já tem um código de licença? Você pode ativá-lo agora, mesmo durante o período gratuito:';
  } else {
    if (payWarning)  payWarning.style.display  = '';
    if (payPriceBox) payPriceBox.style.display = '';
    if (payIntro)    payIntro.innerHTML = 'Após o pagamento, você receberá um <strong>código de licença</strong> por email. Insira abaixo:';
  }

  if (status === 'trial') {
    G('lic-trial-days').textContent = `${daysLeft} dias restantes do período gratuito de 6 meses.`;
  }
  if (status === 'payment_required') {
    const parts = [];
    if (avgIncome  >= 3000)   parts.push(`renda média de ${fmtBRL(avgIncome)}/mês`);
    if (avgExpense >= 5000)   parts.push(`despesas médias de ${fmtBRL(avgExpense)}/mês`);
    if (totalWealth >= 100000) parts.push(`patrimônio de ${fmtBRL(totalWealth)}`);
    const detail = parts.length ? parts.join(', ') : reason;
    G('lic-payment-reason').innerHTML =
      `Seu uso do Cruzeiro (${detail}) está acima do limite gratuito.<br><br>` +
      `Você ainda pode <strong>navegar, consultar e exportar seus dados normalmente</strong> — ` +
      `mas para <strong>registrar novos lançamentos</strong>, é necessária uma licença.`;
  }
  if (status === 'licensed') {
    const s = await ff.settingsGet().catch(()=>({}));
    G('lic-licensed-email').textContent = `Email: ${s.licenseEmail || '—'}`;
  }

  G('lic-message').innerHTML = '';

  // payment_required: show a persistent non-blocking banner (modal still accessible via Settings)
  // Do NOT block navigation — only block transaction creation (enforced in saveTx/import)
  const payBanner = G('lic-payment-banner');
  if (payBanner) payBanner.style.display = status === 'payment_required' ? '' : 'none';

  // Show modal non-blockingly on first visit or trial nearing end
  if (status === 'trial' && daysLeft <= 30) {
    G('lic-continue-btn').style.display = '';
    modal.style.display = 'flex'; modal.classList.add('open');
  }
}

async function licActivate() {
  const code  = G('lic-code-inp')?.value?.trim();
  const email = G('lic-email-inp')?.value?.trim();
  const errEl = G('lic-error');
  if (!code || !email) { errEl.textContent = 'Preencha email e código.'; return; }
  try {
    const r = await ff.licenseActivate(code, email);
    if (r.ok) {
      toast('✅ Licença ativada com sucesso!');
      await checkLicense();
      closeModal('modal-license');
    } else {
      errEl.textContent = r.error || 'Código inválido.';
    }
  } catch(e) { errEl.textContent = 'Erro ao verificar código.'; }
}

async function licDeactivate() {
  if (!await showConfirmDialog('Remover licença?', 'O app voltará ao período de avaliação.', 'Remover', true)) return;
  await ff.licenseDeactivate();
  await checkLicense();
}

function licContinue() {
  const m = G('modal-license');
  if (m) { m.style.display = 'none'; m.classList.remove('open'); }
}

// Simulate a license status for testing (Configurações → Licença → Modo de teste)
async function licDebugSet(value) {
  await ff.licenseDebugOverride(value || null);
  await checkLicense();
  if (value) {
    const labels = { trial: 'Período gratuito', free_social: 'Gratuito (uso social)', payment_required: 'Licença necessária' };
    toast(`🧪 Simulando: ${labels[value] || value}`);
    openLicenseModal();
  } else {
    toast('Voltou ao status normal');
  }
  // Refresh the badge in Settings too
  ff.licenseStatus().then(s => {
    const el = G('settings-lic-status');
    if (!el) return;
    const map = { trial:'🟡 Período gratuito', free_social:'🟢 Gratuito', licensed:'✅ Licenciado', payment_required:'🔴 Licença necessária' };
    el.textContent = map[s.status] || s.status;
    el.style.color = s.status === 'payment_required' ? 'var(--red)' : s.status === 'licensed' ? 'var(--green)' : 'var(--text3)';
  }).catch(()=>{});
}

function licBuy() {
  // Replace with your actual purchase URL when available
  require('electron').shell.openExternal('https://cruzeiro.app/comprar');
}

function showLicenseModal() { openLicenseModal(); } // alias used by payment banner
function openLicenseModal() {
  checkLicense().then(() => {
    const _lm = G('modal-license');
    if (_lm) { _lm.style.display = 'flex'; _lm.classList.add('open'); }
  });
}

// ══ DATA EXPORT ════════════════════════════════════════════════════════════

async function exportData() {
  try {
    const result = await ff.exportData();
    if (!result?.ok) { toast('Erro ao exportar dados'); return; }

    // Build export object
    const exportObj = {
      exportVersion: 1,
      exportDate: new Date().toISOString(),
      appVersion: '4.0',
      data: result.data,
    };

    // Trigger download via hidden link
    const json = JSON.stringify(exportObj, null, 2);
    const blob = new Blob([json], { type: 'application/json' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    const date = new Date().toISOString().slice(0, 10);
    a.href     = url;
    a.download = `cruzeiro-export-${date}.json`;
    a.click();
    URL.revokeObjectURL(url);
    toast(`✅ Exportado: cruzeiro-export-${date}.json`);
  } catch(e) {
    toast('Erro ao exportar: ' + e.message);
  }
}

async function exportCSV() {
  try {
    const result = await ff.exportData();
    if (!result?.ok) return;

    const txs = result.data.transactions || [];
    const header = ['Data', 'Conta', 'Categoria', 'Memorando', 'Valor', 'Conferido', 'Transferência'];
    const escCsv = s => `"${String(s).replace(/"/g, '""')}"`;
    const rows = txs.map(t => [
      t.date, escCsv(t.account_name || ''), escCsv(t.category || ''),
      escCsv(t.memo || ''),
      t.amount.toFixed(2).replace('.', ','),
      t.cleared ? 'Sim' : 'Não',
      t.transfer_id ? 'Sim' : 'Não',
    ]);

    // Semicolon delimiter (Brazilian CSV convention) — avoids conflict with
    // comma decimal separators when using "Text to Columns" in Excel.
    const csv = [header, ...rows].map(r => r.join(';')).join('\r\n');
    const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8' }); // BOM for Excel
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    const date = new Date().toISOString().slice(0, 10);
    a.href     = url;
    a.download = `cruzeiro-lancamentos-${date}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    toast(`✅ CSV exportado: cruzeiro-lancamentos-${date}.csv`);
  } catch(e) {
    toast('Erro ao exportar CSV: ' + e.message);
  }
}

async function exportQIF() {
  try {
    const result = await ff.exportData();
    if (!result?.ok) return;

    const txs  = result.data.transactions || [];
    const accs = result.data.accounts     || [];

    // Group transactions by account
    const byAccount = {};
    txs.forEach(t => {
      const key = t.account_name || String(t.account_id);
      if (!byAccount[key]) byAccount[key] = { type: t.account_type || 'Bank', txs: [] };
      byAccount[key].txs.push(t);
    });

    // QIF account type map
    const qifType = type => ({
      bank: 'Bank', credit: 'CCard', investment: 'Invst', cash: 'Cash'
    })[type] || 'Bank';

    let qif = '';
    Object.entries(byAccount).forEach(([accName, { type, txs: aTxs }]) => {
      qif += `!Account
N${accName}
T${qifType(type)}
^
`;
      qif += `!Type:${qifType(type)}
`;
      aTxs.sort((a, b) => a.date.localeCompare(b.date)).forEach(t => {
        // QIF date format: MM/DD/YYYY
        const [y, mo, d] = t.date.split('-');
        const qDate = `${mo}/${d}/${y}`;
        const amount = t.amount.toFixed(2);
        const cleared = t.cleared ? 'X' : '';
        qif += `D${qDate}
`;
        qif += `T${amount}
`;
        if (cleared) qif += `C${cleared}
`;
        if (t.memo)     qif += `M${t.memo}
`;
        if (t.category) qif += `L${t.category}
`;
        if (t.payee)    qif += `P${t.payee}
`;
        qif += `^
`;
      });
    });

    const blob = new Blob([qif], { type: 'text/plain;charset=utf-8' });
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    const date = new Date().toISOString().slice(0, 10);
    a.href     = url;
    a.download = `cruzeiro-export-${date}.qif`;
    a.click();
    URL.revokeObjectURL(url);
    toast(`✅ QIF exportado: cruzeiro-export-${date}.qif`);
  } catch(e) {
    toast('Erro ao exportar QIF: ' + e.message);
  }
}

// ══ INV TRANSACTION RECLASSIFY PANEL ═══════════════════════════════════════

async function openInvReclassifyPanel() {
  const assetId = parseInt(G('inv-asset-id')?.value);
  if (!assetId) { toast('Salve o ativo primeiro'); return; }

  const panel = G('inv-reclassify-panel');
  const list  = G('inv-reclassify-list');
  if (!panel || !list) return;

  panel.style.display = '';

  // Load all non-valuation transactions for this asset
  const txs = await ff.invTxList({ assetId });
  const cash = txs.filter(t => !(t.tx_type === 'atualizacao') && t.notes !== '__auto_purchase__');

  if (!cash.length) {
    list.innerHTML = '<div style="color:var(--text3);padding:8px">Nenhuma movimentação encontrada para este ativo.</div>';
    return;
  }

  const TYPE_LABELS = {
    compra: '🟢 Compra',      aporte: '➕ Aporte',
    venda:  '🔴 Venda',       amortizacao: '📉 Amortização',
    dividendo: '💰 Dividendo', juros: '💵 Juros',
    jcp: '🏦 JCP',            cupom: '🎫 Cupom',
    taxa: '📋 Taxa',
  };
  const IS_EXT = new Set(['compra','aporte','venda','amortizacao']);
  const IS_INC = new Set(['dividendo','juros','jcp','cupom','taxa']);

  // Group by month for display
  const byMonth = {};
  cash.forEach(t => {
    const m = t.month.slice(0,7);
    if (!byMonth[m]) byMonth[m] = [];
    byMonth[m].push(t);
  });

  list.innerHTML = Object.entries(byMonth).sort(([a],[b]) => a.localeCompare(b)).map(([m, txList]) => {
    const rows = txList.map(t => {
      const isExt = IS_EXT.has(t.tx_type);
      const isInc = IS_INC.has(t.tx_type);
      const currentColor = isExt ? 'var(--accent)' : isInc ? 'var(--green)' : 'var(--text3)';
      const label = TYPE_LABELS[t.tx_type] || t.tx_type;

      // Reclassify buttons — show the OTHER category's options
      const extOptions = ['compra','aporte','venda','amortizacao']
        .map(type => `<button class="btn xs" style="padding:1px 4px;font-size:9px;${t.tx_type===type?'background:var(--accent);color:#fff;':''}border-color:var(--accent);color:var(--accent)"
          onclick="invReclassifyTx(${t.id},'${type}',this)">${TYPE_LABELS[type]}</button>`)
        .join('');
      const incOptions = ['dividendo','juros','jcp','cupom','taxa']
        .map(type => `<button class="btn xs" style="padding:1px 4px;font-size:9px;${t.tx_type===type?'background:var(--green);color:#fff;':''}border-color:var(--green);color:var(--green)"
          onclick="invReclassifyTx(${t.id},'${type}',this)">${TYPE_LABELS[type]}</button>`)
        .join('');

      return `<div style="display:flex;align-items:flex-start;gap:6px;padding:5px 8px;border-bottom:1px solid var(--border);flex-wrap:wrap" id="inv-reclass-row-${t.id}">
        <span style="min-width:70px;color:${currentColor};font-weight:600">${label}</span>
        <span style="min-width:100px;font-family:'DM Mono',monospace;color:var(--text1)">${fmtBRL(t.total_value)}</span>
        <span style="color:var(--text3);font-size:10px;margin-right:4px">→</span>
        <div style="display:flex;gap:2px;flex-wrap:wrap">
          <span style="font-size:9px;color:var(--accent);align-self:center;margin-right:2px">📥</span>${extOptions}
          <span style="font-size:9px;color:var(--green);align-self:center;margin-left:4px;margin-right:2px">💰</span>${incOptions}
        </div>
      </div>`;
    }).join('');

    return `<div style="background:var(--bg3);padding:4px 8px;font-size:10px;font-weight:700;color:var(--text3);border-bottom:1px solid var(--border)">${m}</div>${rows}`;
  }).join('');
}

async function invReclassifyTx(txId, newType, btnEl) {
  try {
    const r = await ff.invTxReclassify({ id: txId, new_tx_type: newType });
    if (!r.ok) { toast('Erro: ' + r.error); return; }

    // Update the row UI — highlight the active button
    const row = G(`inv-reclass-row-${txId}`);
    if (row) {
      const IS_EXT = new Set(['compra','aporte','venda','amortizacao']);
      const IS_INC = new Set(['dividendo','juros','jcp','cupom','taxa']);
      const color = IS_EXT.has(newType) ? 'var(--accent)' : IS_INC.has(newType) ? 'var(--green)' : 'var(--text3)';
      const TYPE_LABELS = { compra:'🟢 Compra', aporte:'➕ Aporte', venda:'🔴 Venda', amortizacao:'📉 Amortização',
        dividendo:'💰 Dividendo', juros:'💵 Juros', jcp:'🏦 JCP', cupom:'🎫 Cupom', taxa:'📋 Taxa' };
      row.querySelector('span').textContent = TYPE_LABELS[newType] || newType;
      row.querySelector('span').style.color = color;
      // Reset all buttons, highlight active
      row.querySelectorAll('button').forEach(b => {
        const bType = b.getAttribute('onclick')?.match(/'([^']+)'/)?.[1];
        if (bType === newType) {
          b.style.background = color; b.style.color = '#fff';
        } else {
          b.style.background = ''; b.style.color = '';
        }
      });
    }

    toast(`✅ Reclassificado para ${newType}`);

    // Reload inv data and refresh the patrimônio table
    await ff.invTxAll().then(txs => { _inv.txAll = txs; }).catch(() => {});
    if (currentPage === 'patrimonio') refreshPatrimonioTable();

  } catch(e) {
    toast('Erro ao reclassificar: ' + e.message);
  }
}
